class CNPC::__async_arg_AsyncTimerExpired final : public CExecutionArgument {
public:
    __async_arg_AsyncTimerExpired(int timerId, std::int64_t timerUid) : id(timerId), uid(timerUid) {}

    void CopyToPad(CExecutionArgumentPad* destination) const override {
        // The pad keeps a complete copy, vtable pointer included, as in the original.
        std::memcpy(destination->Buffer, static_cast<const void*>(this), sizeof(*this));
    }

    int id = 0;
    std::int64_t uid = 0;
};


