template <typename... Args>
std::string FormatLegacyReport(const char* format, Args... arguments) {
    std::array<char, 10240> buffer{};
    const int length = std::snprintf(buffer.data(), buffer.size(), format, arguments...);
    if (length < 0) {
        return {};
    }
    return std::string(buffer.data(), std::min(static_cast<std::size_t>(length), buffer.size() - 1));
}

bool IsZeroVector(const FVector& value) {
    constexpr double epsilon = 9.999999747378752e-06;
    return std::fabs(value.x) < epsilon && std::fabs(value.y) < epsilon && std::fabs(value.z) < epsilon;
}

std::size_t Msvc2015ShuffleIndex(std::size_t count) {
    if (count < 2) {
        return 0;
    }

    constexpr std::uint32_t randMask = 0x7fff;
    const std::uint32_t targetCount = static_cast<std::uint32_t>(count);
    std::uint32_t covered = 0;
    std::uint32_t value = 0;
    do {
        covered = (covered << 15) | randMask;
        value = (value << 15) | static_cast<std::uint32_t>(LegacyCrtRand());
    } while (covered != std::numeric_limits<std::uint32_t>::max() && covered < targetCount);

    return static_cast<std::size_t>(value % targetCount);
}

template <typename... Args>
std::u16string FormatLegacyReport(const std::u16string_view format, const Args&... arguments) {
    std::array<char16_t, 10240> buffer{};
    const int length = FormatUtf16To(buffer.data(), buffer.size(), format, arguments...);
    if (length < 0) {
        return {};
    }
    return std::u16string(buffer.data(), static_cast<std::size_t>(length));
}

const char* SafeFStringParameter(const char* value) { return value ? value : ""; }

std::string MakeFStringMarkup(
    int fstringId, const char* p1, const char* p2, const char* p3, const char* p4, const char* p5
) {
    std::string output = "<fstring p1=\"";
    output += SafeFStringParameter(p1);
    output += "\" p2=\"";
    output += SafeFStringParameter(p2);
    output += "\" p3=\"";
    output += SafeFStringParameter(p3);
    output += "\" p4=\"";
    output += SafeFStringParameter(p4);
    output += "\" p5=\"";
    output += SafeFStringParameter(p5);
    output += "\">";
    output += std::to_string(fstringId);
    output += "</fstring>";
    return output;
}

