std::u16string LottoFString(int id) { return Utf8ToUtf16(MakeFStringMarkup(id, "", "", "", "", "")); }

void AppendDecimal(std::u16string& output, int value) {
    const std::string decimal = std::to_string(value);
    for (const char byte : decimal) {
        output.push_back(static_cast<char16_t>(static_cast<unsigned char>(byte)));
    }
}

void AppendLottoNavigation(std::u16string& output, int state) {
    switch (state) {
        case 1:
            output += u"<A action=\"Link lotto003.htm\">";
            break;
        case 2:
            output += u"<A action=\"Link lotto004.htm\">";
            break;
        case 3:
            output += u"<A action=\"Link lotto002.htm\">";
            break;
        default:
            return;
    }
    output += LottoFString(1000170);
    output += u"</a><br>";
}

// The donor PDB supplies the original global names and
// std::xmap<std::pair<int,int>,int> source type. Current L2NPC.exe fixes the
// 0x20-byte map image at 0x02775e70, the lock at 0x02775e90, and signed
// lexicographic comparison of the two dword key fields.
std::map<std::pair<int, int>, int> g_script_global_map;
CIOCriticalSection g_script_global_map_lock;

std::uint32_t MPCCPartySidAt(const CSharedGeneralObjectData* mpcc, int index) {
    // CNPC::MPCC_GetPartyID at 0x004a1050 accepts
    // index == party_count and addresses +0x4c directly. At count 50
    // this reads the general-object end marker at +0x114.
    std::uint32_t sid = 0;
    const auto* const bytes = reinterpret_cast<const std::uint8_t*>(mpcc);
    std::memcpy(
        &sid, bytes + 0x4c + static_cast<std::ptrdiff_t>(index) * static_cast<std::ptrdiff_t>(sizeof(std::uint32_t)),
        sizeof(sid)
    );
    return sid;
}

std::int64_t AdjustF2PItemReward(const CSharedCreatureData& target, int itemClassId, std::int64_t count) {
    // Current L2NPC.exe CNPC::GiveItemEx at 0x004cae94 and CNPC::GiveItem
    // at 0x004cb1fc apply this only to adena while FreeOpenServer is on.
    if (!::g_bFreeOpenServer || itemClassId != 0x39) {
        return count;
    }

    const int initialQuestId = CScriptEngine::TLGetCurrentQuestID();
    const bool registeredQuest =
        (initialQuestId >= 0 && initialQuestId <= 0xfe) || (initialQuestId >= 0x280f && initialQuestId <= 0x2f0f);
    if (!registeredQuest) {
        std::int64_t cap = count;
        if (target.m_nLevel < 40) {
            cap = 1000;
        } else if (target.m_nLevel < 52) {
            cap = 4000;
        } else if (target.m_nLevel <= 60) {
            cap = 7000;
        }
        return std::min(count, cap);
    }

    for (const int penaltyQuestId : ::g_vF2PRewardPenaltyQuests) {
        if (CScriptEngine::TLGetCurrentQuestID() == penaltyQuestId) {
            return static_cast<std::int64_t>(static_cast<double>(count) * ::g_dF2PQuestRewardPenaltyPer);
        }
    }
    return count;
}

using PrivatePacketParam = CreateOnePrivatePacketHelper::PrivatePacketParam;

std::array<char16_t, 100> SanitizeNpcLogText(const char16_t* source) {
    std::array<char16_t, 100> output{};
    if (!source) {
        return output;
    }

    std::size_t length = 0;
    while (length < output.size() && source[length] != u'\0') {
        ++length;
    }
    // wcscpy_s(wchar_t[100], source) clears destination[0] when source does
    // not fit. The target then scans the resulting empty string.
    if (length == output.size()) {
        myInvalidParameterHandler(L"(L\"Buffer is too small\" && 0)", L"wcscpy_s", nullptr, 0, 0);
        return output;
    }

    std::copy_n(source, length + 1, output.begin());
    std::replace(output.begin(), output.begin() + static_cast<std::ptrdiff_t>(length), u',', u' ');
    return output;
}

std::string NpcLogTextUtf8(const char16_t* value) { return value ? Utf16ToUtf8(std::u16string_view(value)) : std::string{}; }

long long NpcLogInteger(std::int64_t value) { return static_cast<long long>(value); }

sOlympiadFieldInfo* GetOlympiadFieldInfo(int oneBasedFieldId) {
    SharedOlympiadInfo* const info = SharedOlympiadInfo::GetInfo();
    const unsigned int zeroBased = static_cast<unsigned int>(oneBasedFieldId) - 1u;
    if (zeroBased >= SharedOlympiadInfo::FIELD_COUNT) {
        return nullptr;
    }
    // Current EXE treats the published SharedOlympiadInfo mapping as a
    // process invariant and dereferences it directly for every valid field.
    return &info->arrFieldInfo[zeroBased];
}

char16_t* GetOlympiadPlayerName(int sharedCreatureIndex) {
    CCreatureFactory& factory = CCreatureFactory::Inst();
    CSPointer<CCreature> creature = factory.FindObjectSP(sharedCreatureIndex);
    if (!creature || !creature->IsPC()) {
        return EmptyScriptString();
    }
    // Current L2NPC.exe calls virtual CCreature::GetName (+0xb0),
    // instead of reaching into the shared record.
    return creature->GetName();
}

bool GetRandomSpawnPos(const FVector& source, CNPC* npc, FVector& destination) {
    L2_GUARD_FUNCTION();
    const double initialX = source.x;
    const double initialY = source.y;
    const double initialZ = source.z;
    int offsetX = LegacyCrtRand() % 300;
    offsetX += offsetX < 150 ? -200 : -100;
    int offsetY = LegacyCrtRand() % 300;
    offsetY += offsetY < 150 ? -200 : -100;

    const int sourceX = runtime::Win64CvttDoubleToInt32(initialX);
    const int sourceY = runtime::Win64CvttDoubleToInt32(initialY);
    const int sourceZ = runtime::Win64CvttDoubleToInt32(initialZ);
    const FVector candidate{
        static_cast<double>(
            runtime::Int32FromBits(static_cast<std::uint32_t>(sourceX) + static_cast<std::uint32_t>(offsetX))
        ),
        static_cast<double>(
            runtime::Int32FromBits(static_cast<std::uint32_t>(sourceY) + static_cast<std::uint32_t>(offsetY))
        ),
        static_cast<double>(sourceZ),
    };
    const double deltaX = candidate.x - source.x;
    const double deltaY = candidate.y - source.y;
    const double deltaZ = candidate.z - source.z;
    const double distance = std::sqrt(deltaX * deltaX + deltaY * deltaY + deltaZ * deltaZ);
    if (!l2geo::CWorld::Inst().IsValidPosition(static_cast<int>(candidate.x), static_cast<int>(candidate.y))) {
        return false;
    }

    bool floating = false;
    if (npc) {
        BaseSpawnDefine* const definition = npc->SpawnDefine();
        if (!definition->IsInTerritory(candidate, true)) {
            return false;
        }
        floating = npc->m_data->IsFlying();
    }

    CGeoData* const geodata = l2geo::CWorld::Inst().GetGeo();
    if (!geodata->MoveStraightTestBoth(source, candidate, distance, true, floating, 0)) {
        return false;
    }

    destination = candidate;
    return true;
}

void RecordPrivateCreate() {
    // Every shipping call site dereferences the process-global record
    // returned by NpcSpawnInfo::Inst() unconditionally.
    base_structure_detail::AtomicIncrement(&NpcSpawnInfo::Inst()->Npc_CreatePrivate);
}

std::u16string CopyCreatePrivatesText(const char16_t* value) {
    // Current L2NPC.exe 0x004a8eec uses a 0x1000-element wchar_t buffer,
    // wcsncpy_s(..., 0xfff), and then writes the final terminator itself.
    constexpr std::size_t kMaximumLength = 0x0fff;
    std::size_t length = 0;
    while (length < kMaximumLength && value[length] != u'\0') {
        ++length;
    }
    return std::u16string(std::u16string_view(value, length));
}

int ParseCreatePrivatesInt32(std::u16string_view value, std::size_t* parsedEnd = nullptr) {
    std::size_t offset = 0;
    while (offset < value.size()) {
        const char16_t character = value[offset];
        if (character != u' ' && character != u'\t' && character != u'\r' && character != u'\n' && character != u'\f' &&
            character != u'\v') {
            break;
        }
        ++offset;
    }

    bool negative = false;
    if (offset < value.size() && (value[offset] == u'+' || value[offset] == u'-')) {
        negative = value[offset] == u'-';
        ++offset;
    }

    const std::size_t digitsBegin = offset;
    std::uint64_t magnitude = 0;
    const std::uint64_t limit = negative ? 0x80000000ULL : 0x7fffffffULL;
    while (offset < value.size() && value[offset] >= u'0' && value[offset] <= u'9') {
        const unsigned digit = static_cast<unsigned>(value[offset] - u'0');
        if (magnitude > (limit - digit) / 10U) {
            magnitude = limit;
            do {
                ++offset;
            } while (offset < value.size() && value[offset] >= u'0' && value[offset] <= u'9');
            break;
        }
        magnitude = magnitude * 10U + digit;
        ++offset;
    }

    if (digitsBegin == offset) {
        if (parsedEnd) {
            *parsedEnd = 0;
        }
        return 0;
    }
    if (parsedEnd) {
        *parsedEnd = offset;
    }
    if (negative) {
        if (magnitude == 0x80000000ULL) {
            return std::numeric_limits<int>::min();
        }
        return -static_cast<int>(magnitude);
    }
    return static_cast<int>(magnitude);
}

bool EqualsCreatePrivatesSuffix(std::u16string_view left, std::u16string_view right) {
    if (left.size() != right.size()) {
        return false;
    }
    const auto lower = [](char16_t character) {
        return character >= u'A' && character <= u'Z' ? static_cast<char16_t>(character - u'A' + u'a') : character;
    };
    for (std::size_t index = 0; index < left.size(); ++index) {
        if (lower(left[index]) != lower(right[index])) {
            return false;
        }
    }
    return true;
}

int ParseCreatePrivatesRespawnTime(const std::u16string& value) {
    std::size_t parsedEnd = 0;
    int seconds = ParseCreatePrivatesInt32(runtime::StringView(value), &parsedEnd);
    while (parsedEnd < value.size() && value.c_str()[parsedEnd] == u' ') {
        ++parsedEnd;
    }

    std::uint32_t multiplier = 1;
    const std::u16string_view suffix = runtime::StringView(value).substr(parsedEnd);
    if (EqualsCreatePrivatesSuffix(suffix, u"min")) {
        multiplier = 60;
    }
    if (EqualsCreatePrivatesSuffix(suffix, u"hour")) {
        multiplier = 3600;
    }

    std::uint32_t bits = static_cast<std::uint32_t>(seconds);
    bits *= multiplier;
    std::memcpy(&seconds, &bits, sizeof(seconds));
    return seconds;
}

int LowCreatePrivatesClassId(std::int64_t value) {
    const std::uint32_t low = static_cast<std::uint32_t>(static_cast<std::uint64_t>(value));
    int result = 0;
    static_assert(sizeof(result) == sizeof(low));
    std::memcpy(&result, &low, sizeof(result));
    return result;
}

