constexpr std::uint32_t kManorEntryCount = 40;

bool IsValidManorId(int manorId) { return static_cast<std::uint32_t>(manorId) - 1U < kManorEntryCount; }

bool ValidateManorOrder(
    int manorId,
    int order,
    const char* entryName,
    [[maybe_unused]] int invalidManorLine,
    [[maybe_unused]] int invalidOrderLine,
    std::size_t& index
) {
    if (!IsValidManorId(manorId)) {
        // Log.Add(LOG_ERROR, L"[%S][%d]manor id[%d] is invalid", kNpcSourceFile, invalidManorLine, manorId)
        // Log.Add(LOG_ERROR,
        //     "[manor] Cannot read %s order %d: manor ID %d is outside 1..%u (NPC.cpp:%d).",
        //     entryName ? entryName : "<unknown>", order, manorId, static_cast<unsigned int>(kManorEntryCount),
        //     invalidManorLine)
        // Noise: shipping source-line coordinates do not locate this portable implementation.
        // L2_LOG_ERROR(Log,
        //     "[manor] Cannot read %s order %d: manor ID %d is outside 1..%u (NPC.cpp:%d).",
        //     entryName ? entryName : "<unknown>", order, manorId, static_cast<unsigned int>(kManorEntryCount),
        //     invalidManorLine)
        L2_LOG_ERROR(
            Log, "[manor] Cannot read %s order %d: manor ID %d is outside 1..%u.", entryName ? entryName : "<unknown>",
            order, manorId, static_cast<unsigned int>(kManorEntryCount)
        );
        return false;
    }

    const std::uint32_t orderIndex = static_cast<std::uint32_t>(order) - 1U;
    if (orderIndex >= kManorEntryCount) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%S][%d]manor id[%d], %S number[%d] "
        //     L"is invalid",
        //     kNpcSourceFile, invalidOrderLine, manorId, entryName, runtime::Int32FromBits(orderIndex)
        // )
        // Log.Add(LOG_ERROR,
        //     "[manor] Cannot read %s order %d in manor %d: order must be within 1..%u (NPC.cpp:%d).",
        //     entryName ? entryName : "<unknown>", order, manorId, static_cast<unsigned int>(kManorEntryCount),
        //     invalidOrderLine)
        // Noise: shipping source-line coordinates do not locate this portable implementation.
        // L2_LOG_ERROR(Log,
        //     "[manor] Cannot read %s order %d in manor %d: order must be within 1..%u (NPC.cpp:%d).",
        //     entryName ? entryName : "<unknown>", order, manorId, static_cast<unsigned int>(kManorEntryCount),
        //     invalidOrderLine)
        L2_LOG_ERROR(
            Log, "[manor] Cannot read %s order %d in manor %d: order must be within 1..%u.",
            entryName ? entryName : "<unknown>", order, manorId, static_cast<unsigned int>(kManorEntryCount)
        );
        return false;
    }

    index = orderIndex;
    return true;
}

// Current L2NPC.exe 0x0047e4f8, 0x0048872c,
// 0x00491294..0x004913ed, 0x00495e44..0x00495fd6, and
// 0x004a4af4..0x004abf81.
// The shipping MSVC sort is observable when two waypoints have the same
// distance. Keep its 32-element insertion threshold, median selection,
// three-way partition and heap fallback instead of inheriting the host STL's
// permutation.
struct WaypointDistanceLess {
    explicit WaypointDistanceLess(const FVector& value) : origin(value) {}

    bool operator()(const FVector& left, const FVector& right) const {
        const double rightX = origin.x - right.x;
        const double leftX = origin.x - left.x;
        const double leftY = origin.y - left.y;
        const double rightY = origin.y - right.y;
        const double rightZ = origin.z - right.z;
        const double leftZ = origin.z - left.z;
        return leftX * leftX + leftY * leftY + leftZ * leftZ < rightX * rightX + rightY * rightY + rightZ * rightZ;
    }

    FVector origin;
};

using WaypointIterator = AiWaypoints::iterator;
using WaypointDifference = AiWaypoints::difference_type;

void Msvc2015Median3(
    WaypointIterator first, WaypointIterator middle, WaypointIterator last, const WaypointDistanceLess& less
) {
    if (less(*middle, *first)) {
        std::iter_swap(middle, first);
    }
    if (less(*last, *middle)) {
        std::iter_swap(last, middle);
        if (less(*middle, *first)) {
            std::iter_swap(middle, first);
        }
    }
}

void Msvc2015GuessMedian(
    WaypointIterator first, WaypointIterator middle, WaypointIterator last, const WaypointDistanceLess& less
) {
    const WaypointDifference count = last - first;
    if (count > 40) {
        const WaypointDifference step = (count + 1) >> 3;
        const WaypointDifference twoStep = step << 1;
        Msvc2015Median3(first, first + step, first + twoStep, less);
        Msvc2015Median3(middle - step, middle, middle + step, less);
        Msvc2015Median3(last - twoStep, last - step, last, less);
        Msvc2015Median3(first + step, middle, last - step, less);
    } else {
        Msvc2015Median3(first, middle, last, less);
    }
}

std::pair<WaypointIterator, WaypointIterator> Msvc2015PartitionByPivot(
    WaypointIterator first, WaypointIterator pivotFirst, WaypointIterator last, const WaypointDistanceLess& less
) {
    WaypointIterator pivotLast = pivotFirst + 1;

    while (first < pivotFirst && !less(*(pivotFirst - 1), *pivotFirst) && !less(*pivotFirst, *(pivotFirst - 1))) {
        --pivotFirst;
    }
    while (pivotLast < last && !less(*pivotLast, *pivotFirst) && !less(*pivotFirst, *pivotLast)) {
        ++pivotLast;
    }

    WaypointIterator greaterFirst = pivotLast;
    WaypointIterator greaterLast = pivotFirst;
    for (;;) {
        for (; greaterFirst < last; ++greaterFirst) {
            if (less(*pivotFirst, *greaterFirst)) {
                continue;
            }
            if (less(*greaterFirst, *pivotFirst)) {
                break;
            }
            if (pivotLast != greaterFirst) {
                std::iter_swap(pivotLast, greaterFirst);
                ++pivotLast;
            } else {
                ++pivotLast;
            }
        }

        for (; first < greaterLast; --greaterLast) {
            const WaypointIterator previous = greaterLast - 1;
            if (less(*previous, *pivotFirst)) {
                continue;
            }
            if (less(*pivotFirst, *previous)) {
                break;
            }
            if (--pivotFirst != previous) {
                std::iter_swap(pivotFirst, previous);
            }
        }

        if (greaterLast == first && greaterFirst == last) {
            return {pivotFirst, pivotLast};
        }
        if (greaterLast == first) {
            if (pivotLast != greaterFirst) {
                std::iter_swap(pivotFirst, pivotLast);
            }
            ++pivotLast;
            std::iter_swap(pivotFirst, greaterFirst);
            ++pivotFirst;
            ++greaterFirst;
        } else if (greaterFirst == last) {
            --greaterLast;
            --pivotFirst;
            if (greaterLast != pivotFirst) {
                std::iter_swap(greaterLast, pivotFirst);
            }
            --pivotLast;
            std::iter_swap(pivotFirst, pivotLast);
        } else {
            --greaterLast;
            std::iter_swap(greaterFirst, greaterLast);
            ++greaterFirst;
        }
    }
}

std::pair<WaypointIterator, WaypointIterator> Msvc2015PartitionByMedian(
    WaypointIterator first, WaypointIterator last, const WaypointDistanceLess& less
) {
    WaypointIterator middle = first + ((last - first) >> 1);
    Msvc2015GuessMedian(first, middle, last - 1, less);
    return Msvc2015PartitionByPivot(first, middle, last, less);
}

void Msvc2015InsertionSort(WaypointIterator first, WaypointIterator last, const WaypointDistanceLess& less) {
    if (first == last) {
        return;
    }
    for (WaypointIterator middle = first; ++middle != last;) {
        FVector value(*middle);
        if (less(value, *first)) {
            WaypointIterator hole = middle;
            do {
                *hole = *(hole - 1);
                --hole;
            } while (hole != first);
            *first = value;
        } else {
            WaypointIterator hole = middle;
            WaypointIterator previous = hole;
            while (less(value, *--previous)) {
                *hole = *previous;
                hole = previous;
            }
            *hole = value;
        }
    }
}

void Msvc2015PushHeap(
    WaypointIterator first,
    WaypointDifference hole,
    WaypointDifference top,
    const FVector& value,
    const WaypointDistanceLess& less
) {
    for (WaypointDifference parent = (hole - 1) >> 1; top < hole && less(*(first + parent), value);
        parent = (hole - 1) >> 1) {
        *(first + hole) = *(first + parent);
        hole = parent;
    }
    *(first + hole) = value;
}

void Msvc2015PopHeapHole(
    WaypointIterator first,
    WaypointDifference hole,
    WaypointDifference bottom,
    const FVector& value,
    const WaypointDistanceLess& less
) {
    const WaypointDifference top = hole;
    WaypointDifference index = hole;
    const WaypointDifference maximumNonLeaf = (bottom - 1) >> 1;
    while (index < maximumNonLeaf) {
        index = 2 * index + 2;
        if (less(*(first + index), *(first + index - 1))) {
            --index;
        }
        *(first + hole) = *(first + index);
        hole = index;
    }
    if (index == maximumNonLeaf && bottom % 2 == 0) {
        *(first + hole) = *(first + bottom - 1);
        hole = bottom - 1;
    }
    Msvc2015PushHeap(first, hole, top, value, less);
}

void Msvc2015MakeHeap(WaypointIterator first, WaypointIterator last, const WaypointDistanceLess& less) {
    const WaypointDifference bottom = last - first;
    for (WaypointDifference hole = bottom >> 1; hole > 0;) {
        --hole;
        const FVector value(*(first + hole));
        Msvc2015PopHeapHole(first, hole, bottom, value, less);
    }
}

void Msvc2015SortHeap(WaypointIterator first, WaypointIterator last, const WaypointDistanceLess& less) {
    while (last - first >= 2) {
        --last;
        const FVector value(*last);
        *last = *first;
        Msvc2015PopHeapHole(first, 0, last - first, value, less);
    }
}

void Msvc2015SortWaypointsUnchecked(
    WaypointIterator first, WaypointIterator last, WaypointDifference ideal, const WaypointDistanceLess& less
) {
    for (;;) {
        if (last - first <= 32) {
            Msvc2015InsertionSort(first, last, less);
            return;
        }
        if (ideal <= 0) {
            Msvc2015MakeHeap(first, last, less);
            Msvc2015SortHeap(first, last, less);
            return;
        }

        const auto middle = Msvc2015PartitionByMedian(first, last, less);
        ideal = (ideal >> 1) + (ideal >> 2);
        if (middle.first - first < last - middle.second) {
            Msvc2015SortWaypointsUnchecked(first, middle.first, ideal, less);
            first = middle.second;
        } else {
            Msvc2015SortWaypointsUnchecked(middle.second, last, ideal, less);
            last = middle.first;
        }
    }
}

void Msvc2015SortWaypoints(AiWaypoints& waypoints, const FVector& origin) {
    const WaypointDistanceLess less(origin);
    Msvc2015SortWaypointsUnchecked(
        waypoints.begin(), waypoints.end(), static_cast<WaypointDifference>(waypoints.size()), less
    );
}

