char16_t* Wctime32(std::int32_t timestamp) {
    // _wctime32 rejects the negative half of its signed 32-bit range and
    // returns CRT-owned per-thread storage overwritten by the next call.
    if (timestamp < 0) {
        return nullptr;
    }
    const std::time_t value = static_cast<std::time_t>(timestamp);
    char text[32]{};
#if defined(_WIN32)
    if (::ctime_s(text, sizeof(text), &value) != 0) {
        return nullptr;
    }
#else
    if (::ctime_r(&value, text) == nullptr) {
        return nullptr;
    }
#endif
    thread_local std::array<char16_t, 32> buffer{};
    const std::size_t length = std::min(std::char_traits<char>::length(text), buffer.size() - 1);
    for (std::size_t index = 0; index < length; ++index) {
        buffer[index] = static_cast<unsigned char>(text[index]);
    }
    buffer[length] = u'\0';
    return buffer.data();
}

CSharedPledgeData* ResidenceOwnerPledge(const CNPC& npc) {
    // Castle_GetPledgeName/Castle_GetOwnerName in the current image cache the
    // residence ID, but call CResidenceData::Inst separately for the owner ID
    // and owner index. They also have no m_data null fallback.
    const int residenceId = npc.m_data->m_nResidenceID;
    const std::uint32_t ownerId = CResidenceData::Inst(residenceId).m_nResidenceOwnerID;
    const std::uint32_t ownerIndex = CResidenceData::Inst(residenceId).m_nResidenceOwnerIndex;
    if (ownerId == 0 || ownerIndex == UINT32_MAX) {
        return nullptr;
    }
    return CPledgeFactory::Inst().GetData(static_cast<int>(ownerIndex));
}

template <typename MemberPointer>
void AddNpcScriptFunction(
    ScriptTypeInfo& typeInfo,
    const wchar_t* name,
    MemberPointer function,
    ScriptTypeId returnType,
    std::initializer_list<ScriptTypeId> argumentTypes
) {
    auto* const descriptor = new ScriptFuncInfo_T<MemberPointer>(function);
    descriptor->Name(name);
    descriptor->SetRetType(&GetBuiltinScriptType(returnType));
    for (const ScriptTypeId argumentType : argumentTypes) {
        descriptor->AddArgType(&GetBuiltinScriptType(argumentType));
    }
    typeInfo.AddFuncInfo(descriptor);
}

