void RoomInfo::Clear() {
    // Current L2NPC.exe 0x0047e458. NPC.cpp:17933-17943. Index and status
    // survive the reset.
    L2_GUARD_FUNCTION();
    mMemberCount = 0;
    mTime = 0;
    mPartyID = 0;
    std::memset(mMemberList.data(), 0, sizeof(mMemberList));
}

void RoomInfo::SetParty(int taggedPartyId) {
    // Current L2NPC.exe 0x004a1d84. Matching source NPC.cpp:17845-17870.
    L2_GUARD_FUNCTION();
    const std::uint32_t bits = static_cast<std::uint32_t>(taggedPartyId);
    // if ((bits & 0xf8000000U) != 0x68000000U) {
    if ((bits & CLASS_MASK) != (SCLS_PARTY << CLASS_SHIFT)) {
        return;
    }
    CSharedPartyData* const party = CPartyFactory::Inst().GetData(static_cast<int>(bits & 0x000fffffU));
    if (!party) {
        return;
    }

    if (party->m_nOnlineMemberCount != 0) {
        std::uint32_t index = 0;
        do {
            mMemberList[static_cast<std::size_t>(index)] = runtime::Int32FromBits(party->m_OnlineMember[index].id);
            ++index;
        } while (index < party->m_nOnlineMemberCount);
    }
    mMemberCount = runtime::Int32FromBits(party->m_nOnlineMemberCount);
    mPartyID = party->m_nId;
    mTime = runtime::crt::Time32Now();
}

int RoomInfo::IsInRoom(CSharedCreatureData* creature) {
    // Current L2NPC.exe 0x0047e38c. Matching source NPC.cpp:17876-17894.
    L2_GUARD_FUNCTION();
    if (!creature) {
        return 0;
    }
    for (int index = 0; index < mMemberCount; ++index) {
        if (mMemberList[static_cast<std::size_t>(index)] == creature->m_nId) {
            return 1;
        }
    }
    return 0;
}

int RoomInfo::PartyChanged() {
    // Current L2NPC.exe 0x004a1ed0. Matching source NPC.cpp:17898-17930.
    L2_GUARD_FUNCTION();
    const std::uint32_t bits = static_cast<std::uint32_t>(mPartyID);
    CSharedPartyData* const party =
        // (bits & 0xf8000000U) == 0x68000000U ? CPartyFactory::Inst().GetData(static_cast<int>(bits & 0x000fffffU)) :
        // nullptr.
        (bits & CLASS_MASK) == (SCLS_PARTY << CLASS_SHIFT)
        ? CPartyFactory::Inst().GetData(static_cast<int>(bits & 0x000fffffU))
        : nullptr;
    if (!party || !party->m_bIsActive) {
        return 1;
    }
    const int memberCount = runtime::Int32FromBits(party->m_nOnlineMemberCount);
    if (memberCount != mMemberCount) {
        return 1;
    }

    for (int index = 0; index < memberCount; ++index) {
        User* const user = User::GetObjectW(runtime::Int32FromBits(party->m_OnlineMember[index].id));
        // The target ignores absent users and reports a change only when a
        // resolved user's shared record is not in the captured member set.
        if (user && !IsInRoom(user->m_data)) {
            return 1;
        }
    }
    return 0;
}

