int ItemIndexList::GetItemIndexWithMaxValue() {
    // Current L2NPC.exe 0x00495fd8. NPC.cpp:0x3c.
    L2_GUARD(m_lock);
    if (m_ItemIndexList.empty()) {
        return -1;
    }

    std::int64_t result = m_ItemIndexList.front();
    auto current = m_ItemIndexList.begin();
    while (current != m_ItemIndexList.end()) {
        if (result < *current) {
            result = *current;
        }
        ++current;
    }
    return runtime::Int32FromBits(static_cast<std::uint32_t>(result));
}

