bool CNPC::AddTimer(std::uint32_t milliseconds, int timerId) {
    // Current L2NPC.exe 0x004b16b8.
    L2_GUARD_FUNCTION();
    CheckTimerCount();

    std::int64_t uid = 0;
    {
        L2_GUARD(m_TimerLock);
        TimerSetting* setting = nullptr;
        const auto found = m_TimerSettingDB.find(timerId);
        const bool insertSetting = found == m_TimerSettingDB.end();
        if (insertSetting) {
            setting = new TimerSetting;
        } else {
            setting = found->second;
            if (setting->m_bTimerBlock) {
                return false;
            }
        }

        uid = TimerData::s_TimerUId.fetch_add(1, std::memory_order_seq_cst) + 1;
        auto* const data = new TimerData;
        data->m_MilliSec = runtime::Int32FromBits(milliseconds);
        data->m_StartMilliSec = runtime::Int32FromBits(runtime::GetTickCount());
        setting->m_TimerDataDB.emplace(uid, data);
        if (insertSetting) {
            m_TimerSettingDB.emplace(timerId, setting);
        }
        ++m_TimerCount;
    }

    g_nTimerCount.fetch_add(1, std::memory_order_seq_cst);
    CIOObject::AddTimer2(milliseconds, timerId, uid);
    return true;
}

