float CNPC::StaticObjectDistFromMe(CSharedStaticObjectData* target) {
    // Current L2NPC.exe 0x0046eab4. PDB NPC.cpp:7083.
    L2_GUARD_FUNCTION();
    const std::uintptr_t selfAddress = reinterpret_cast<std::uintptr_t>(this);
    if (selfAddress == 0U || !m_data) {
        // Log.Add(LOG_ERROR, L"[%s][%d] Who am I? at DistFromMe()", kNpcSourceFileW, 0x1cd4)
        // Log.Add(LOG_ERROR,
        //     "[NPC script] Cannot calculate static-object distance: NPC or its shared data is missing. Returning
        //     1000000.")
        L2_LOG_ERROR(
            Log,
            "[NPC script] Cannot calculate static-object distance: NPC or its shared data is missing; returning 1000000."
        );
        return 1000000.0F;
    }
    if (!target) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] target null at DistFromMe(). "
        //     L"I'm [%s]",
        //     kNpcSourceFileW, 0x1cda, npcName.c_str()
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC script] Cannot calculate static-object distance from NPC '%s': target is missing. Returning 1000000.",
        //     WideToUtf8(npcName).c_str())
        L2_LOG_ERROR(
            Log, "[NPC script] Cannot calculate static-object distance from NPC '%s': target is missing; returning 1000000.",
            npcName.c_str()
        );
        return 1000000.0F;
    }

    const FVector source = m_data->GetPos();
    const FVector destination = target->GetPos();
    const double dx = source.x - destination.x;
    const double dy = source.y - destination.y;
    const double dz = source.z - destination.z;
    return static_cast<float>(std::sqrt(dx * dx + dy * dy + dz * dz));
}

