void CNPC::ReportDesireToBuilder(int builderObjectId, PhysicalState physicalState) {
    // Current L2NPC.exe 0x0049994c. PDB NPC.cpp:5678.
    L2_GUARD_FUNCTION();
    TerritoryInfo* const territory = m_pSpawnDefine->GetTerritoryInfo();
    if (!territory) {
        // Log.Add(LOG_ERROR, L"[%s][%d] TerritoryInfo is NULL", kNpcSourceFileW, 0x169d)
        // Log.Add(LOG_ERROR,
        //     "[NPC actions] Cannot report actions for NPC %u to builder %u: spawn territory information is missing.",
        //     static_cast<unsigned int>(Id()), static_cast<unsigned int>(builderObjectId))
        L2_LOG_ERROR(
            Log, "[NPC actions] Cannot report actions for NPC %u to builder %u: spawn territory information is missing.",
            static_cast<unsigned int>(Id()), static_cast<unsigned int>(builderObjectId)
        );
        return;
    }

    CSharedCreatureData* const positionData = m_data;
    const FVector position = positionData->GetPos();
    const char16_t* const territoryName = territory->GetFirstTerritoryName();
    const char16_t* const npcName = GetName();
    const std::u16string npcInfo = FormatLegacyReport(
        u"----- Npc(%s) info -----\r\n"
        u"Server action type - %d\r\n"
        u"Pos(%d,%d,%d)\r\n"
        u"Territory(%s)",
        npcName, m_data->m_Action, static_cast<int>(position.x), static_cast<int>(position.y), static_cast<int>(position.z),
        territoryName
    );
    // Noise: The host-wide copy served only the old console format. The builder report remains unchanged.
    // const std::wstring npcInfoHost = Utf16ToWide(npcInfo)
    // The shipping body passes the completed report back as CLog's format.
    // Log.Add(LOG_NORMAL, npcInfoHost.c_str())
    // Log.Add(LOG_NORMAL,
    //     "[NPC actions] Action report for NPC '%s' (%u): server action %d, position (%d, %d, %d), territory '%s'.",
    //     WideToUtf8(npcName).c_str(), static_cast<unsigned int>(Id()), m_data->m_Action, static_cast<int>(position.x),
    //     static_cast<int>(position.y), static_cast<int>(position.z), WideToUtf8(territoryName).c_str())
    L2_LOG_INFO(
        Log, u"[NPC actions] Action report for NPC '%s' (%u): server action %d, position (%d, %d, %d), territory '%s'.",
        npcName, static_cast<unsigned int>(Id()), m_data->m_Action, static_cast<int>(position.x),
        static_cast<int>(position.y), static_cast<int>(position.z), territoryName
    );
    if (builderObjectId != 0) {
        g_ns.Send("cdS", 0x54, builderObjectId, npcInfo.c_str());
    }

    std::u16string desireReport;
    m_DesirePQ.Report(desireReport, physicalState);
    if (builderObjectId != 0) {
        g_ns.Send("cdS", 0x54, builderObjectId, desireReport.c_str());
    }
}

void CNPC::AddChoice(int code, int msgIndex) {
    // Current L2NPC.exe 0x0048b9c0. PDB NPC.cpp:11065.
    L2_GUARD_FUNCTION();
    if (th_ChoiceN >= 100) {
        // Current machine code supplies only the final maximum in R9. The
        // source-file and line conversions read absent varargs.
        // Log.Add(LOG_ERROR, L"[%s][%d] Maximum choices exceeded. max[%d]", 100)
        // Log.Add(LOG_ERROR,
        //     "[NPC UI] Cannot add choice %d (message %d) for NPC %u: choice count %d has reached the limit of 100. Choice
        //     ignored.", code, msgIndex, static_cast<unsigned int>(Id()), th_ChoiceN)
        L2_LOG_ERROR(
            Log,
            "[NPC UI] Cannot add choice %d (message %d) for NPC %u: choice count %d has reached the limit of 100; choice "
            "ignored.",
            code, msgIndex, static_cast<unsigned int>(Id()), th_ChoiceN
        );
        return;
    }

    const std::u16string choiceString = Utf8ToUtf16(MakeFStringMarkup(msgIndex, "", "", "", "", ""));

    int* categoryCount = nullptr;
    ChoiceData* categoryChoices = nullptr;
    switch (msgIndex % 10) {
        case 1:
            categoryCount = &th_ChoiceCount1;
            categoryChoices = th_Choices[0];
            break;
        case 2:
            categoryCount = &th_ChoiceCount2;
            categoryChoices = th_Choices[1];
            break;
        case 3:
            categoryCount = &th_ChoiceCount3;
            categoryChoices = th_Choices[2];
            break;
        case 4:
            categoryCount = &th_ChoiceCount4;
            categoryChoices = th_Choices[3];
            break;
        default:
            break;
    }

    if (categoryCount && categoryChoices) {
        ChoiceData& choice = categoryChoices[*categoryCount];
        choice.Choice = code;
        const std::size_t length = std::min<std::size_t>(choiceString.size(), std::size(choice.ChoiceString) - 1);
        std::copy_n(choiceString.data(), length, choice.ChoiceString);
        choice.ChoiceString[length] = u'\0';
        ++*categoryCount;
    }
    ++th_ChoiceN;
}

void CNPC::SRandNumbers(int maximumNumber, int requestedCount, int copies) {
    // Current L2NPC.exe 0x004b1fb4.
    L2_GUARD_FUNCTION();
    if (maximumNumber < 1 || requestedCount < 1 || copies < 1) {
        return;
    }

    // The shipping x64 IMUL keeps only the low 32 bits.
    const int total = runtime::MultiplyInt32Wrapping(maximumNumber, copies);
    if (total > requestedCount) {
        return;
    }

    m_vShuffleNumber.reserve(static_cast<std::size_t>(total));
    m_vShuffleNumber.resize(0);

    std::vector<int> values;
    int number = 1;
    for (int index = 0; index < total; ++index) {
        values.push_back(number);
        if (number == maximumNumber) {
            number = 0;
        }
        ++number;
    }
    for (std::size_t index = 1; index < values.size(); ++index) {
        std::swap(runtime::CheckedVectorAt(values, index), runtime::CheckedVectorAt(values, Msvc2015ShuffleIndex(index + 1)));
    }

    // Shipping scripts satisfy requestedCount == total. A larger count is
    // the target's own invalid out-of-range precondition, not a portable
    // recovery fallback.
    for (int index = 0; index < requestedCount; ++index) {
        m_vShuffleNumber.push_back(runtime::CheckedVectorAt(values, static_cast<std::size_t>(index)));
    }
}

int CNPC::SRandGetNumbers(int index) {
    // Current L2NPC.exe 0x00483c4c.
    L2_GUARD_FUNCTION();
    return index >= 0 && static_cast<std::size_t>(index) < m_vShuffleNumber.size()
        ? runtime::CheckedVectorAt(m_vShuffleNumber, static_cast<std::size_t>(index))
        : -1;
}

