void CNPC::Despawn() {
    // Current L2NPC.exe 0x004ac5a4. PDB NPC.cpp:8601.
    L2_GUARD_FUNCTION();
    if (runtime::raw_atomic::CompareExchangeI32(&m_nNpcDespawnCount, 1, 0) != 0) {
        // Noise: The atomic guard already makes repeated despawn requests a no-op. No second despawn packet is sent.
        // const std::wstring npcName = Utf16ToWide(GetName())
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] Invalid Despawn() "
        //     L"(npc[%s][%d]) called count[%d] ",
        //     kNpcSourceFileW, 0x2408, npcName.c_str(), static_cast<int>(Id()), 1
        // )
        return;
    }

    if (Deleted()) {
        return;
    }

    CNPC* partyRoot = CNPC::GetObjectW(m_data->m_BossID);
    if (!partyRoot && m_bBoss) {
        partyRoot = this;
    }
    if (partyRoot) {
        partyRoot->PartyDied(this);
    }

    g_ns.Send("cdd", 0x2e, static_cast<int>(Id()), m_data->index);
}

