void CNPC::ShowSetSiegeTime(
    CSharedCreatureData* target, char16_t* announcingPage, char16_t* siegePage, char16_t* scheduledPage
) {
    // Current L2NPC.exe 0x0049ed48.
    L2_GUARD_FUNCTION();
    const int residenceId = m_data->m_nResidenceID;
    // The target calls Inst twice in this order instead of retaining the
    // first returned record across both shared-state reads.
    const ResidenceState residenceState = CResidenceData::Inst(residenceId).m_ResidenceState;
    const std::int32_t nextSiege = CResidenceData::Inst(residenceId).m_NextSiege;
    char16_t* page = scheduledPage;
    const std::int32_t now = runtime::crt::Time32Now();
    if (nextSiege == 0 || nextSiege <= now) {
        page = residenceState == 0 ? announcingPage : siegePage;
    }
    ShowPage(target, page);
}

