void CNPC::ShowChoicePage(CSharedCreatureData* to, int nOption) {
    // Current L2NPC.exe 0x004af440.
    L2_GUARD_FUNCTION();
    if (th_ChoiceN < 2) {
        // Log.Add(LOG_ERROR, L"[%s][%d] th_ChoiceN < 2... shit", kNpcSourceFileW, 0x2fa3)
        // Log.Add(LOG_ERROR,
        //     "[NPC UI] NPC %u cannot show choices: only %d choices were prepared, at least 2 are required. Page not sent.",
        //     static_cast<unsigned int>(Id()), th_ChoiceN)
        L2_LOG_ERROR(
            Log,
            "[NPC UI] NPC %u cannot show choices: only %d choices were prepared, at least 2 are required; page not sent.",
            static_cast<unsigned int>(Id()), th_ChoiceN
        );
        return;
    }

    if (th_ChoiceN != th_ChoiceCount1 + th_ChoiceCount2 + th_ChoiceCount3 + th_ChoiceCount4) {
        // Log.Add(LOG_ERROR, L"[%s][%d] Total Count Error... shit", kNpcSourceFileW, 0x2fa9)
        // Log.Add(LOG_ERROR,
        //     "[NPC UI] NPC %u cannot show choices: total %d differs from category counts (%d, %d, %d, %d). Page not sent.",
        //     static_cast<unsigned int>(Id()), th_ChoiceN, th_ChoiceCount1, th_ChoiceCount2, th_ChoiceCount3,
        //     th_ChoiceCount4)
        L2_LOG_ERROR(
            Log,
            "[NPC UI] NPC %u cannot show choices: total %d differs from category counts (%d, %d, %d, %d); page not sent.",
            static_cast<unsigned int>(Id()), th_ChoiceN, th_ChoiceCount1, th_ChoiceCount2, th_ChoiceCount3, th_ChoiceCount4
        );
        return;
    }

    std::u16string page = u"<HTML><BODY>";
    const auto appendCategory = [&page, nOption](const ChoiceData* choices, int count, const char16_t* color) {
        for (int index = 0; index < count; ++index) {
            const ChoiceData& choice = choices[index];
            page += u"<font color=\"";
            page += color;
            page += u"\"><button icon=quest align=left action=\"bypass -h "
                    u"quest_choice?choice=";
            page += Utf8ToUtf16(std::to_string(choice.Choice));
            page += u"&option=";
            const std::u16string option = IntToXStr(nOption);
            page.append(runtime::StringView(option));
            page += u"\">";
            page += choice.ChoiceString;
            page += u"</button></font>";
        }
    };

    // Exact target order and colors: categories 2, 1, 4, then 3.
    appendCategory(th_Choices[1], th_ChoiceCount2, u"ffdd66");
    appendCategory(th_Choices[0], th_ChoiceCount1, u"bbaa88");
    appendCategory(th_Choices[3], th_ChoiceCount4, u"a62f31");
    appendCategory(th_Choices[2], th_ChoiceCount3, u"787878");
    page += u"</BODY></HTML>";

    if (page.size() >= 0x2329) {
        // Log.Add(LOG_ERROR, L"[%s][%d] Too Big HTML String", kNpcSourceFileW, 0x2fd1)
        // Log.Add(LOG_ERROR,
        //     "[NPC UI] NPC %u choice page contains %zu UTF-16 units, exceeding the 9000-unit limit. Page not sent.",
        //     static_cast<unsigned int>(Id()), page.size())
        L2_LOG_ERROR(
            Log, "[NPC UI] NPC %u choice page contains %zu UTF-16 units, exceeding the 9000-unit limit; page not sent.",
            static_cast<unsigned int>(Id()), page.size()
        );
        return;
    }

    // The target reads the recipient index before the NPC index while
    // preparing the varargs call.
    const int targetIndex = to->index;
    const int npcIndex = m_data->index;
    g_ns.Send("cddS", 0x11, npcIndex, targetIndex, page.c_str());
}

void CNPC::SellPreview(
    CSharedCreatureData* viewer,
    BuySellList* sellList,
    char16_t* ignoredPage [[maybe_unused]],
    char16_t* title,
    char16_t* requiredPage,
    char16_t* emptyListPage
) {
    // Current L2NPC.exe 0x0049c8ac.
    L2_GUARD_FUNCTION();
    if (!viewer || !sellList || !title || !requiredPage || !emptyListPage) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] ai sell function "
        //     L"parameter invalid",
        //     kNpcSourceFileW, 0x1f76
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC UI] NPC %u cannot show the sales preview: %s is missing. Request not sent.",
        //     static_cast<unsigned int>(Id()), !viewer ? "viewer" : !sellList ? "sale list" : !title ? "title" :
        //     !requiredPage ? "required page" : "empty-list page")
        L2_LOG_ERROR(
            Log, "[NPC UI] NPC %u cannot show the sales preview: %s is missing; request not sent.",
            static_cast<unsigned int>(Id()),
            !viewer             ? "viewer"
                : !sellList     ? "sale list"
                : !title        ? "title"
                : !requiredPage ? "required page"
                                : "empty-list page"
        );
        return;
    }
    const int instantZoneId = InstantZone_GetId();
    const int residenceId = Residence_GetId();
    CBuySellListCacheManager::map_key cacheKey(residenceId, instantZoneId, sellList);
    CPacketHelperEx<20480> cachePacket;
    bool cached = false;
    if (!CBuySellListCacheManager::IsCached(cacheKey)) {
        cached = CBuySellListCacheManager::Cache(cacheKey, cachePacket);
    }

    if (sellList->empty()) {
        ShowPage(viewer, emptyListPage);
        return;
    }

    const long long listToken = static_cast<long long>(reinterpret_cast<std::uintptr_t>(sellList));
    const int viewerIndex = viewer->index;
    const int npcIndex = m_data->index;
    if (cached) {
        g_ns.Send(
            "cddQSdb", 0x61, viewerIndex, npcIndex, listToken, title, 1, cachePacket.GetLength(), cachePacket.GetPacket()
        );
    } else {
        g_ns.Send("cddQSd", 0x61, viewerIndex, npcIndex, listToken, title, 0);
    }
}

void CNPC::ShowBuySell(CSharedCreatureData* viewer, BuySellList* sellList, BuySellList* buyList, float priceAdjustment) {
    // Current L2NPC.exe 0x0049468c.
    L2_GUARD_FUNCTION();
    if (!viewer || !sellList || !buyList) {
        return;
    }

    const int sellInstantZoneId = InstantZone_GetId();
    const int sellResidenceId = Residence_GetId();
    CBuySellListCacheManager::map_key sellKey(sellResidenceId, sellInstantZoneId, sellList);
    CPacketHelperEx<20480> sellCachePacket;
    CPacketHelperEx<20480> buyCachePacket;
    bool cachedSell = false;
    if (!CBuySellListCacheManager::IsCached(sellKey)) {
        cachedSell = CBuySellListCacheManager::Cache(sellKey, sellCachePacket);
    }

    const int buyInstantZoneId = InstantZone_GetId();
    const int buyResidenceId = Residence_GetId();
    CBuySellListCacheManager::map_key buyKey(buyResidenceId, buyInstantZoneId, buyList);
    bool cachedBuy = false;
    if (!CBuySellListCacheManager::IsCached(buyKey)) {
        cachedBuy = CBuySellListCacheManager::Cache(buyKey, buyCachePacket);
    }

    const long long sellToken = static_cast<long long>(reinterpret_cast<std::uintptr_t>(sellList));
    const long long buyToken = static_cast<long long>(reinterpret_cast<std::uintptr_t>(buyList));
    if (cachedSell && cachedBuy) {
        g_ns.Send(
            "cddQQfdbb", 0xd7, viewer->index, static_cast<int>(Id()), sellToken, buyToken,
            static_cast<double>(priceAdjustment), 2, sellCachePacket.GetLength(), sellCachePacket.GetPacket(),
            buyCachePacket.GetLength(), buyCachePacket.GetPacket()
        );
    } else if (cachedSell) {
        g_ns.Send(
            "cddQQfdb", 0xd7, viewer->index, static_cast<int>(Id()), sellToken, buyToken,
            static_cast<double>(priceAdjustment), 1, sellCachePacket.GetLength(), sellCachePacket.GetPacket()
        );
    } else if (cachedBuy) {
        g_ns.Send(
            "cddQQfdb", 0xd7, viewer->index, static_cast<int>(Id()), sellToken, buyToken,
            static_cast<double>(priceAdjustment), 1, buyCachePacket.GetLength(), buyCachePacket.GetPacket()
        );
    } else {
        g_ns.Send(
            "cddQQfd", 0xd7, viewer->index, static_cast<int>(Id()), sellToken, buyToken,
            static_cast<double>(priceAdjustment), 0
        );
    }
}

