        // Log.Add(LOG_ERROR,
        //     "[NPC script] NPC '%s' cannot become a player's talk target: player is missing. Change not queued.",
        //     WideToUtf8(npcName).c_str())
        L2_LOG_ERROR(
            Log, "[NPC script] NPC '%s' cannot become a player's talk target: player is missing; change not queued.",
            npcName.c_str()
        );
        return;
