int CNPC::DebugSay(char16_t* text) {
    L2_GUARD_FUNCTION();
    // Current L2NPC.exe 0x0046e5fc compares the process server type to DEV
    // and replaces the target's empty-string literal for a null argument.
    if (g_L2ServerType != L2ServerType::DEV) {
        return 0;
    }
    g_ns.Send("cddS", 4, 1, m_data->index, text ? text : u"");
    return 1;
}

void CNPC::SayInt(std::int64_t value) {
    L2_GUARD_FUNCTION();
    // Current L2NPC.exe 0x0046e6e4 formats with "%I64d".
    const std::u16string text = Utf8ToUtf16(std::to_string(value));
    g_ns.Send("cddS", 4, 1, m_data->index, text.c_str());
}

void CNPC::SayFloat(float value) {
    // Current L2NPC.exe 0x0048aa20 formats through the target's
    // 100-wchar_t "%f" helper.
    L2_GUARD_FUNCTION();
    std::array<char, 100> text{};
    const int length = std::snprintf(text.data(), text.size(), "%f", static_cast<double>(value));
    const std::u16string wideText = Utf8ToUtf16(length > 0 ? std::string_view(text.data()) : std::string_view{});
    g_ns.Send("cddS", 4, 1, m_data->index, wideText.c_str());
}

int CNPC::Shout(char16_t* text) {
    // Current L2NPC.exe 0x0048ab1c.
    L2_GUARD_FUNCTION();
    if (reinterpret_cast<std::uintptr_t>(text) < kTargetStringPointerMinimum) {
        // Log.Add(LOG_ERROR, L"[%s][%d] Invalid Pointer[0x%p]", kNpcSourceFileW, 0x1d0c, static_cast<void*>(text))
        // Log.Add(LOG_ERROR,
        //     "[NPC script] NPC %u cannot shout: text pointer %p is below the valid string-address range. Request not
        //     sent.", static_cast<unsigned int>(Id()), static_cast<void*>(text))
        L2_LOG_ERROR(
            Log,
            "[NPC script] NPC %u cannot shout: text pointer %p is below the valid string-address range; request not sent.",
            static_cast<unsigned int>(Id()), static_cast<void*>(text)
        );
        return 0;
    }
    g_ns.Send("cddS", 4, 2, m_data->index, text);
    return 1;
}

void CNPC::ShoutEx(char16_t* text, int value) {
    // Current L2NPC.exe 0x0049b870.
    L2_GUARD_FUNCTION();
    if (reinterpret_cast<std::uintptr_t>(text) < kTargetStringPointerMinimum) {
        // Log.Add(LOG_ERROR, L"[%s][%d] Invalid Pointer[0x%p]", kNpcSourceFileW, 0x1d30, static_cast<void*>(text))
        // Log.Add(LOG_ERROR,
        //     "[NPC script] NPC %u cannot send extended shout (value %d): text pointer %p is below the valid string-address
        //     range, request not sent.", static_cast<unsigned int>(Id()), value, static_cast<void*>(text))
        L2_LOG_ERROR(
            Log,
            "[NPC script] NPC %u cannot send extended shout (value %d): text pointer %p is below the valid string-address "
            "range; request not sent.",
            static_cast<unsigned int>(Id()), value, static_cast<void*>(text)
        );
        return;
    }
    const int lookupIndex = m_data->index;
    g_ns.Send("cddSd", 0x67, CCreatureFactory::Inst().GetIdByIndex(lookupIndex), m_data->index, text, value);
}

