        //     static_cast<unsigned int>(Id()), index, !delays ? "delay list is missing" : "index must be within 1..list
        //     size", delays ? delays->size() : std::size_t{0})
        L2_LOG_ERROR(
            Log, "[NPC route] NPC %u cannot read waypoint delay at index %d: %s (list size %zu); returning 0.",
            static_cast<unsigned int>(Id()), index, !delays ? "delay list is missing" : "index must be within 1..list size",
            delays ? delays->size() : std::size_t{0}
        );
