void CNPC::FHTML_SetFStr(
    CFHTML* html,
    char16_t* key,
    int fstringId,
    char16_t* parameter0,
    char16_t* parameter1,
    char16_t* parameter2,
    char16_t* parameter3,
    char16_t* parameter4
) {
    L2_GUARD_FUNCTION();
    // Current L2NPC.exe 0x00471b04 calls _snwprintf_s with _TRUNCATE into
    // this uninitialized 0x400-WCHAR stack buffer and passes the result
    // directly to CFHTML::Set. In particular, it has no nullable-parameter
    // substitution and never converts the strings through UTF-8.
    std::array<char16_t, 0x400> markup;
#if defined(_MSC_VER)
    static_assert(sizeof(wchar_t) == sizeof(char16_t));
    ::_snwprintf_s(
        reinterpret_cast<wchar_t*>(markup.data()), markup.size(), _TRUNCATE,
        L"<fstring p1=\"%s\" p2=\"%s\" p3=\"%s\" p4=\"%s\" p5=\"%s\">%d</fstring>",
        reinterpret_cast<const wchar_t*>(parameter0), reinterpret_cast<const wchar_t*>(parameter1),
        reinterpret_cast<const wchar_t*>(parameter2), reinterpret_cast<const wchar_t*>(parameter3),
        reinterpret_cast<const wchar_t*>(parameter4), fstringId
    );
#else
    // Host adapter for the same fixed UTF-16 formatting operation. Copying
    // code units directly keeps the target's 0x3ff-unit truncation point
    // on platforms where wchar_t is four bytes.
    std::size_t length = 0;
    bool truncated = false;
    const auto append = [&](const char16_t* text) {
        if (truncated) {
            return;
        }
        while (*text != u'\0') {
            if (length + 1 == markup.size()) {
                truncated = true;
                return;
            }
            markup[length++] = *text++;
        }
    };

    append(u"<fstring p1=\"");
    append(parameter0);
    append(u"\" p2=\"");
    append(parameter1);
    append(u"\" p3=\"");
    append(parameter2);
    append(u"\" p4=\"");
    append(parameter3);
    append(u"\" p5=\"");
    append(parameter4);
    append(u"\">");

    std::array<char, 16> decimal;
    const int decimalLength = std::snprintf(decimal.data(), decimal.size(), "%d", fstringId);
    if (!truncated) {
        for (int index = 0; index < decimalLength; ++index) {
            if (length + 1 == markup.size()) {
                truncated = true;
                break;
            }
            markup[length++] = static_cast<char16_t>(static_cast<unsigned char>(decimal[static_cast<std::size_t>(index)]));
        }
    }
    append(u"</fstring>");
    markup[length] = u'\0';
#endif
    html->Set(key, markup.data());
}

