void CNPC::RegisterSiege(CSharedCreatureData* talker) {
    L2_GUARD_FUNCTION();
    // Current L2NPC.exe 0x00471e04.
    if (!talker) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(
        //     LOG_ERROR,
        //     L"Script:GetPledgeSkillLevel : Talker is "
        //     L"NULL!!!, npc[%s]",
        //     npcName.c_str()
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC siege] NPC '%s' cannot register a siege attacker: requesting creature is missing. Request not sent.",
        //     WideToUtf8(npcName).c_str())
        L2_LOG_ERROR(
            Log, "[NPC siege] NPC '%s' cannot register a siege attacker: requesting creature is missing; request not sent.",
            npcName.c_str()
        );
        return;
    }

    const int residenceId = m_data->m_nResidenceID;
    const int pledgeId = talker->m_nPledgeID;

    const auto dispatchReply = [&](int reply, [[maybe_unused]] int failureLine) {
        CNPCEvent* const event = CNPCEventFactory::CreateManageCastleSiegeEvent(this, talker, 1, reply);
        if (!event) {
            // Log.Add(LOG_ERROR, L"[%s][%d] Event failed", kNpcSourceFileW, failureLine)
            // Log.Add(LOG_ERROR,
            //     "[NPC siege] Cannot create attacker registration reply %d for residence %d, pledge %d on NPC %u. AI
            //     callback not delivered (NPC.cpp:%d).", reply, residenceId, pledgeId, static_cast<unsigned int>(Id()),
            //     failureLine)
            // Noise: shipping line numbers do not locate the portable implementation.
            // L2_LOG_ERROR(Log,
            //     "[NPC siege] Cannot create attacker registration reply %d for residence %d, pledge %d on NPC %u. AI
            //     callback not delivered (NPC.cpp:%d).", reply, residenceId, pledgeId, static_cast<unsigned int>(Id()),
            //     failureLine)
            L2_LOG_ERROR(
                Log,
                "[NPC siege] Cannot create attacker registration reply %d for residence %d, pledge %d on NPC %u; AI "
                "callback not delivered.",
                reply, residenceId, pledgeId, static_cast<unsigned int>(Id())
            );
            return;
        }
        HandleEvent(event);
        L2_RELEASE(event, ObjectRefType::CreateDelete);
    };

    if (pledgeId == 0 || !talker->m_bPledgeMaster) {
        dispatchReply(4, 0x29c4);
        return;
    }

    const ResidenceState state = CResidenceData::Inst(residenceId).m_ResidenceState;
    if (state == RS_ANNOUNCING) {
        dispatchReply(2, 0x29d4);
    } else if (state == RS_REGISTRATION || state == RS_TYPE_CHANGE) {
        CSharedCreatureData* const sendData = m_data;
        const int talkerIndex = talker->index;
        const int sourceIndex = sendData->index;
        g_ns.Send("cddddd", 0x0c, sourceIndex, talkerIndex, residenceId, pledgeId, 1);
    } else {
        dispatchReply(3, 0x29e3);
    }
}

