void CNPC::ShowSysMsgToParty2(
    CSharedPartyData* party, int routingValue, int messageId, int argument0, int argument1, int argument2, int argument3
) {
    L2_GUARD_FUNCTION();
    // Current L2NPC.exe 0x0046eea8.
    if (!party) {
        return;
    }
    CPacketHelperEx<0x5000> packet;
    const int packetLength = packet.Assemble("cdddddd", 0x62, messageId, 2, argument0, argument1, argument2, argument3);
    if (packetLength > 0) {
        g_ns.Send(
            "cdddb", 0x6e, static_cast<int>(party->m_nId), routingValue, packetLength, packetLength,
            static_cast<const void*>(packet.GetPacket())
        );
    }
}

