void MiniGameFuncHelper(eMiniGameAgitFunc function, CNPC* npc, CSharedCreatureData* creature, int argument) {
    // Current L2NPC.exe 0x0047d2ec.
    L2_GUARD_FUNCTION();
    if (!creature) {
        const std::string npcName = Utf16ToUtf8(npc->GetName());
        // Log.Add(
        //     LOG_ERROR, L"[%s][%d] pUser==NULL npc[%s] func(%d)", kNpcSourceFileW, 0x43e5, npcName.c_str(),
        //     static_cast<int>(function)
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC minigame] NPC '%s' cannot request operation %d (argument %d): target creature is missing. Request not
        //     sent.", WideToUtf8(npcName).c_str(), static_cast<int>(function), argument)
        L2_LOG_ERROR(
            Log,
            "[NPC minigame] NPC '%s' cannot request operation %d (argument %d): target creature is missing; request not "
            "sent.",
            npcName.c_str(), static_cast<int>(function), argument
        );
        return;
    }
    CSharedCreatureData* const npcData = npc->m_data;
    const int creatureIndex = creature->index;
    const int npcIndex = npcData->index;
    const int residenceId = npcData->m_nResidenceID;
    g_ns.Send("ccdddd", 0x84, static_cast<int>(function), residenceId, npcIndex, creatureIndex, argument);
}

