int CNPC::GetDirection(CSharedCreatureData* creature) {
    L2_GUARD_FUNCTION();
    // Current L2NPC.exe 0x0046d974.
    if (!creature) {
        // Log.Add(LOG_ERROR, L"[%s][%d] spCreature is null", kNpcSourceFileW, 0x1a2d)
        // Log.Add(LOG_ERROR,
        //     "[NPC script] NPC %u cannot calculate relative direction: target creature is missing. Returning 0.",
        //     static_cast<unsigned int>(Id()))
        L2_LOG_ERROR(
            Log, "[NPC script] NPC %u cannot calculate relative direction: target creature is missing; returning 0.",
            static_cast<unsigned int>(Id())
        );
        return 0;
    }

    const double targetY = creature->m_Pos.y;
    const double sourceY = m_data->m_Pos.y;
    const double targetX = creature->m_Pos.x;
    const double sourceX = m_data->m_Pos.x;
    constexpr double kTau = 6.283185307179586;
    const int targetHeading =
        runtime::Win64CvttDoubleToInt32(std::atan2(targetY - sourceY, targetX - sourceX) * 65535.0 / kTau);
    const int sourceYaw = m_data->GetDirByInt();
    const int relativeHeading = (targetHeading - sourceYaw) & 0xffff;
    return runtime::Win64CvttDoubleToInt32(static_cast<double>(relativeHeading) * 360.0 / 65535.0);
}

int CNPC::GetDirectionToTarget(CSharedCreatureData* creature) {
    L2_GUARD_FUNCTION();
    // Current L2NPC.exe 0x0046da98.
    if (!creature) {
        // Log.Add(LOG_ERROR, L"[%s][%d] spCreature is null", kNpcSourceFileW, 0x1a42)
        // Log.Add(LOG_ERROR,
        //     "[NPC script] NPC %u cannot calculate direction to the target: target creature is missing. Returning 0.",
        //     static_cast<unsigned int>(Id()))
        L2_LOG_ERROR(
            Log, "[NPC script] NPC %u cannot calculate direction to the target: target creature is missing; returning 0.",
            static_cast<unsigned int>(Id())
        );
        return 0;
    }

    const double targetY = creature->m_Pos.y;
    const double sourceY = m_data->m_Pos.y;
    const double targetX = creature->m_Pos.x;
    const double sourceX = m_data->m_Pos.x;
    constexpr double kTau = 6.283185307179586;
    const int targetHeading =
        runtime::Win64CvttDoubleToInt32(std::atan2(targetY - sourceY, targetX - sourceX) * 65535.0 / kTau);
    return runtime::Win64CvttDoubleToInt32(static_cast<double>(targetHeading & 0xffff) * 360.0 / 65535.0);
}

