int CNPC::GetMemoCount(CSharedCreatureData* creature) {
    L2_GUARD_FUNCTION();
    // Current L2NPC.exe 0x0046f994.
    if (!creature) {
        return 0;
    }

    int count = 0;
    for (const MemoStruct& memo : creature->m_Memo) {
        if (memo.nQuestID > 0) {
            ++count;
        }
    }
    return count;
}

