int CNPC::IsMemberOfParty(CSharedCreatureData* creature, CSharedPartyData* party) {
    L2_GUARD_FUNCTION();
    // Current L2NPC.exe 0x00476e5c scans all seven online-member slots,
    // regardless of m_nOnlineMemberCount.
    if (!creature || !party) {
        return 0;
    }
    for (const IdIndexPair& member : party->m_OnlineMember) {
        if (member.id == static_cast<std::uint32_t>(creature->m_nId)) {
            return 1;
        }
    }
    return 0;
}

