std::int64_t CNPC::OwnItemCountEx(CSharedCreatureData* creature, int itemClassId, int enchant) {
    // Current L2NPC.exe 0x004b4ca8.
    L2_GUARD_FUNCTION();
    if (!creature) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(LOG_ERROR, L"[%s][%d] OwnItemCountEx(c=null) I'm [%s]", kNpcSourceFileW, 0x21b2, npcName.c_str())
        // Log.Add(LOG_ERROR,
        //     "[NPC script] NPC '%s' cannot count item class %d with enchantment filter %d: target creature is missing.
        //     returning 0.", WideToUtf8(npcName).c_str(), itemClassId, enchant)
        L2_LOG_ERROR(
            Log,
            "[NPC script] NPC '%s' cannot count item class %d with enchantment filter %d: target creature is missing; "
            "returning 0.",
            npcName.c_str(), itemClassId, enchant
        );
        return 0;
    }

    std::uint64_t count = 0;
    {
        CInventory inventory;
        const bool isUser = creature->m_bIsUser;
        const int creatureIndex = creature->index;
        inventory.SetIndex(creatureIndex, isUser);
        L2_READ_GUARD(inventory);
        CSharedItemData* item = inventory.GetFirst();
        while (item) {
            CSharedItemData* const next = item->Next();
            if (item->m_bIsVariation) {
                item = next;
                continue;
            }
            const bool enchantMatches = enchant < 0 || item->GetEnchanted() == enchant;
            if (item->m_nClassID == itemClassId && enchantMatches) {
                count += item->IsStackable() ? static_cast<std::uint64_t>(item->m_nCount) : UINT64_C(1);
            }
            item = next;
        }
    }

    std::int64_t result = 0;
    static_assert(sizeof(result) == sizeof(count));
    std::memcpy(&result, &count, sizeof(result));
    return result;
}

CSharedItemData* CNPC::GetItemData(CSharedCreatureData* creature, int itemClassId) {
    // Current L2NPC.exe 0x004b4e70.
    L2_GUARD_FUNCTION();
    if (!creature) {
        // Log.Add(LOG_ERROR, L"[%s][%d] GetItemData(c=null)", kNpcSourceFileW, 0x22eb)
        // Log.Add(LOG_ERROR,
        //     "[NPC script] NPC %u cannot find inventory data for item class %d: target creature is missing. Returning no
        //     item.", static_cast<unsigned int>(Id()), itemClassId)
        L2_LOG_ERROR(
            Log,
            "[NPC script] NPC %u cannot find inventory data for item class %d: target creature is missing; returning no "
            "item.",
            static_cast<unsigned int>(Id()), itemClassId
        );
        return nullptr;
    }

    CSharedItemData* result = nullptr;
    {
        CInventory inventory;
        const bool isUser = creature->m_bIsUser;
        const int creatureIndex = creature->index;
        inventory.SetIndex(creatureIndex, isUser);
        L2_READ_GUARD(inventory);
        for (CSharedItemData* item = inventory.GetFirst(); item; item = item->Next()) {
            if (item->m_nClassID == itemClassId && !item->m_bIsVariation) {
                result = item;
                break;
            }
        }
    }
    return result;
}

int CNPC::UseItem(int itemIndex) {
    // Current L2NPC.exe 0x004b517c. CNPC::Set stores the same current
    // shared-creature pointer at target +0x20 and +0x720. The former owns
    // the inventory cursor and the latter supplies this packet's ID/index.
    L2_GUARD_FUNCTION();
    const int targetObjectId = CCreatureFactory::Inst().GetIdByIndex(sm->index);
    bool hasItem = false;
    {
        CInventory inventory;
        inventory.SetIndex(m_data->index, m_data->m_bIsUser);
        L2_READ_GUARD(inventory);
        hasItem = inventory.Have(itemIndex);
    }
    if (!hasItem) {
        return 0;
    }
    g_ns.Send("cddd", 0x1c, targetObjectId, sm->index, itemIndex);
    return 1;
}

int CNPC::UseCategoryItem(int categoryId) {
    // Current L2NPC.exe 0x004b6884.
    L2_GUARD_FUNCTION();
    const int targetObjectId = CCreatureFactory::Inst().GetIdByIndex(sm->index);
    int itemClassId = -1;
    {
        CInventory inventory;
        inventory.SetIndex(m_data->index, m_data->m_bIsUser);
        L2_READ_GUARD(inventory);
        CSharedItemData* item = inventory.GetFirst();
        while (item) {
            CSharedItemData* const next = item->Next();
            if (!item->m_bIsVariation && CCategoryDataDB::Inst().IsInCategory(item->m_nClassID, categoryId)) {
                itemClassId = item->m_nClassID;
                break;
            }
            item = next;
        }
    }
    if (itemClassId == -1) {
        return 0;
    }
    g_ns.Send("cddd", 0x1c, targetObjectId, sm->index, itemClassId);
    return 1;
}

int CNPC::GiveItem(CSharedCreatureData* creature, int itemClassId, std::int64_t count, bool normalItem) {
    // Current L2NPC.exe 0x004cb1fc. The embedded signature supplies the
    // name because this current-revision helper is absent from the donor PDB.
    L2_GUARD_FUNCTION();
    if (!creature) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(LOG_ERROR, L"Script:GiveItem1 :  c==NULL!!!, npc[%s]", npcName.c_str())
        // Log.Add(LOG_ERROR,
        //     "[NPC reward] NPC '%s' cannot give item class %d, count %lld: recipient creature is missing. Reward not
        //     queued, returning 0.", WideToUtf8(npcName).c_str(), itemClassId, static_cast<long long>(count))
        L2_LOG_ERROR(
            Log,
            "[NPC reward] NPC '%s' cannot give item class %d, count %lld: recipient creature is missing; reward not queued, "
            "returning 0.",
            npcName.c_str(), itemClassId, static_cast<long long>(count)
        );
        return 0;
    }
    if (count > 0 && itemClassId != 0) {
        const std::int64_t adjustedCount = AdjustF2PItemReward(*creature, itemClassId, count);
        const int questId = CScriptEngine::TLGetCurrentQuestID();
        const ItemManip item(questId, itemClassId, adjustedCount, 0, 0, 0, true);
        AtomicJobCompositor* const compositor = Singleton<ThreadLocalStorage<AtomicJobCompositor, 8>>::inst();
        const int queueIndex = creature->index;
        compositor->AddItemManip(queueIndex, item, normalItem);
    }
    return 1;
}

