bool CNPC::SetAIParameter(CSharedCreatureData* creature, int type, int value) {
    // Current L2NPC.exe 0x004a3394.
    L2_GUARD_FUNCTION();
    if (!creature) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(LOG_ERROR, L"[%s][%d] Target(c=null) I'm [%s]", kNpcSourceFileW, 0x5105, npcName.c_str())
        // Log.Add(LOG_ERROR,
        //     "[NPC AI] NPC '%s' cannot set AI parameter %d to %d: target creature is missing. Returning false.",
        //     WideToUtf8(npcName).c_str(), type, value)
        L2_LOG_ERROR(
            Log, "[NPC AI] NPC '%s' cannot set AI parameter %d to %d: target creature is missing; returning false.",
            npcName.c_str(), type, value
        );
        return false;
    }
    CCreature* const targetObject = CCreature::GetObjectW(CCreatureFactory::Inst().GetIdByIndex(creature->index));
    CNPC* const target = targetObject && targetObject->IsNPC() ? targetObject->CastNPC() : nullptr;
    if (!target) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] Target(c=invalid or c=not npc) "
        //     L"I'm [%s]",
        //     kNpcSourceFileW, 0x510d, npcName.c_str()
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC AI] NPC '%s' cannot set AI parameter %d to %d for creature %u: %s. Returning false.",
        //     WideToUtf8(npcName).c_str(), type, value, static_cast<unsigned int>(creature->m_nId), !targetObject ? "target
        //     object is unavailable" : "target cannot be used as an NPC")
        L2_LOG_ERROR(
            Log, "[NPC AI] NPC '%s' cannot set AI parameter %d to %d for creature %u: %s; returning false.",
            npcName.c_str(), type, value, static_cast<unsigned int>(creature->m_nId),
            !targetObject ? "target object is unavailable" : "target cannot be used as an NPC"
        );
        return false;
    }
    if (type < 0 || type >= 10) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(LOG_ERROR, L"[%s][%d] Type must be 0~9 I'm [%s]", kNpcSourceFileW, 0x5135, npcName.c_str())
        // Log.Add(LOG_ERROR,
        //     "[NPC AI] NPC '%s' cannot set AI parameter %d to %d for creature %u: parameter index is outside 0..9.
        //     returning false.", WideToUtf8(npcName).c_str(), type, value, static_cast<unsigned int>(creature->m_nId))
        L2_LOG_ERROR(
            Log,
            "[NPC AI] NPC '%s' cannot set AI parameter %d to %d for creature %u: parameter index is outside 0..9; returning "
            "false.",
            npcName.c_str(), type, value, static_cast<unsigned int>(creature->m_nId)
        );
        return false;
    }
    switch (type) {
        case 0:
            target->i_ai0 = value;
            return true;
        case 1:
            target->i_ai1 = value;
            return true;
        case 2:
            target->i_ai2 = value;
            return true;
        case 3:
            target->i_ai3 = value;
            return true;
        case 4:
            target->i_ai4 = value;
            return true;
        case 5:
            target->i_ai5 = value;
            return true;
        case 6:
            target->i_ai6 = value;
            return true;
        case 7:
            target->i_ai7 = value;
            return true;
        case 8:
            target->i_ai8 = value;
            return true;
        case 9:
            target->i_ai9 = value;
            return true;
        default:
            break;
    }
    return false;
}

int CNPC::GetAIParameter(CSharedCreatureData* creature, int type) {
    // Current L2NPC.exe 0x004a3638.
    L2_GUARD_FUNCTION();
    if (!creature) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(LOG_ERROR, L"[%s][%d] Target(c=null) I'm [%s]", kNpcSourceFileW, 0x5145, npcName.c_str())
        // Log.Add(LOG_ERROR,
        //     "[NPC AI] NPC '%s' cannot read AI parameter %d: target creature is missing. Returning -1.",
        //     WideToUtf8(npcName).c_str(), type)
        L2_LOG_ERROR(
            Log, "[NPC AI] NPC '%s' cannot read AI parameter %d: target creature is missing; returning -1.",
            npcName.c_str(), type
        );
        return -1;
    }
    CCreature* const targetObject = CCreature::GetObjectW(CCreatureFactory::Inst().GetIdByIndex(creature->index));
    CNPC* const target = targetObject && targetObject->IsNPC() ? targetObject->CastNPC() : nullptr;
    if (!target) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] Target(c=invalid or c=not npc) "
        //     L"I'm [%s]",
        //     kNpcSourceFileW, 0x514d, npcName.c_str()
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC AI] NPC '%s' cannot read AI parameter %d for creature %u: %s. Returning 1.",
        //     WideToUtf8(npcName).c_str(), type, static_cast<unsigned int>(creature->m_nId), !targetObject ? "target object
        //     is unavailable" : "target cannot be used as an NPC")
        L2_LOG_ERROR(
            Log, "[NPC AI] NPC '%s' cannot read AI parameter %d for creature %u: %s; returning 1.",
            npcName.c_str(), type, static_cast<unsigned int>(creature->m_nId),
            !targetObject ? "target object is unavailable" : "target cannot be used as an NPC"
        );
        return 1;
    }
    if (type < 0 || type >= 10) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(LOG_ERROR, L"[%s][%d] Type must be 0~9 I'm [%s]", kNpcSourceFileW, 0x5176, npcName.c_str())
        // Log.Add(LOG_ERROR,
        //     "[NPC AI] NPC '%s' cannot read AI parameter %d for creature %u: parameter index is outside 0..9. Returning
        //     -1.", WideToUtf8(npcName).c_str(), type, static_cast<unsigned int>(creature->m_nId))
        L2_LOG_ERROR(
            Log,
            "[NPC AI] NPC '%s' cannot read AI parameter %d for creature %u: parameter index is outside 0..9; returning -1.",
            npcName.c_str(), type, static_cast<unsigned int>(creature->m_nId)
        );
        return -1;
    }
    switch (type) {
        case 0:
            return runtime::Int32FromBits(static_cast<std::uint32_t>(target->i_ai0));
        case 1:
            return runtime::Int32FromBits(static_cast<std::uint32_t>(target->i_ai1));
        case 2:
            return runtime::Int32FromBits(static_cast<std::uint32_t>(target->i_ai2));
        case 3:
            return runtime::Int32FromBits(static_cast<std::uint32_t>(target->i_ai3));
        case 4:
            return runtime::Int32FromBits(static_cast<std::uint32_t>(target->i_ai4));
        case 5:
            return runtime::Int32FromBits(static_cast<std::uint32_t>(target->i_ai5));
        case 6:
            return runtime::Int32FromBits(static_cast<std::uint32_t>(target->i_ai6));
        case 7:
            return runtime::Int32FromBits(static_cast<std::uint32_t>(target->i_ai7));
        case 8:
            return runtime::Int32FromBits(static_cast<std::uint32_t>(target->i_ai8));
        case 9:
            return runtime::Int32FromBits(static_cast<std::uint32_t>(target->i_ai9));
        default:
            break;
    }
    return -1;
}

void CNPC::SetDieEvent(CSharedCreatureData* creature, int enabled, int distance) {
    // Current L2NPC.exe 0x00482ae0.
    L2_GUARD_FUNCTION();
    if (!creature) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(LOG_ERROR, L"Script:SetDieEvent : c == NULL!!!, npc[%s]", npcName.c_str())
        // Log.Add(LOG_ERROR,
        //     "[NPC AI] NPC '%s' cannot set death notifications (enabled %d, distance %d): target creature is missing.
        //     settings unchanged.", WideToUtf8(npcName).c_str(), enabled, distance)
        L2_LOG_ERROR(
            Log,
            "[NPC AI] NPC '%s' cannot set death notifications (enabled %d, distance %d): target creature is missing; "
            "settings unchanged.",
            npcName.c_str(), enabled, distance
        );
        return;
    }
    if (distance < 0x801) {
        creature->m_bDieEventSet = enabled != 0;
        creature->m_nDieEventDistance = distance;
        return;
    }
    const std::string npcName = Utf16ToUtf8(GetName());
    // Log.Add(
    //     LOG_ERROR,
    //     L"Script:SetDieEvent : Too long distance to "
    //     L"broadcast!, npc[%s]",
    //     npcName.c_str()
    // )
    // Log.Add(LOG_ERROR,
    //     "[NPC AI] NPC '%s' cannot set death notifications for creature %u (enabled %d): distance %d exceeds 2048. Settings
    //     unchanged.", WideToUtf8(npcName).c_str(), static_cast<unsigned int>(creature->m_nId), enabled, distance)
    L2_LOG_ERROR(
        Log,
        "[NPC AI] NPC '%s' cannot set death notifications for creature %u (enabled %d): distance %d exceeds 2048; settings "
        "unchanged.",
        npcName.c_str(), static_cast<unsigned int>(creature->m_nId), enabled, distance
    );
}

