void CNPC::ChangeNPCState(CSharedCreatureData* creature, int state) {
    // Current L2NPC.exe 0x00483ed4.
    L2_GUARD_FUNCTION();
    if (state < 0) {
        std::wstring targetNameStorage;
        const wchar_t* targetName = L"null";
        if (creature) {
            targetNameStorage = Utf16ToWide(creature->Name());
            targetName = targetNameStorage.c_str();
        }
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%s] ChangeEffectStatus() : "
        //     L"Invalid state [%d]",
        //     npcName.c_str(), targetName, state
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC script] NPC '%s' cannot change state to %d for target '%s': state must be non-negative. Request not
        //     sent.", WideToUtf8(npcName).c_str(), state, WideToUtf8(targetName).c_str())
        L2_LOG_ERROR(
            Log,
            "[NPC script] NPC '%s' cannot change state to %d for target '%s': state must be non-negative; request not sent.",
            npcName.c_str(), state, WideToUtf8(targetName).c_str()
        );
        ReportScriptContext(LOG_ERROR);
        return;
    }
    g_ns.Send("cdd", 0xdb, creature->m_nId, state);
}

