void CNPC::SetNobless(CSharedCreatureData* creature, int noblessType) {
    // Current L2NPC.exe 0x0048e5c0 validates the type before it touches
    // the target pointer.
    L2_GUARD_FUNCTION();
    if (noblessType == 1) {
        auto* const job = new AtomicSetNobless(m_data->m_nId, creature->m_nId, 1);
        CScriptEngine::AddAtomicJob(creature->index, job);
    } else if (noblessType == 2) {
        auto* const job = new AtomicSetNobless(m_data->m_nId, creature->m_nId, 2);
        CScriptEngine::AddAtomicJob(creature->index, job);
    }
}

