int CNPC::ClassChange(CSharedCreatureData* creature, int classId, int argument) {
    // Current L2NPC.exe 0x0049e47c.
    L2_GUARD_FUNCTION();
    if (!creature) {
        return 0;
    }
    const int creatureSid = CCreatureFactory::Inst().GetIdByIndex(creature->index);
    auto* const job = new AtomicChangeClass(creatureSid, classId, static_cast<int>(Id()), argument);
    CScriptEngine::AddAtomicJob(creature->index, job);
    return 1;
}

