void CNPC::SendAgitWarPacket(CSharedCreatureData* talker) {
    // Current L2NPC.exe 0x0047ce04.
    L2_GUARD_FUNCTION();
    if (!talker) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(LOG_ERROR, L"[%s][%d] talker is NULL!!!, npc[%s]", kNpcSourceFile, 0x435d, npcName.c_str())
        // Log.Add(LOG_ERROR,
        //     "[NPC siege] NPC '%s' cannot send clan-hall war information: recipient creature is missing. Request not
        //     sent.", WideToUtf8(npcName).c_str())
        L2_LOG_ERROR(
            Log,
            "[NPC siege] NPC '%s' cannot send clan-hall war information: recipient creature is missing; request not sent.",
            npcName.c_str()
        );
        return;
    }
    // The current image's "chdd" call supplies only the talker ID after
    // the sub-opcode. Its final `d` consumes the absent trailing vararg.
    g_ns.Send("chdd", 0xfe, 0x38, talker->m_nId);
}

