void CNPC::GiveItemOnAccount(
    CSharedCreatureData* talker, int value1, std::int64_t value2, int value3, std::int64_t value4, int value5, int value6
) {
    // Current L2NPC.exe 0x0047ec5c validates only values 1 through 5.
    L2_GUARD_FUNCTION();
    if (!talker) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(
        //     LOG_ERROR,
        //     L"Script:GiveItemOnAccount : "
        //     L"talker==NULL!!!, npc[%s]",
        //     npcName.c_str()
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC reward] NPC '%s' cannot request an account reward: recipient creature is missing. Request not sent.",
        //     WideToUtf8(npcName).c_str())
        L2_LOG_ERROR(
            Log, "[NPC reward] NPC '%s' cannot request an account reward: recipient creature is missing; request not sent.",
            npcName.c_str()
        );
        return;
    }
    if (value1 < 0 || value2 < 0 || value3 < 0 || value4 < 0 || value5 < 0) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(
        //     LOG_ERROR,
        //     L"Script:GiveItemOnAccount : "
        //     L"Invalid params, npc[%s]",
        //     npcName.c_str()
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC reward] NPC '%s' cannot request an account reward for creature %u: arguments 1..5 must be non-negative
        //     (received %d, %lld, %d, %lld, %d), request not sent.", WideToUtf8(npcName).c_str(), static_cast<unsigned
        //     int>(talker->m_nId), value1, static_cast<long long>(value2), value3, static_cast<long long>(value4), value5)
        L2_LOG_ERROR(
            Log,
            "[NPC reward] NPC '%s' cannot request an account reward for creature %u: arguments 1..5 must be non-negative "
            "(received %d, %lld, %d, %lld, %d); request not sent.",
            npcName.c_str(), static_cast<unsigned int>(talker->m_nId), value1, static_cast<long long>(value2),
            value3, static_cast<long long>(value4), value5
        );
        return;
    }
    g_ns.Send(
        "chddQddQdd", 0xfe, 0x1d, talker->m_nId, value1, static_cast<long long>(value2), 1, value3,
        static_cast<long long>(value4), value5, value6
    );
}

