void CNPC::AddEventLogByNpc(
    int selector,
    CSharedCreatureData* talker,
    char16_t* text0,
    char16_t* text1,
    int argument0,
    int argument1,
    int argument2,
    int argument3,
    int argument4,
    int argument5 [[maybe_unused]]
) {
    // Current L2NPC.exe 0x0048fed8. The sixth integer is present in the
    // registered signature but is not consumed by either target branch.
    L2_GUARD_FUNCTION();
    if (!talker) {
        const std::string npcName = Utf16ToUtf8(GetName());
        const std::wstring first = text0 ? Utf16ToWide(text0) : std::wstring{};
        const std::wstring second = text1 ? Utf16ToWide(text1) : std::wstring{};
        // Log.Add(
        //     LOG_ERROR,
        //     L"AddEventLogByNpc Invalid Talker [%s][%s] "
        //     L"Log[%d] NPC[%s] Args[%d,%d,%d,%d,%d]",
        //     first.c_str(), second.c_str(), selector, npcName.c_str(), argument0, argument1, argument2, argument3,
        //     argument4
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC script] NPC '%s' cannot submit event log %d: target creature is missing. Request not sent. Texts '%s',
        //     '%s'. Arguments %d, %d, %d, %d, %d.", WideToUtf8(npcName).c_str(), selector, WideToUtf8(first).c_str(),
        //     WideToUtf8(second).c_str(), argument0, argument1, argument2, argument3, argument4)
        L2_LOG_ERROR(
            Log,
            "[NPC script] NPC '%s' cannot submit event log %d: target creature is missing; request not sent. Texts '%s', "
            "'%s'; arguments %d, %d, %d, %d, %d.",
            npcName.c_str(), selector, WideToUtf8(first).c_str(), WideToUtf8(second).c_str(), argument0,
            argument1, argument2, argument3, argument4
        );
        return;
    }
    if (selector != 0x8c) {
        return;
    }
    std::array<char16_t, 32> truncatedText;
    if (!text0) {
        truncatedText[0] = u'\0';
        myInvalidParameterHandler(L"(L\"Invalid string pointer\" && 0)", L"wcsncpy_s", nullptr, 0, 0);
    } else {
        std::size_t length = 0;
        while (length < truncatedText.size() - 1 && text0[length] != u'\0') {
            truncatedText[length] = text0[length];
            ++length;
        }
        truncatedText[length] = u'\0';
    }
    g_ns.Send(
        "chdddddS", 0xfe, 0x0f, selector, talker->m_nId, static_cast<int>(Id()), argument0, argument1, truncatedText.data()
    );
}

