bool CNPC::IsLockedItem(CSharedCreatureData* talker, int itemClassId) {
    // Current L2NPC.exe 0x004b4ff8.
    L2_GUARD_FUNCTION();
    if (!talker) {
        // Log.Add(LOG_ERROR, L"[%s][%d] GetItemData(c=null)", kNpcSourceFileW, 0x2312)
        // Log.Add(LOG_ERROR,
        //     "[NPC script] NPC %u cannot evaluate IsLockedItem for item class %d: target creature is missing. Returning
        //     false.", static_cast<unsigned int>(Id()), itemClassId)
        L2_LOG_ERROR(
            Log,
            "[NPC script] NPC %u cannot evaluate IsLockedItem for item class %d: target creature is missing; returning "
            "false.",
            static_cast<unsigned int>(Id()), itemClassId
        );
        return false;
    }
    CInventory inventory;
    const bool isUser = talker->m_bIsUser;
    const int talkerIndex = talker->index;
    inventory.SetIndex(talkerIndex, isUser);
    L2_READ_GUARD(inventory);
    for (CSharedItemData* item = inventory.GetFirst(); item; item = item->Next()) {
        if (item->m_nClassID == itemClassId && item->GetLocked() == 0) {
            return true;
        }
    }
    return false;
}

