void CNPC::SetBossNPCStage(int increment, int threshold, bool incrementBossStage) {
    // Current L2NPC.exe 0x00495700.
    L2_GUARD_FUNCTION();
    const int next = runtime::AddInt32Wrapping(m_nNpcStage, increment);
    if (next < threshold) {
        m_nNpcStage = next;
        return;
    }

    m_nNpcStage = 0;
    CNPC* const boss = CNPC::GetObjectW(m_data->m_BossID);
    if (!boss) {
        // Log.Add(LOG_ERROR, L"[%s][%d] Find Boss failed", kNpcSourceFileW, 0x532d)
        // Log.Add(LOG_ERROR,
        //     "[NPC AI] NPC %u reset its local stage after reaching threshold %d, but boss %u is unavailable. Boss stage
        //     unchanged.", static_cast<unsigned int>(Id()), threshold, static_cast<unsigned int>(m_data->m_BossID))
        L2_LOG_ERROR(
            Log,
            "[NPC AI] NPC %u reset its local stage after reaching threshold %d, but boss %u is unavailable; boss stage "
            "unchanged.",
            static_cast<unsigned int>(Id()), threshold, static_cast<unsigned int>(m_data->m_BossID)
        );
        return;
    }

    boss->SetMyNPCStage(incrementBossStage ? boss->GetMyNPCStage() + 1 : 0);
    CNPCEvent* const event = CNPCEventFactory::CreateChangeEventStage(boss, boss->GetMyNPCStage());
    if (!event) {
        // Log.Add(LOG_ERROR, L"[%s][%d] CreateScriptEvent failed", kNpcSourceFileW, 0x5328)
        // Log.Add(LOG_ERROR,
        //     "[NPC AI] NPC %u updated the stage of boss %u, but could not create the stage-change event. AI callback not
        //     delivered.", static_cast<unsigned int>(Id()), static_cast<unsigned int>(m_data->m_BossID))
        L2_LOG_ERROR(
            Log,
            "[NPC AI] NPC %u updated the stage of boss %u, but could not create the stage-change event; AI callback not "
            "delivered.",
            static_cast<unsigned int>(Id()), static_cast<unsigned int>(m_data->m_BossID)
        );
        return;
    }
    boss->HandleEvent(event);
    L2_RELEASE(event, ObjectRefType::CreateDelete);
}

