int CNPC::IsHostileInDominionSiege(CSharedCreatureData* creature) {
    // Current L2NPC.exe 0x0048306c returns -1 when the creature is
    // invalid or is not participating, 0 for the same dominion, and 1
    // for a different dominion.
    L2_GUARD_FUNCTION();
    if (!creature) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(
        //     LOG_ERROR,
        //     L"Script:IsHostileInDominionSiege : "
        //     L"c == NULL!!!, npc[%s]",
        //     npcName.c_str()
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC siege] NPC '%s' cannot check dominion hostility: target creature is missing. Returning -1.",
        //     WideToUtf8(npcName).c_str())
        L2_LOG_ERROR(
            Log, "[NPC siege] NPC '%s' cannot check dominion hostility: target creature is missing; returning -1.",
            npcName.c_str()
        );
        return -1;
    }
    const int siegeId = GetDominionSiegeID(creature);
    if (siegeId == 0) {
        return -1;
    }
    return siegeId != m_data->m_nResidenceID ? 1 : 0;
}

