int CNPC::CanAttack(CSharedCreatureData* creature) {
    // Current L2NPC.exe 0x0047b72c.
    L2_GUARD_FUNCTION();
    if (!creature) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%S][%d] CNPC::CanAttack(target=NULL) "
        //     L"I'm [%s] ",
        //     kNpcSourceFile, 0x40bf, npcName.c_str()
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC combat] NPC '%s' cannot check attack range: target creature is missing. Returning 0.",
        //     WideToUtf8(npcName).c_str())
        L2_LOG_ERROR(
            Log, "[NPC combat] NPC '%s' cannot check attack range: target creature is missing; returning 0.",
            npcName.c_str()
        );
        return 0;
    }

    const FVector source = m_data->GetPos();
    const FVector target = creature->GetPos();
    const double deltaX = source.x - target.x;
    const double deltaY = source.y - target.y;
    return CheckAttackable(
               static_cast<double>(m_data->m_nAttackRange), m_data->m_dCollisionRadius, creature->m_dCollisionRadius,
               deltaX * deltaX + deltaY * deltaY, m_data->m_dCollisionHeight, creature->m_dCollisionHeight,
               static_cast<int>(source.z), static_cast<int>(target.z)
           )
        ? 1
        : 0;
}

bool CNPC::CanAttackEx(double targetCollisionRadius, const FVector& targetPosition, NpcAttackMoveType attackMoveType) {
    L2_GUARD_FUNCTION();
    // Current L2NPC.exe 0x0046c730.
    const FVector sourcePosition = m_data->GetPos();
    const double deltaX = sourcePosition.x - targetPosition.x;
    const double deltaY = sourcePosition.y - targetPosition.y;
    const double deltaZ = sourcePosition.z - targetPosition.z;
    const double distance = std::sqrt(deltaX * deltaX + deltaY * deltaY + deltaZ * deltaZ);

    return static_cast<int>(attackMoveType) == 1 ||
        static_cast<double>(m_data->m_nAttackRange) + m_data->m_dCollisionRadius + targetCollisionRadius > distance;
}

