int CNPC::UseSkill(CSharedCreatureData* creature, std::int64_t skillNameId) {
    // Current L2NPC.exe 0x0049ea48. The current embedded signature and
    // packet format use a 64-bit packed skill id, unlike the older PDB.
    L2_GUARD_FUNCTION();
    if (!creature) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] int CNPC::UseSkill failed. "
        //     L"c=NULL",
        //     kNpcSourceFileW, 0x2588
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC combat] NPC %u cannot use skill %lld: target creature is missing. Request not sent, returning -1.",
        //     static_cast<unsigned int>(Id()), static_cast<long long>(skillNameId))
        L2_LOG_ERROR(
            Log, "[NPC combat] NPC %u cannot use skill %lld: target creature is missing; request not sent, returning -1.",
            static_cast<unsigned int>(Id()), static_cast<long long>(skillNameId)
        );
        return -1;
    }
    CCreatureFactory& creatureFactory = CCreatureFactory::Inst();
    const int selfIndex = sm->index;
    const int selfId = creatureFactory.GetIdByIndex(selfIndex);
    const int targetId = creature->m_nId;
    g_ns.Send("cdddQdd", 0x1b, selfId, selfIndex, targetId, static_cast<long long>(skillNameId), 1, 1);
    return 1;
}

