int CNPC::GiveTimeAttackReward(CSharedCreatureData* creature, int roomNumber, int itemClassId, int count) {
    // Current L2NPC.exe 0x0048d938.
    L2_GUARD_FUNCTION();
    if (gGlobalObj.GetSSQPart(creature) == 0) {
        return 0;
    }
    if (!creature) {
        // Log.Add(
        //     LOG_ERROR,
        //     "[%s][%d] GiveTimeAttackReward() failed. "
        //     "Invalid user from NPC[%s]",
        //     kNpcSourceFile, 0x3f08, Utf16ToUtf8(GetName()).c_str()
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC reward] NPC '%s' cannot grant item class %d, count %d for time-attack room %d: recipient creature is
        //     missing, reward not queued, returning 0.", Utf16ToUtf8(GetName()).c_str(), itemClassId, count, roomNumber)
        L2_LOG_ERROR(
            Log,
            "[NPC reward] NPC '%s' cannot grant item class %d, count %d for time-attack room %d: recipient creature is "
            "missing; reward not queued, returning 0.",
            Utf16ToUtf8(GetName()).c_str(), itemClassId, count, roomNumber
        );
        return 0;
    }

    const int questId = CScriptEngine::TLGetCurrentQuestID();
    const int creatureId = creature->m_nId;
    auto* const job =
        new AtomicGiveTimeAttackReward(creatureId, roomNumber, questId, itemClassId, static_cast<std::int64_t>(count));
    CScriptEngine::AddAtomicJob(creature->index, job);
    return 1;
}

