void CNPC::GiveEventItem(
    CSharedCreatureData* creature,
    int value1,
    std::int64_t value2,
    int value3,
    std::int64_t value4,
    int value5,
    int value6,
    int eventType,
    int value8
) {
    // Current L2NPC.exe 0x0047ea7c.
    L2_GUARD_FUNCTION();
    if (!creature) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(
        //     LOG_ERROR,
        //     L"Script:GiveEventItem : "
        //     L"talker==NULL!!!, npc[%s]",
        //     npcName.c_str()
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC reward] NPC '%s' cannot request event reward type %d: recipient creature is missing. Request not sent.",
        //     WideToUtf8(npcName).c_str(), eventType)
        L2_LOG_ERROR(
            Log,
            "[NPC reward] NPC '%s' cannot request event reward type %d: recipient creature is missing; request not sent.",
            npcName.c_str(), eventType
        );
        return;
    }
    if (value1 < 0 || value2 < 0 || value3 < 0 || value4 < 0 || value5 < 0 || value6 < 0 || value8 < 0) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(
        //     LOG_ERROR,
        //     L"Script:GiveEventItem : "
        //     L"Invalid params, npc[%s]",
        //     npcName.c_str()
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC reward] NPC '%s' cannot request event reward type %d: reward arguments must be non-negative (1..6: %d,
        //     %lld, %d, %lld, %d, %d. 8: %d). Request not sent.", WideToUtf8(npcName).c_str(), eventType, value1,
        //     static_cast<long long>(value2), value3, static_cast<long long>(value4), value5, value6, value8)
        L2_LOG_ERROR(
            Log,
            "[NPC reward] NPC '%s' cannot request event reward type %d: reward arguments must be non-negative (1..6: %d, "
            "%lld, %d, %lld, %d, %d; 8: %d); request not sent.",
            npcName.c_str(), eventType, value1, static_cast<long long>(value2), value3,
            static_cast<long long>(value4), value5, value6, value8
        );
        return;
    }
    if (static_cast<unsigned int>(eventType) >= 13U) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(
        //     LOG_ERROR,
        //     L"Script:GiveEventItem : "
        //     L"Invalid eventtype, npc[%s]",
        //     npcName.c_str()
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC reward] NPC '%s' cannot request event reward type %d: event type is outside 0..12. Request not sent.",
        //     WideToUtf8(npcName).c_str(), eventType)
        L2_LOG_ERROR(
            Log, "[NPC reward] NPC '%s' cannot request event reward type %d: event type is outside 0..12; request not sent.",
            npcName.c_str(), eventType
        );
        return;
    }

    g_ns.Send(
        "cddQdQdddd", 0x99, creature->m_nId, value1, static_cast<long long>(value2), value3, static_cast<long long>(value4),
        value5, value6, eventType, value8
    );
}

