void CNPC::UpdatePVPPoint(CSharedCreatureData* target, int delta, int type) {
    // Current L2NPC.exe 0x0048ed5c. The public name comes from its embedded
    // debug signature. The linker symbol itself was stripped.
    L2_GUARD_FUNCTION();
    if (!target) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(LOG_ERROR, L"[%s][%d] talker is NULL!!!, npc[%s]", kNpcSourceFile, 0x436c, npcName.c_str())
        // Log.Add(LOG_ERROR,
        //     "[NPC PvP] NPC '%s' cannot change PvP points by %d (type %d): target creature is missing. Update not queued.",
        //     WideToUtf8(npcName).c_str(), delta, type)
        L2_LOG_ERROR(
            Log,
            "[NPC PvP] NPC '%s' cannot change PvP points by %d (type %d): target creature is missing; update not queued.",
            npcName.c_str(), delta, type
        );
        return;
    }
    auto* const job = new AtomicUpdatePVPPoint(target->m_nId, delta, type);
    CScriptEngine::AddAtomicJob(target->index, job);
}

