void CNPC::SetHTMLCookie(CSharedCreatureData* target, int pageGroup, int page) {
    // Current L2NPC.exe 0x0047aff0.
    L2_GUARD_FUNCTION();
    if (!target) {
        // Log.Add(LOG_ERROR, L"[%s][%d] SetHTMLCookie failed. spUser is null", kNpcSourceFileW, 0x3fe9)
        // Log.Add(LOG_ERROR,
        //     "[NPC script] NPC %u cannot store HTML selection (group %d, page %d): target creature is missing. Selection
        //     unchanged.", static_cast<unsigned int>(Id()), pageGroup, page)
        L2_LOG_ERROR(
            Log,
            "[NPC script] NPC %u cannot store HTML selection (group %d, page %d): target creature is missing; selection "
            "unchanged.",
            static_cast<unsigned int>(Id()), pageGroup, page
        );
        return;
    }
    if (User* const user = User::GetObjectW(target->m_nId)) {
        const std::uint32_t cookie = static_cast<std::uint32_t>(pageGroup) * 100U + static_cast<std::uint32_t>(page);
        user->mHTMLCookie = runtime::Int32FromBits(cookie);
    }
}

int CNPC::GetHTMLCookie(CSharedCreatureData* target, int pageGroup, int page) {
    // Current L2NPC.exe 0x0047b0e0.
    L2_GUARD_FUNCTION();
    if (!target) {
        // Log.Add(LOG_ERROR, L"[%s][%d] GetHTMLCookie failed. spUser is null", kNpcSourceFileW, 0x3ffb)
        // Log.Add(LOG_ERROR,
        //     "[NPC script] NPC %u cannot check HTML selection (group %d, page %d): target creature is missing. Returning
        //     -1.", static_cast<unsigned int>(Id()), pageGroup, page)
        L2_LOG_ERROR(
            Log,
            "[NPC script] NPC %u cannot check HTML selection (group %d, page %d): target creature is missing; returning -1.",
            static_cast<unsigned int>(Id()), pageGroup, page
        );
        return -1;
    }
    User* const user = User::GetObjectW(target->m_nId);
    if (!user) {
        return -1;
    }
    const std::uint32_t cookie = static_cast<std::uint32_t>(pageGroup) * 100U + static_cast<std::uint32_t>(page);
    return user->mHTMLCookie == runtime::Int32FromBits(cookie) ? user->mHTMLCookie : -1;
}

void CNPC::SetCookie(CSharedCreatureData* target, char16_t* key, int value) {
    // Current L2NPC.exe 0x0049ad2c.
    L2_GUARD_FUNCTION();
    if (!target) {
        // Log.Add(LOG_ERROR, L"[%s][%d] SetCookie failed. spUser is null", kNpcSourceFileW, 0x1a59)
        // Log.Add(LOG_ERROR,
        //     "[NPC script] NPC %u cannot set a script cookie: target creature is missing. Cookie unchanged.",
        //     static_cast<unsigned int>(Id()))
        L2_LOG_ERROR(
            Log, "[NPC script] NPC %u cannot set a script cookie: target creature is missing; cookie unchanged.",
            static_cast<unsigned int>(Id())
        );
        return;
    }
    CCreature* const object = CCreatureFactory::Inst().GetObjectW(target->index);
    if (object && object->m_data->m_bIsUser && object->IsPC()) {
        User* const user = object->CastUser();
        user->SetCookie(key, value);
        return;
    }
    // Log.Add(LOG_ERROR, L"[%s][%d] SetCookie failed. invalid user", kNpcSourceFileW, 0x1a60)
    // Log.Add(LOG_ERROR,
    //     "[NPC script] NPC %u cannot set a script cookie for creature %u: %s. Cookie unchanged.",
    //     static_cast<unsigned int>(Id()), static_cast<unsigned int>(target->m_nId), !object ? "target object is
    //     unavailable" : "target object cannot be used as a player")
    L2_LOG_ERROR(
        Log, "[NPC script] NPC %u cannot set a script cookie for creature %u: %s; cookie unchanged.",
        static_cast<unsigned int>(Id()), static_cast<unsigned int>(target->m_nId),
        !object ? "target object is unavailable" : "target object cannot be used as a player"
    );
}

int CNPC::GetCookie(CSharedCreatureData* target, char16_t* key) {
    // Current L2NPC.exe 0x0049aec0. The null-target diagnostic really names
    // SetCookie in the shipping binary.
    L2_GUARD_FUNCTION();
    if (!target) {
        // Log.Add(LOG_ERROR, L"[%s][%d] SetCookie failed. spUser is null", kNpcSourceFileW, 0x1a6f)
        // Log.Add(LOG_ERROR,
        //     "[NPC script] NPC %u cannot read a script cookie: target creature is missing. Returning -1.",
        //     static_cast<unsigned int>(Id()))
        L2_LOG_ERROR(
            Log, "[NPC script] NPC %u cannot read a script cookie: target creature is missing; returning -1.",
            static_cast<unsigned int>(Id())
        );
        return -1;
    }
    CCreature* const object = CCreatureFactory::Inst().GetObjectW(target->index);
    if (object && object->m_data->m_bIsUser && object->IsPC()) {
        User* const user = object->CastUser();
        return user->GetCookie(key);
    }
    // Log.Add(LOG_ERROR, L"[%s][%d] GetCookie failed. invalid user", kNpcSourceFileW, 0x1a76)
    // Log.Add(LOG_ERROR,
    //     "[NPC script] NPC %u cannot read a script cookie for creature %u: %s. Returning -1.",
    //     static_cast<unsigned int>(Id()), static_cast<unsigned int>(target->m_nId), !object ? "target object is
    //     unavailable" : "target object cannot be used as a player")
    L2_LOG_ERROR(
        Log, "[NPC script] NPC %u cannot read a script cookie for creature %u: %s; returning -1.",
        static_cast<unsigned int>(Id()), static_cast<unsigned int>(target->m_nId),
        !object ? "target object is unavailable" : "target object cannot be used as a player"
    );
    return -1;
}

