int CNPC::AddMoveToDesire(int x, int y, int z, float value) {
    // Current L2NPC.exe 0x0048a280.
    L2_GUARD_FUNCTION();
    if (!CanAct()) {
        return 0;
    }

    if (m_data->IsFlying()) {
        z = std::clamp(z, -1000, 6000);
    }

    if (l2geo::CWorld::Inst().IsValidPosition(x, y)) {
        m_DesirePQ.AddValue(
            CDesireFactory::MakeMoveTo(
                FVector{static_cast<double>(x), static_cast<double>(y), static_cast<double>(z)}, value
            )
        );
        return 1;
    }

    const FVector position = m_data->GetPos();
    const std::string npcName = Utf16ToUtf8(GetName());
    // Log.Add(
    //     LOG_ERROR,
    //     L"[%s] AddMoveToDesire -> IsValidPosition. "
    //     L"[%d,%d,%d] -> [%d,%d,%d]",
    //     npcName.c_str(), runtime::Win64CvttDoubleToInt32(position.x), runtime::Win64CvttDoubleToInt32(position.y),
    //     runtime::Win64CvttDoubleToInt32(position.z), x, y, z
    // )
    // Log.Add(LOG_ERROR,
    //     "[NPC movement] Cannot queue movement for NPC '%s' (%u) from (%d, %d, %d) to (%d, %d, %d): destination has no
    //     available geodata zone.", WideToUtf8(npcName).c_str(), static_cast<unsigned int>(Id()),
    //     runtime::Win64CvttDoubleToInt32(position.x), runtime::Win64CvttDoubleToInt32(position.y),
    //     runtime::Win64CvttDoubleToInt32(position.z), x, y, z)
    L2_LOG_ERROR(
        Log,
        "[NPC movement] Cannot queue movement for NPC '%s' (%u) from (%d, %d, %d) to (%d, %d, %d): destination has no "
        "available geodata zone.",
        npcName.c_str(), static_cast<unsigned int>(Id()), runtime::Win64CvttDoubleToInt32(position.x),
        runtime::Win64CvttDoubleToInt32(position.y), runtime::Win64CvttDoubleToInt32(position.z), x, y, z
    );
    return 0;
}

CShowTutorialHTMLTimer::CShowTutorialHTMLTimer(
    int npcIndex, int toIndex, int delaySeconds, const char16_t* htmlFile, const char16_t* soundFile
) :
    _npcindex(npcIndex), _toindex(toIndex), sHTMLFile(htmlFile), sSoundFile(soundFile) {
    AddTimer(static_cast<std::uint32_t>(delaySeconds) * 1000U, 0);
}

void CShowTutorialHTMLTimer::TimerExpired(int) {
    g_ns.Send("cddS", 0x35, _npcindex, _toindex, sHTMLFile.c_str());

    g_ns.Send("cSddddddd", 0x30, sSoundFile.c_str(), _toindex, 0, 0, 0, 0, 0, 0);

    L2_RELEASE(this, ObjectRefType::CreateDelete);
}

CShowTutorialMarkTimer::CShowTutorialMarkTimer(int npcIndex, int toIndex, int type, int id, int delaySeconds) :
    _npcindex(npcIndex), _toindex(toIndex), _id(id), _type(type) {
    AddTimer(static_cast<std::uint32_t>(delaySeconds) * 1000U, 0);
}

void CShowTutorialMarkTimer::TimerExpired(int) {
    g_ns.Send("cdddd", 0x36, _npcindex, _toindex, _type, _id);

    L2_RELEASE(this, ObjectRefType::CreateDelete);
}

