int CNPC::GetOlympiadPoint(CSharedCreatureData* creature) {
    // Current L2NPC.exe 0x0048e14c.
    L2_GUARD_FUNCTION();
    if (!creature) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(
        //     LOG_ERROR, L"[%s][%d][%s] talker is null. CNPC[%s]", kNpcSourceFileW, 0x4123, L"CNPC::GetOlympiadPoint",
        //     npcName.c_str()
        // )
        // Log.Add(LOG_ERROR,
        //     "[Olympiad] NPC '%s' cannot read current points: target creature is missing. Returning 0.",
        //     WideToUtf8(npcName).c_str())
        L2_LOG_ERROR(
            Log, "[Olympiad] NPC '%s' cannot read current points: target creature is missing; returning 0.",
            npcName.c_str()
        );
        return 0;
    }

    SharedNoblessInfoVector& info = SharedNoblessInfo::Inst();
    const int index = creature->m_nNoblessIndex;
    if (index >= info.Size()) {
        // Log.Add(LOG_ERROR, L"[%s] invald nobless index!!!! %d %d", L"CNPC::GetOlympiadPoint", creature->m_nDBID, index)
        // Log.Add(LOG_ERROR,
        //     "[Olympiad] NPC %u cannot read current points for character %u: noblesse index %d is outside the available
        //     table, returning 0.", static_cast<unsigned int>(Id()), static_cast<unsigned int>(creature->m_nDBID), index)
        L2_LOG_ERROR(
            Log,
            "[Olympiad] NPC %u cannot read current points for character %u: noblesse index %d is outside the available "
            "table; returning 0.",
            static_cast<unsigned int>(Id()), static_cast<unsigned int>(creature->m_nDBID), index
        );
        return 0;
    }
    if (index == -1) {
        return 0;
    }
    SharedNoblessInfo* const row = SharedNoblessInfo::GetInfo(index);
    return row->nOlympiadPoint;
}

