CSharedCreatureData* CNPC::FindNeighborHero(int radius) {
    // Current L2NPC.exe 0x004b1b08.
    L2_GUARD_FUNCTION();
    std::vector<int> sharedIndices;
    for (int index = 0; index < SharedNoblessInfo::Inst().Size(); ++index) {
        // if (SharedNoblessInfo::GetInfo(index)->nHeroType != 2) {
        if (SharedNoblessInfo::GetInfo(index)->nHeroType != HERO_ACTIVE) {
            continue;
        }
        User* const hero = User::GetObjectW(SharedNoblessInfo::GetInfo(index)->nCharSid);
        if (!hero) {
            continue;
        }
        const FVector position = hero->m_data->GetPos();
        const FVector origin = m_data->GetPos();
        const double dx = position.x - origin.x;
        const double dy = position.y - origin.y;
        const double dz = position.z - origin.z;
        if (dx * dx + dy * dy + dz * dz <= static_cast<double>(radius) * static_cast<double>(radius)) {
            sharedIndices.push_back(hero->m_data->index);
        }
    }
    const std::size_t count = sharedIndices.size();
    if (count != 0) {
        const int selected = Random(static_cast<int>(count)) - 1;
        if (selected >= 0 && static_cast<std::size_t>(selected) < count) {
            CSharedCreatureData* const result =
                CCreatureFactory::Inst().GetData(sharedIndices[static_cast<std::size_t>(selected)]);
            if (result) {
                return result;
            }
        }
    }
    return nullptr;
}

