int CNPC::GetFishingRanking(CSharedCreatureData* creature) {
    // Current L2NPC.exe 0x0047db74.
    L2_GUARD_FUNCTION();
    if (!creature) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(
        //     LOG_ERROR,
        //     L"Script:GetFishingRanking :  "
        //     L"talker==NULL!!!, npc[%s]",
        //     npcName.c_str()
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC script] NPC '%s' cannot read fishing rank: target creature is missing. Returning 0.",
        //     WideToUtf8(npcName).c_str())
        L2_LOG_ERROR(
            Log, "[NPC script] NPC '%s' cannot read fishing rank: target creature is missing; returning 0.",
            npcName.c_str()
        );
        return 0;
    }
    for (int rank = 0; rank < 5; ++rank) {
        const SharedFishingInfo* const info = SharedFishingInfo::GetInfo();
        if (info->m_RankingDBID[rank] == creature->m_nDBID) {
            return rank + 1;
        }
    }
    return 0;
}

