void CNPC::SetKamarokaReward(int reward, CSharedCreatureData* creature) {
    // Current L2NPC.exe 0x00487224.
    L2_GUARD_FUNCTION();
    // Current L2NPC.exe 0x00487224 forms reward-1 with a 32-bit LEA before
    // its signed-positive test, so INT_MIN wraps to INT_MAX.
    if (!creature) {
        return;
    }
    const int adjustedReward = runtime::Int32FromBits(static_cast<std::uint32_t>(reward) - 1u);
    if (adjustedReward <= 0) {
        return;
    }
    l2npc::dbnpc.RequestKamarokaSetReward(adjustedReward, creature->m_nDBID, 1);
}

void CNPC::GetKamarokaCheckReward(int reward, CSharedCreatureData* creature) {
    // Current L2NPC.exe 0x00495960.
    L2_GUARD_FUNCTION();
    if (!creature) {
        return;
    }
    const int zeroBasedReward = static_cast<int>(static_cast<std::uint32_t>(reward) - 1U);
    if (zeroBasedReward >= 1) {
        const SharedKamarokaInfo* const info = SharedKamarokaInfo::GetInfo();
        if (info->m_nState == 2) {
            l2npc::dbnpc.RequestKamarokaCheckReward(
                zeroBasedReward, static_cast<int>(Id()), creature->m_nDBID, creature->m_nId
            );
            return;
        }
    }

    CNPC* const source = CNPC::GetObjectW(Id());
    if (!source) {
        return;
    }
    CNPCEvent* const event = CNPCEventFactory::CreateCheckKamarokaRewardEvent(source, creature, 0, -1);
    if (!event) {
        // Log.Add(LOG_ERROR, L"[%s][%d] Event failed", kNpcSourceFileW, 0x5472)
        // Log.Add(LOG_ERROR,
        //     "[NPC reward] NPC %u cannot create the Kamaroka reward-check fallback event for creature %u, requested reward
        //     %d (result 0, -1), AI callback not delivered.", static_cast<unsigned int>(Id()), static_cast<unsigned
        //     int>(creature->m_nId), reward)
        L2_LOG_ERROR(
            Log,
            "[NPC reward] NPC %u cannot create the Kamaroka reward-check fallback event for creature %u, requested reward "
            "%d (result 0, -1); AI callback not delivered.",
            static_cast<unsigned int>(Id()), static_cast<unsigned int>(creature->m_nId), reward
        );
        return;
    }
    source->HandleEvent(event);
    L2_RELEASE(event, ObjectRefType::CreateDelete);
}

