int CNPC::GetTimeOfSSQ(int timeType) {
    // Current L2NPC.exe 0x0047a9fc.
    L2_GUARD_FUNCTION();
    switch (timeType) {
        case 0:
            return SharedSSQInfo::GetInfo()->mEventStartTime;
        case 1:
            return SharedSSQInfo::GetInfo()->mEventEndTime;
        case 2:
            return SharedSSQInfo::GetInfo()->mSealEffectTime;
        case 3:
            return SharedSSQInfo::GetInfo()->mSealEffectEndTime;
        default:
            return 0;
    }
}

std::int64_t CNPC::GetDepositedSSQItemCount(CSharedCreatureData* creature, int side, int itemType) {
    // Current L2NPC.exe 0x0047873c.
    L2_GUARD_FUNCTION();
    if (!creature) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d Script::GetDepositedSSQItemCount : "
        //     L"c==NULL!!!, npc[%s]",
        //     kNpcSourceFile, 0x3b15, npcName.c_str()
        // )
        // Log.Add(LOG_ERROR,
        //     "[Seven Signs] NPC '%s' cannot read deposited item type %d for side %d: target creature is missing. Returning
        //     0.", WideToUtf8(npcName).c_str(), itemType, side)
        L2_LOG_ERROR(
            Log,
            "[Seven Signs] NPC '%s' cannot read deposited item type %d for side %d: target creature is missing; returning "
            "0.",
            npcName.c_str(), itemType, side
        );
        return 0;
    }
    if (static_cast<std::uint32_t>(itemType) >= 3U) {
        return 0;
    }
    if (SharedSSQInfo::GetInfo()->mCurrentStatus == 0) {
        return 0;
    }
    if (side == 1 || side == 2) {
        return side == 1 ? creature->m_nDawnItemCount[itemType] : creature->m_nTwilightItemCount[itemType];
    }
    return 0;
}

int CNPC::GetSealSelectionNo(CSharedCreatureData* creature) {
    // Current L2NPC.exe 0x0047885c.
    L2_GUARD_FUNCTION();
    // Current L2NPC.exe 0x0047885c does not initialize/access the shared SSQ
    // singleton when the supplied creature is null.
    if (!creature) {
        return 0;
    }
    SharedSSQInfo* const info = SharedSSQInfo::GetInfo();
    return info->mRoundNumber == creature->m_nSSQRoundNumber ? creature->m_nSealSelectionNo : 0;
}

int CNPC::IsJoinableToDawn(CSharedCreatureData* creature) {
    // Current L2NPC.exe 0x00478918.
    L2_GUARD_FUNCTION();
    if (!creature) {
        return 0;
    }
    SharedSSQInfo* info = SharedSSQInfo::GetInfo();
    if (info->mRoundNumber == creature->m_nSSQRoundNumber) {
        return 0;
    }
    info = SharedSSQInfo::GetInfo();
    return info->mRoundNumber == creature->m_nSSQDawnRound ? 1 : 0;
}

