int CNPC::IsManorSettingTime() {
    // Current L2NPC.exe 0x00476068 uses _time32/localtime and the unsigned
    // comparison `(tm_hour - 8) > 11`.
    L2_GUARD_FUNCTION();
    const std::uint32_t nowBits = static_cast<std::uint32_t>(runtime::crt::Time32Now());
    const std::time_t now = static_cast<std::time_t>(runtime::Int32FromBits(nowBits));
    std::tm local{};
    std::tm* localResult = nullptr;
#if defined(_WIN32)
    localResult = ::localtime_s(&local, &now) == 0 ? &local : nullptr;
#else
    localResult = ::localtime_r(&now, &local);
#endif
    return static_cast<std::uint32_t>(localResult->tm_hour) - 8U > 11U ? 1 : 0;
}

