void CNPC::SetSeedSellProperty(
    CSharedCreatureData* creature, int manorId, int seedClassId, std::int64_t count, std::int64_t price
) {
    // Current L2NPC.exe 0x00479548.
    L2_GUARD_FUNCTION();
    if (!IsValidManorId(manorId)) {
        // Log.Add(LOG_ERROR, L"[%S][%d]manor id[%d] is invalid", kNpcSourceFile, 0x3c6c, manorId)
        // Log.Add(LOG_ERROR,
        //     "[manor] NPC %u cannot set the sale of seed class %d (count %lld, price %lld): manor ID %d is outside 1..%u.
        //     request not sent.", static_cast<unsigned int>(Id()), seedClassId, static_cast<long long>(count),
        //     static_cast<long long>(price), manorId, static_cast<unsigned int>(kManorEntryCount))
        L2_LOG_ERROR(
            Log,
            "[manor] NPC %u cannot set the sale of seed class %d (count %lld, price %lld): manor ID %d is outside 1..%u; "
            "request not sent.",
            static_cast<unsigned int>(Id()), seedClassId, static_cast<long long>(count), static_cast<long long>(price),
            manorId, static_cast<unsigned int>(kManorEntryCount)
        );
        return;
    }

    const int sourceSharedIndex = m_data->index;
    const int targetSharedIndex = creature->index;
    const int residenceId = CManorData::Inst(manorId).m_nResidenceID;
    g_ns.Send(
        "cdddddQQ", 0x5b, sourceSharedIndex, targetSharedIndex, residenceId, manorId, seedClassId,
        static_cast<long long>(count), static_cast<long long>(price)
    );
}

