int CNPC::Castle_GetPledgeWorldId() {
    L2_GUARD_FUNCTION();
    const int residenceId = m_data->m_nResidenceID;
    if (static_cast<std::uint32_t>(residenceId) - 1U >= 999U) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(
        //     LOG_ERROR,
        //     L"NPC[%s] participated in invalid "
        //     L"residence[%d]",
        //     npcName.c_str(), residenceId
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC siege] NPC '%s' cannot read the owner pledge world ID: residence ID %d is outside 1..999. Returning 0.",
        //     WideToUtf8(npcName).c_str(), residenceId)
        L2_LOG_ERROR(
            Log,
            "[NPC siege] NPC '%s' cannot read the owner pledge world ID: residence ID %d is outside 1..999; returning 0.",
            npcName.c_str(), residenceId
        );
        return 0;
    }
    const int pledgeWorldId = CResidenceData::Inst(residenceId).m_nResidenceOwnerWorldId;
    const std::uint32_t pledgeIndex = CResidenceData::Inst(residenceId).m_nResidenceOwnerIndex;
    if (pledgeWorldId == 0 || pledgeIndex == UINT32_MAX) {
        return 0;
    }
    return pledgeWorldId;
}

int CNPC::Castle_GetPledgeId() {
    // Current L2NPC.exe 0x0048b4e8. The target asks the maker/spawn
    // definition for its live in-zone id. It does not read the creature
    // record's cached instant-zone field here.
    L2_GUARD_FUNCTION();
    if (InstantZone_GetId() >= 1) {
        BaseSpawnDefine* const definition = SpawnDefine();
        return definition ? definition->GetPledgeDBID() : 0;
    }
    // The non-in-zone branch reads CSharedCreatureData::residence_id
    // directly in the shipping body, avoiding a nested script guard.
    const int residenceId = m_data->m_nResidenceID;
    if (static_cast<std::uint32_t>(residenceId) - 1U >= 999U) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(
        //     LOG_ERROR,
        //     L"NPC[%s] participated in invalid "
        //     L"residence[%d]",
        //     npcName.c_str(), residenceId
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC siege] NPC '%s' cannot read the owner pledge ID: residence ID %d is outside 1..999. Returning 0.",
        //     WideToUtf8(npcName).c_str(), residenceId)
        L2_LOG_ERROR(
            Log, "[NPC siege] NPC '%s' cannot read the owner pledge ID: residence ID %d is outside 1..999; returning 0.",
            npcName.c_str(), residenceId
        );
        return 0;
    }
    const std::uint32_t pledgeId = CResidenceData::Inst(residenceId).m_nResidenceOwnerID;
    const std::uint32_t pledgeIndex = CResidenceData::Inst(residenceId).m_nResidenceOwnerIndex;
    if (pledgeId == 0 || pledgeIndex == UINT32_MAX) {
        return 0;
    }
    return runtime::Int32FromBits(pledgeId);
}

int CNPC::Castle_IsUnderSiege() {
    L2_GUARD_FUNCTION();
    // Current L2NPC.exe 0x00472af0 caches the shared residence ID, then
    // performs a second live lookup only when the first state test fails.
    const int residenceId = m_data->m_nResidenceID;
    return (CResidenceData::Inst(residenceId).m_ResidenceState == RS_SIEGE ||
               CResidenceData::Inst(residenceId).m_ResidenceState == RS_MID_VICTORY)
        ? 1
        : 0;
}

int CNPC::Castle_IsUnderSiege2(int residenceId) {
    L2_GUARD_FUNCTION();
    if (static_cast<unsigned int>(residenceId) >= 21u) {
        return 0;
    }
    // Current L2NPC.exe 0x00472bb8 repeats Inst for the second test instead
    // of retaining the first reference.
    return (CResidenceData::Inst(residenceId).m_ResidenceState == RS_SIEGE ||
               CResidenceData::Inst(residenceId).m_ResidenceState == RS_MID_VICTORY)
        ? 1
        : 0;
}

int CNPC::IsMyLord(CSharedCreatureData* creature) {
    L2_GUARD_FUNCTION();
    if (!creature) {
        return 0;
    }
    const std::uint32_t pledgeId = creature->m_nPledgeID;
    const int worldId = creature->m_nWorldId;
    if (pledgeId == 0 || !creature->m_bPledgeMaster) {
        return 0;
    }
    const int residenceId = m_data->m_nResidenceID;
    if (residenceId == 0) {
        if (!SharedInstantAgitDecoData::GetInfo(runtime::Int32FromBits(pledgeId))) {
            // Log.Add(
            //     LOG_ERROR,
            //     L"residence_id should be more than 0. "
            //     L"current residence_id = %d",
            //     residenceId
            // )
            // Log.Add(LOG_ERROR,
            //     "[NPC siege] NPC %u cannot confirm lord ownership for pledge %u: residence is 0 and no instant clan-hall
            //     decoration record is available, returning 0.", static_cast<unsigned int>(Id()), static_cast<unsigned
            //     int>(pledgeId))
            L2_LOG_ERROR(
                Log,
                "[NPC siege] NPC %u cannot confirm lord ownership for pledge %u: residence is 0 and no instant clan-hall "
                "decoration record is available; returning 0.",
                static_cast<unsigned int>(Id()), static_cast<unsigned int>(pledgeId)
            );
            return 0;
        }
        return 1;
    }
    if (CResidenceData::Inst(residenceId).m_nResidenceOwnerID != pledgeId) {
        return 0;
    }
    return CResidenceData::Inst(residenceId).m_nResidenceOwnerWorldId == worldId ? 1 : 0;
}

