char16_t* CNPC::PrepareSiegeTime(int addFollowingDay, int addHalfDay, int hour, int minute) {
    L2_GUARD_FUNCTION();
    std::int32_t timestamp = runtime::crt::Time32Now();

    std::tm localStorage{};
    std::tm* local = runtime::crt::LocalTime32(timestamp, localStorage) ? &localStorage : nullptr;
    std::uint32_t result = static_cast<std::uint32_t>(timestamp);
    if (local->tm_wday == 6) {
        result += 14U * 24U * 60U * 60U;
    } else {
        result += static_cast<std::uint32_t>(13 - local->tm_wday) * 24U * 60U * 60U;
    }

    timestamp = runtime::Int32FromBits(result);
    local = runtime::crt::LocalTime32(timestamp, localStorage) ? &localStorage : nullptr;
    result -= (static_cast<std::uint32_t>(local->tm_hour) * 60U + static_cast<std::uint32_t>(local->tm_min)) * 60U +
        static_cast<std::uint32_t>(local->tm_sec);
    if (addFollowingDay != 0) {
        result += 24U * 60U * 60U;
    }
    if (addHalfDay != 0) {
        result += 12U * 60U * 60U;
    }
    result += (static_cast<std::uint32_t>(hour) * 60U + static_cast<std::uint32_t>(minute)) * 60U;

    return Wctime32(runtime::Int32FromBits(result));
}

char16_t* CNPC::Castle_GetSiegeTime() {
    const int residenceId = m_data->m_nResidenceID;
    const std::int32_t nextSiege = CResidenceData::Inst(residenceId).m_NextSiege;
    if (CResidenceData::Inst(residenceId).m_ResidenceState == RS_ANNOUNCING || nextSiege == 0) {
        return EmptyScriptString();
    }

    std::tm localStorage{};
    std::tm* const local = runtime::crt::LocalTime32(nextSiege, localStorage) ? &localStorage : nullptr;
    char16_t* const output = AllocTmpString(0x14);
    if (!output) {
        // Log.Add(LOG_ERROR, L"[%s][%d] Can't allocate buffer for fstring", kNpcSourceFileW, 0x2c75)
        // Log.Add(LOG_ERROR,
        //     "[NPC siege] NPC %u cannot allocate the 20-unit siege-time string for residence %d. Returning an empty
        //     string.", static_cast<unsigned int>(Id()), residenceId)
        L2_LOG_ERROR(
            Log,
            "[NPC siege] NPC %u cannot allocate the 20-unit siege-time string for residence %d; returning an empty string.",
            static_cast<unsigned int>(Id()), residenceId
        );
        return EmptyScriptString();
    }
    const std::u16string value = FormatLegacyReport(
        u"%04d-%02d-%02d %02d:%02d:%02d", local->tm_year + 1900, local->tm_mon + 1, local->tm_mday, local->tm_hour,
        local->tm_min, local->tm_sec
    );
    std::copy(value.begin(), value.end(), output);
    output[value.size()] = u'\0';
    return output;
}

