void CNPC::Castle_GetRelatedFortressList(CSharedCreatureData* creature) {
    L2_GUARD_FUNCTION();
    const int residenceId = m_data->m_nResidenceID;
    CResidenceData* const related4Source = &CResidenceData::Inst(residenceId);
    CResidenceData* const related3Source = &CResidenceData::Inst(residenceId);
    CResidenceData* const related2Source = &CResidenceData::Inst(residenceId);
    CResidenceData* const related1Source = &CResidenceData::Inst(residenceId);
    CResidenceData* const related0Source = &CResidenceData::Inst(residenceId);
    const int related4 = related4Source->m_nRelatedFortress[4];
    const int related3 = related3Source->m_nRelatedFortress[3];
    const int related2 = related2Source->m_nRelatedFortress[2];
    const int related1 = related1Source->m_nRelatedFortress[1];
    const int related0 = related0Source->m_nRelatedFortress[0];
    CNPCEvent* const event = CNPCEventFactory::CreateGetRelatedFortressListReturned(
        this, creature, related0, related1, related2, related3, related4
    );
    if (!event) {
        // Log.Add(LOG_ERROR, L"[%s][%d] Event failed", kNpcSourceFileW, 0x2b47)
        // Log.Add(LOG_ERROR,
        //     "[NPC siege] NPC %u cannot create the related-fortress-list event for residence %d. AI callback not
        //     delivered.", static_cast<unsigned int>(Id()), residenceId)
        L2_LOG_ERROR(
            Log,
            "[NPC siege] NPC %u cannot create the related-fortress-list event for residence %d; AI callback not delivered.",
            static_cast<unsigned int>(Id()), residenceId
        );
        return;
    }
    HandleEvent(event);
    L2_RELEASE(event, ObjectRefType::CreateDelete);
}

