int CNPC::InstantAgit_GetDecoData(CSharedCreatureData* creature, int selector, int field) {
    // Current L2NPC.exe 0x00485a18.
    L2_GUARD_FUNCTION();
    // The current executable accepts 1..31, not the full
    // 32-slot adjacent-PDB array.
    if (!creature || static_cast<unsigned int>(selector - 1) >= 31u) {
        return -1;
    }
    SharedInstantAgitDeco* const data = SharedInstantAgitDecoData::GetInfo(creature->m_nPledgeID);
    if (!data) {
        return -1;
    }
    const SharedInstantAgitDeco::InstantAgitDecoSlot& value = data->decoInfo[static_cast<std::size_t>(selector - 1)];
    if (field == 0) {
        return value.agitDecoId;
    }
    if (field == 1) {
        return value.agitDecoLevel;
    }
    if (field == 2) {
        return runtime::Win64CvttDoubleToInt32(value.agitDecoPower);
    }
    return -1;
}

