int CNPC::HasSubPledge(CSharedCreatureData* creature, int pledgeType) {
    // Current L2NPC.exe 0x004a1a44.
    L2_GUARD_FUNCTION();
    CSharedPledgeData* const pledge = GetPledge(creature);
    if (!pledge) {
        return 0;
    }
    const unsigned int index = g_PledgeTypeValidator.GetIndex(static_cast<PledgeType>(pledgeType));
    if (index >= 8u) {
        throw std::out_of_range("invalid bitset<N> position");
    }
    return (pledge->m_subPledgeTypeBits & (1u << index)) != 0 ? 1 : 0;
}

