int CNPC::Castle_GetPledgeState(CSharedCreatureData* creature) {
    // Current L2NPC.exe 0x004a6384.
    L2_GUARD_FUNCTION();
    if (!creature) {
        return 0;
    }
    if (creature->m_nDominionSiegeId == m_data->m_nResidenceID) {
        return 2;
    }
    CSharedPledgeData* const pledge = GetPledge(creature);
    if (!pledge) {
        return 0;
    }
    const int residenceId = m_data->m_nResidenceID;

    const int castleIndex = residenceId - 1;
    if (static_cast<unsigned int>(castleIndex) > 9u) {
        // Log.Add(LOG_ERROR, L"[Siege][%s][%d] castle_index is wrong!! [%d]", L"NPC.cpp", 0x2d6e, castleIndex)
        // Log.Add(LOG_ERROR,
        //     "[NPC siege] NPC %u cannot read pledge siege state for residence %d: castle index %d is outside 0..9.
        //     returning 0.", static_cast<unsigned int>(Id()), residenceId, castleIndex)
        L2_LOG_ERROR(
            Log,
            "[NPC siege] NPC %u cannot read pledge siege state for residence %d: castle index %d is outside 0..9; returning "
            "0.",
            static_cast<unsigned int>(Id()), residenceId, castleIndex
        );
        ReportCallStackNew(const_cast<wchar_t*>(L"Siege"), LOG_ERROR, false);
        return 0;
    }

    // The target admits index nine. At that index the first
    // read reaches status[0], and the second reaches the following fortress
    // offence field.
    const int registeredCastle =
        castleIndex < 9 ? pledge->m_nNowCastleSiegeDbId[castleIndex] : pledge->m_nNowCastleSiegeStatus[0];
    if (registeredCastle == residenceId) {
        return castleIndex < 9 ? pledge->m_nNowCastleSiegeStatus[castleIndex]
                               : static_cast<int>(pledge->m_nFortressUnderOffenceSiegeId);
    }
    return static_cast<int>(pledge->m_nDominionSiegeId) == residenceId ? 2 : 0;
}

int CNPC::Castle_GetPledgeReserveState(CSharedCreatureData* creature) {
    // Current L2NPC.exe 0x004a64d4 assumes this CNPC has shared data.
    L2_GUARD_FUNCTION();
    if (!creature) {
        return 0;
    }
    const int residenceId = m_data->m_nResidenceID;
    if (creature->m_nDominionSiegeId == residenceId) {
        return 2;
    }
    CSharedPledgeData* const pledge = GetPledge(creature);
    if (!pledge) {
        return 0;
    }
    if (static_cast<int>(pledge->m_nReservedOffenceCastleSiegeDbId) == residenceId) {
        return 1;
    }
    return static_cast<int>(pledge->m_nReservedDefenceCastleSiegeDbId) == residenceId ? 2 : 0;
}

