int CNPC::HavePledgePower(CSharedCreatureData* creature, int power) {
    // Current L2NPC.exe 0x004a66ac and the nearby PDB both use int.
    L2_GUARD_FUNCTION();
    if (creature->m_bPledgeMaster) {
        return 1;
    }
    const int rank = creature->m_nGradeId;
    if (rank < 1 || rank > 9) {
        return 0;
    }
    CSharedPledgeData* const pledge = GetPledge(creature);
    if (!pledge) {
        return 0;
    }
    if (static_cast<unsigned int>(power) >= 25u) {
        throw std::out_of_range("invalid bitset<N> position");
    }
    return static_cast<int>((pledge->m_gradePowerList[rank - 1] >> power) & 1u);
}

CSharedCreatureData* CNPC::Pledge_GetCreature(CSharedCreatureData* creature, int memberIndex) {
    // Current L2NPC.exe 0x004a67e0.
    L2_GUARD_FUNCTION();
    CSharedPledgeData* const pledge = GetPledge(creature);
    if (!pledge) {
        return nullptr;
    }

    int onlineIndex = 0;
    for (const IdIndexPair& member : pledge->m_OnlineMember) {
        if (member.id == 0) {
            continue;
        }
        if (onlineIndex == memberIndex) {
            return CCreatureFactory::Inst().GetData(static_cast<int>(member.index));
        }
        ++onlineIndex;
    }
    return nullptr;
}

