// L2NPC.exe 0x00487ba4. The shipping implementation accepts
// the shared-record pointer as-is and always reports success after sending.
bool CNPC::SetPledgeRaidPoint(CSharedPledgeData* pledge, std::int64_t point) {
    L2_GUARD_FUNCTION();
    g_ns.Send(
        "chdddQ", 0xfe, 0x30, static_cast<int>(Id()), static_cast<int>(pledge->m_nDbId), pledge->index,
        static_cast<long long>(point)
    );
    return true;
}

