void CNPC::GiveItemByCastleSiegeDefence(
    CSharedCreatureData* creature, int itemClassId, int reason, int argument, std::int64_t count
) {
    // Current L2NPC.exe 0x004a24e4.
    L2_GUARD_FUNCTION();
    if (itemClassId < 1 || reason < 0 || count < 0 || argument < 0) {
        // Log.Add(LOG_ERROR, L"GiveItemByCastleSiegeDefence param is not valid")
        // Log.Add(LOG_ERROR,
        //     "[NPC reward] NPC %u cannot request a castle-defence reward: item class %d must be positive. Reason %d,
        //     argument %d and count %lld must be non-negative, request not sent.", static_cast<unsigned int>(Id()),
        //     itemClassId, reason, argument, static_cast<long long>(count))
        L2_LOG_ERROR(
            Log,
            "[NPC reward] NPC %u cannot request a castle-defence reward: item class %d must be positive; reason %d, "
            "argument %d and count %lld must be non-negative; request not sent.",
            static_cast<unsigned int>(Id()), itemClassId, reason, argument, static_cast<long long>(count)
        );
        return;
    }
    if (!GetPledge(creature)) {
        return;
    }
    const int pledgeId = runtime::Int32FromBits(creature->m_nPledgeID);
    const int creatureId = runtime::Int32FromBits(creature->m_nId);
    const int npcId = runtime::Int32FromBits(m_nId);
    g_ns.Send("cddddddQ", 0xa6, npcId, creatureId, pledgeId, itemClassId, reason, argument, static_cast<long long>(count));
}

void CNPC::LookNeighbor(int argument) {
    L2_GUARD_FUNCTION();
    if (g_LookNeighborTick != 0 && CanAct()) {
        LookNeighbor1(argument);
    }
}

void CNPC::LookNeighbor1(int argument) {
    // Current L2NPC.exe 0x0048a86c assumes the shared record exists.
    L2_GUARD_FUNCTION();
    if (!m_data->GetEventFlag(NEF_SEE_CREATURE)) {
        return;
    }
    const std::uint32_t now = runtime::GetTickCount();
    if (g_LookNeighborTick >= now - m_dwLastLookNeighborTick) {
        return;
    }
    m_dwLastLookNeighborTick = now;
    g_ns.Send("cdd", 0x50, static_cast<int>(Id()), argument);
}

void CreateOnePrivatePacketHelper::Send(const PrivatePacketParam& param) {
    // Current L2NPC.exe 0x00470ff8.
    L2_GUARD_FUNCTION();
    g_ns.Send(
        "cdddpSddddddddddddd", 0x1e, param.m_BossId, param.m_ClassId, param.m_PrivateId, param.m_pSpawnDefine,
        param.m_AiName, param.m_WeightPoint, param.m_RespawnTime, static_cast<int>(param.m_Pos.x),
        static_cast<int>(param.m_Pos.y), static_cast<int>(param.m_Pos.z), param.m_Dir, param.m_MakerId, param.m_P1,
        param.m_P2, param.m_P3, param.m_Fixed, param.m_InzoneId, param.m_nDroidMasterCharSID
    );
}

CPartyPrivateCreator::CPartyPrivateCreator(
    CNPC* boss, int classId, const char16_t* aiName, int privateWeightPoint, int respawnTime, int droidMasterCharSid
) :
    m_nClassID(classId),
    m_nPrivateWeightPoint(privateWeightPoint),
    m_nRespawnTime(respawnTime),
    m_nBossID(static_cast<std::uint32_t>(boss->Id())),
    m_sAI(aiName),
    m_vBossPos(boss->m_data->GetPos()),
    m_pSpawnDefine(boss->SpawnDefine()),
    m_EventID(GetCurrentNPCEventID()),
    m_PrivateID(boss->m_data->m_nPrivateID),
    m_nDroidMasterCharSID(droidMasterCharSid) {
    if (m_pSpawnDefine) {
        L2_ADD_REF(m_pSpawnDefine, ObjectRefType::NpcRelated);
    }
}

CPartyPrivateCreator::~CPartyPrivateCreator() {
    if (m_pSpawnDefine) {
        L2_RELEASE(m_pSpawnDefine, ObjectRefType::NpcRelated);
        m_pSpawnDefine = nullptr;
    }
}

void CPartyPrivateCreator::TimerExpired(int) {
    L2_GUARD_FUNCTION();
    CNPC* const boss = CNPC::GetObjectW(static_cast<int>(m_nBossID));
    if (m_EventID == 0x14 && (!boss || !boss->m_data->m_bIsActive || boss->m_data->m_bIsAlive == 0)) {
        L2_RELEASE(this, ObjectRefType::CreateDelete, true);
        return;
    }
    if (!m_pSpawnDefine->ReserveNPC()) {
        LogPrivateReserveFailure(m_nClassID);
        L2_RELEASE(this, ObjectRefType::CreateDelete, true);
        return;
    }

    if (boss) {
        m_vBossPos = boss->m_data->GetPos();
    }
    FVector spawnPosition = m_vBossPos;
    for (int attempt = 0; attempt < 10; ++attempt) {
        FVector candidate;
        if (GetRandomSpawnPos(spawnPosition, boss, candidate)) {
            spawnPosition = candidate;
            break;
        }
    }

    const int packetInzoneId = boss ? boss->m_data->m_nInstantZoneID : 0;
    const char16_t* const packetAiName = m_sAI.c_str();
    const int packetDroidMasterCharSid = m_nDroidMasterCharSID;
    const int packetRespawnTime = m_nRespawnTime;
    const int packetWeightPoint = m_nPrivateWeightPoint;
    BaseSpawnDefine* const packetSpawnDefine = m_pSpawnDefine;
    const int packetPrivateId = m_PrivateID;
    const int packetClassId = m_nClassID;
    const int packetBossId = static_cast<int>(m_nBossID);

    PrivatePacketParam packet;
    packet.m_BossId = packetBossId;
    packet.m_ClassId = packetClassId;
    packet.m_PrivateId = packetPrivateId;
    packet.m_pSpawnDefine = packetSpawnDefine;
    packet.m_AiName = packetAiName;
    packet.m_WeightPoint = packetWeightPoint;
    packet.m_RespawnTime = packetRespawnTime;
    packet.m_Pos = spawnPosition;
    packet.m_InzoneId = packetInzoneId;
    packet.m_nDroidMasterCharSID = packetDroidMasterCharSid;
    CreateOnePrivatePacketHelper::Send(packet);
    RecordPrivateCreate();
    L2_RELEASE(this, ObjectRefType::CreateDelete, true);
}

