void CNPC::CreateOnePrivate(int classId, const char16_t* aiName, int privateWeightPoint, int respawnTime) {
    L2_GUARD_FUNCTION();
    m_bBoss = true;
    auto* const creator = new CPartyPrivateCreator(this, classId, aiName, privateWeightPoint, respawnTime, 0);
    creator->AddTimer(TimerDelayMilliseconds(respawnTime), 0);
    // Current L2NPC.exe 0x004aa004 supplies only two stack DWORDs for the
    // three trailing `d` fields in "chddd". The last field is genuinely
    // read from the call site's residual vararg area.
    g_ns.Send("chddd", 0xfe, 0x27, classId, respawnTime);
}

void CNPC::CreateOneAnother(int classId, const char16_t* aiName, int x, int y, int z) {
    // Current L2NPC.exe 0x00471518. NPCServer's "cdSddd" format ignores
    // the additional instant-zone-id vararg supplied by the target call site.
    L2_GUARD_FUNCTION();
    g_ns.Send("cdSddd", 0xf4, classId, aiName, x, y, z, m_data->m_nInstantZoneID);
}

int CNPC::CreateOnePrivateEx(
    int classId,
    const char16_t* aiName,
    int privateWeightPoint,
    int respawnTime,
    int x,
    int y,
    int z,
    int direction,
    int p1,
    int p2,
    int p3
) {
    L2_GUARD_FUNCTION();
    if (!m_pSpawnDefine) {
        const std::string hostAiName = Utf16ToUtf8(std::u16string_view(aiName));
        // Log.Add(LOG_ERROR, L"CreateOnePrivateInzoneEx null spawn define [%d][%s]", classId, hostAiName.c_str())
        // Log.Add(LOG_ERROR,
        //     "[NPC spawn] CreateOnePrivateEx cannot schedule class %d: parent NPC %u has no spawn definition. Returning key
        //     0. AI '%s'.", classId, static_cast<unsigned int>(Id()), WideToUtf8(hostAiName).c_str())
        L2_LOG_ERROR(
            Log,
            "[NPC spawn] CreateOnePrivateEx cannot schedule class %d: parent NPC %u has no spawn definition; returning key "
            "0. AI '%s'.",
            classId, static_cast<unsigned int>(Id()), hostAiName.c_str()
        );
        return 0;
    }
    const int makerId = m_pSpawnDefine->CreateMakerKey();
    m_bBoss = true;
    auto* const creator = new CPartyPrivateCreatorEx(
        this, classId, aiName, privateWeightPoint, respawnTime, x, y, z, direction, p1, p2, p3, makerId, 0
    );
    creator->AddTimer(TimerDelayMilliseconds(respawnTime), 0);
    return makerId;
}

