void CNPC::CreatePrivates(char16_t* value) {
    // Current L2NPC.exe 0x004a8eec. StringTokenizer's current bodies are
    // 0x00539c64-0x0053a22f.
    L2_GUARD_FUNCTION();
    if (!value || value[0] == u'\0') {
        const std::string hostNpcName = Utf16ToUtf8(GetName());
        // Log.Add(LOG_ERROR, L"CreatePrivates private null. [%s]", hostNpcName.c_str())
        // Log.Add(LOG_ERROR,
        //     "[NPC spawn] CreatePrivates has no private-NPC specification (%s). No creation requests sent for NPC '%s'.",
        //     value ? "empty text" : "null text", WideToUtf8(hostNpcName).c_str())
        L2_LOG_ERROR(
            Log, "[NPC spawn] CreatePrivates has no private-NPC specification (%s); no creation requests sent for NPC '%s'.",
            value ? "empty text" : "null text", hostNpcName.c_str()
        );
        ReportScriptContext(LOG_ERROR);
        return;
    }

    const std::u16string specification = CopyCreatePrivatesText(value);
    StringTokenizer entries(specification, std::u16string(u";"));
    FVector anchor = m_data->GetPos();
    int entryCount = entries.CountTokens();
    for (int entryIndex = 0; entryIndex < entryCount;) {
        const std::u16string entryText = entries.NextToken();
        StringTokenizer fields(entryText, std::u16string(u":"));

        const std::u16string npcName = fields.NextToken();
        if (npcName.empty()) {
            // Log.Add(LOG_ERROR, "invalid privates string at file[%s, line[%d]", kNpcSourceFile, 0x267f)
            // Log.Add(LOG_ERROR,
            //     "[NPC spawn] CreatePrivates stopped at entry %d for NPC %u: NPC name is missing. Remaining entries are
            //     skipped.", entryIndex + 1, static_cast<unsigned int>(Id()))
            L2_LOG_ERROR(
                Log,
                "[NPC spawn] CreatePrivates stopped at entry %d for NPC %u: NPC name is missing; remaining entries are "
                "skipped.",
                entryIndex + 1, static_cast<unsigned int>(Id())
            );
            break;
        }

        const std::u16string aiName = fields.NextToken();
        if (aiName.empty()) {
            // Log.Add(LOG_ERROR, "invalid privates string at file[%s], line[%d]", kNpcSourceFile, 0x2686)
            // Log.Add(LOG_ERROR,
            //     "[NPC spawn] CreatePrivates stopped at entry %d for NPC %u: AI name is missing for private '%s'. Remaining
            //     entries are skipped.", entryIndex + 1, static_cast<unsigned int>(Id()),
            //     Utf16ToUtf8(npcName.view()).c_str())
            L2_LOG_ERROR(
                Log,
                "[NPC spawn] CreatePrivates stopped at entry %d for NPC %u: AI name is missing for private '%s'; remaining "
                "entries are skipped.",
                entryIndex + 1, static_cast<unsigned int>(Id()), Utf16ToUtf8(runtime::StringView(npcName)).c_str()
            );
            break;
        }

        const std::u16string weightText = fields.NextToken();
        if (weightText.empty()) {
            // Log.Add(LOG_ERROR, "invalid privates string at file[%s], line[%d]", kNpcSourceFile, 0x268c)
            // Log.Add(LOG_ERROR,
            //     "[NPC spawn] CreatePrivates stopped at entry %d for NPC %u: weight field is missing for private '%s'.
            //     remaining entries are skipped.", entryIndex + 1, static_cast<unsigned int>(Id()),
            //     Utf16ToUtf8(npcName.view()).c_str())
            L2_LOG_ERROR(
                Log,
                "[NPC spawn] CreatePrivates stopped at entry %d for NPC %u: weight field is missing for private '%s'; "
                "remaining entries are skipped.",
                entryIndex + 1, static_cast<unsigned int>(Id()), Utf16ToUtf8(runtime::StringView(npcName)).c_str()
            );
            break;
        }

        const std::u16string respawnText = fields.NextToken();
        // The shipping fourth-field check accidentally examines the third
        // token again (NPC.cpp line 0x2692).
        if (weightText.empty()) {
            // Noise: The same immutable weight token was checked above. This duplicate recovered check cannot add another
            // actionable diagnostic. Log.Add(LOG_ERROR, "invalid privates string at file[%s], line[%d]", kNpcSourceFile,
            // 0x2692)
            break;
        }

        const int npcClassId = LowCreatePrivatesClassId(g_PrecompiledHeaderDB.Search(npcName.c_str()));
        const int weightPoint = ParseCreatePrivatesInt32(runtime::StringView(weightText));
        const int respawnTime = ParseCreatePrivatesRespawnTime(respawnText);
        if (npcClassId < 0) {
            const std::string hostNpcName = Utf16ToUtf8(runtime::StringView(npcName));
            // Log.Add(LOG_ERROR, "invalid npc name [%S] at file[%s], line[%d]", hostNpcName.c_str(), kNpcSourceFile,
            // 0x26ad), Log.Add(LOG_ERROR,
            //     "[NPC spawn] CreatePrivates stopped at entry %d for NPC %u: private name '%s' resolved to invalid class ID
            //     %d, remaining entries are skipped.", entryIndex + 1, static_cast<unsigned int>(Id()),
            //     WideToUtf8(hostNpcName).c_str(), npcClassId)
            L2_LOG_ERROR(
                Log,
                "[NPC spawn] CreatePrivates stopped at entry %d for NPC %u: private name '%s' resolved to invalid class ID "
                "%d; remaining entries are skipped.",
                entryIndex + 1, static_cast<unsigned int>(Id()), hostNpcName.c_str(), npcClassId
            );
            break;
        }

        if (!m_pSpawnDefine->ReserveNPC()) {
            break;
        }
        m_bBoss = true;
        for (int attempt = 0; attempt < 10; ++attempt) {
            FVector candidate;
            if (GetRandomSpawnPos(anchor, this, candidate)) {
                anchor = candidate;
                break;
            }
        }

        const char16_t* const packetAiName = aiName.c_str();
        BaseSpawnDefine* const packetSpawnDefine = m_pSpawnDefine;
        const int packetInzoneId = m_data->m_nInstantZoneID;
        const int packetPrivateId = m_data->m_nPrivateID;
        const int packetBossId = static_cast<int>(Id());

        PrivatePacketParam packet;
        packet.m_BossId = packetBossId;
        packet.m_ClassId = npcClassId;
        packet.m_PrivateId = packetPrivateId;
        packet.m_pSpawnDefine = packetSpawnDefine;
        packet.m_AiName = packetAiName;
        packet.m_WeightPoint = weightPoint;
        packet.m_RespawnTime = respawnTime;
        packet.m_Pos = anchor;
        packet.m_InzoneId = packetInzoneId;
        CreateOnePrivatePacketHelper::Send(packet);
        RecordPrivateCreate();

        ++entryIndex;
        entryCount = entries.CountTokens();
    }
}

void CNPC::CreateOnePrivateNearUser(
    CSharedCreatureData* talker, int classId, const char16_t* aiName, int x, int y, int z, int direction
) {
    L2_GUARD_FUNCTION();
    if (!talker || !aiName) {
        return;
    }

    const int bossId = static_cast<int>(Id());
    const std::u16string copiedAiName(aiName);
    CCreature* const source = CCreature::GetObjectW(static_cast<std::uint32_t>(bossId));
    if (!source) {
        return;
    }

    BaseSpawnDefine* const definition = m_pSpawnDefine;
    if (!definition) {
        return;
    }
    L2_ADD_REF(definition, ObjectRefType::NpcRelated);
    m_bBoss = true;

    const int eventId = GetCurrentNPCEventID();
    const int privateId = m_data->m_nPrivateID;
    if (eventId == 0x14 && (!source->m_data->m_bIsActive || source->m_data->m_bIsAlive == 0)) {
        L2_RELEASE(definition, ObjectRefType::NpcRelated);
        return;
    }
    if (!definition->ReserveNPC()) {
        LogPrivateReserveFailure(classId);
        L2_RELEASE(definition, ObjectRefType::NpcRelated);
        return;
    }

    g_ns.Send(
        "cddddpSdddddddd", 0xe6, talker->index, bossId, classId, privateId, definition, copiedAiName.c_str(), x, y, z, 0, 0,
        0, 0, direction
    );
    RecordPrivateCreate();
    L2_RELEASE(definition, ObjectRefType::NpcRelated);
}

