char16_t* CNPC::Lotto_GetChooseTime() {
    // Current L2NPC.exe 0x004952e4.
    L2_GUARD_FUNCTION();
    const std::u16string value = l2npc::g_LottoGameManager.GetChooseTime();
    const int valueLength = runtime::Int32FromBits(static_cast<std::uint32_t>(value.size()));
    char16_t* const output = AllocTmpString(runtime::Int32FromBits(static_cast<std::uint32_t>(valueLength) + 1U));
    if (!output) {
        // Log.Add(LOG_ERROR, L"[%s][%d] Can't allocate buffer for fstring", kNpcSourceFileW, 0x38a4)
        // Log.Add(LOG_ERROR,
        //     "[lottery] Cannot allocate temporary text for the draw time (%d UTF-16 units) requested by NPC %u. Returning
        //     an empty string.", valueLength, static_cast<unsigned int>(Id()))
        L2_LOG_ERROR(
            Log,
            "[lottery] Cannot allocate temporary text for the draw time (%d UTF-16 units) requested by NPC %u; returning an "
            "empty string.",
            valueLength, static_cast<unsigned int>(Id())
        );
        return EmptyScriptString();
    }

    const std::size_t copyLength = static_cast<std::size_t>(valueLength);
    const std::size_t destinationLength = static_cast<std::size_t>(GetTmpStringEnd() - output);
    if (copyLength < destinationLength) {
        std::char_traits<char16_t>::copy(output, value.data(), copyLength);
    }
    // The shipping body performs one 32-bit zero store beginning at
    // valueLength-1. GetChooseTime always supplies a non-empty string.
    output[valueLength - 1] = u'\0';
    output[valueLength] = u'\0';
    return output;
}

char16_t* CNPC::Lotto_GetChosenNumber() {
    // Current L2NPC.exe 0x00495450.
    L2_GUARD_FUNCTION();
    const std::u16string value = l2npc::g_LottoGameManager.GetChosenNumberString();
    const int valueLength = runtime::Int32FromBits(static_cast<std::uint32_t>(value.size()));
    char16_t* const output = AllocTmpString(runtime::Int32FromBits(static_cast<std::uint32_t>(valueLength) + 1U));
    if (!output) {
        // Log.Add(LOG_ERROR, L"[%s][%d] Can't allocate buffer for fstring", kNpcSourceFileW, 0x398a)
        // Log.Add(LOG_ERROR,
        //     "[lottery] Cannot allocate temporary text for the chosen numbers (%d UTF-16 units) requested by NPC %u.
        //     returning an empty string.", valueLength, static_cast<unsigned int>(Id()))
        L2_LOG_ERROR(
            Log,
            "[lottery] Cannot allocate temporary text for the chosen numbers (%d UTF-16 units) requested by NPC %u; "
            "returning an empty string.",
            valueLength, static_cast<unsigned int>(Id())
        );
        return EmptyScriptString();
    }

    const std::size_t copyLength = static_cast<std::size_t>(valueLength);
    const std::size_t destinationLength = static_cast<std::size_t>(GetTmpStringEnd() - output);
    if (copyLength < destinationLength) {
        std::char_traits<char16_t>::copy(output, value.data(), copyLength);
    }
    output[valueLength] = u'\0';
    return output;
}

