void CNPC::Lotto_ShowBuyingPage(CSharedCreatureData* target, int numberFlag, CFHTML* html) {
    // Current L2NPC.exe 0x004ac92c.
    L2_GUARD_FUNCTION();
    if (l2npc::g_LottoGameManager.IsPaused()) {
        return;
    }

    html->Set(u"round", l2npc::g_LottoGameManager.GetRoundNumber());

    const std::uint32_t selectedMask = static_cast<std::uint32_t>(numberFlag);
    int selectedCount = 0;
    for (unsigned bit = 0; bit < 20; ++bit) {
        if ((selectedMask & (1U << bit)) != 0) {
            ++selectedCount;
        }
    }
    if (selectedCount >= 6) {
        const std::string targetName = Utf16ToUtf8(target->Name());
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] Lotto_ShowBuyingPage. "
        //     L"hacking user[%s]",
        //     kNpcSourceFileW, 0x38cc, targetName.c_str()
        // )
        // Log.Add(LOG_WARN,
        //     "[lottery] Selection 0x%08x contains %d of the 20 numbers. At most 5 are allowed. Buying page not shown to
        //     '%s'.", static_cast<unsigned int>(selectedMask), selectedCount, WideToUtf8(targetName).c_str())
        L2_LOG_WARN(
            Log,
            "[lottery] Selection 0x%08x contains %d of the 20 numbers; at most 5 are allowed. Buying page not shown to "
            "'%s'.",
            static_cast<unsigned int>(selectedMask), selectedCount, targetName.c_str()
        );
        return;
    }

    std::u16string body;
    for (int row = 0; row < 4; ++row) {
        body += u"<tr>";
        for (int column = 0; column < 5; ++column) {
            const std::size_t numberIndex = static_cast<std::size_t>(row * 5 + column);
            const std::uint32_t bit = 1U << numberIndex;
            const bool selected = (selectedMask & bit) != 0;
            const std::u16string_view normal = kLottoNumberImages[numberIndex];
            const std::u16string_view checked = kCheckedLottoNumberImages[numberIndex];

            body += u"<td>";
            if (!selected && selectedCount == 5) {
                body += u"<button action=\"\" fore=\"";
                body.append(checked.data(), checked.size());
                body += u"\" back=\"";
                body.append(normal.data(), normal.size());
                body += u"\" width=40 height=20></button>";
            } else {
                const std::uint32_t reply = selected ? selectedMask & ~bit : selectedMask | bit;
                body += u"<button action=\"bypass "
                        u"menu_selected?ask=-777&reply=";
                AppendDecimal(body, runtime::Int32FromBits(reply));
                body += u"\" fore=\"";
                const std::u16string_view fore = selected ? normal : checked;
                body.append(fore.data(), fore.size());
                body += u"\" back=\"";
                const std::u16string_view back = selected ? checked : normal;
                body.append(back.data(), back.size());
                body += u"\" width=40 height=20></button>";
            }
            body += u"</td>";
        }
        body += u"</tr>";
    }
    html->Set(u"str", body.c_str());

    std::u16string tail;
    if (selectedCount != 5) {
        tail = u"<br><A action=\"Link lotto007.htm\">";
        tail += LottoFString(1000170);
        tail += u"</a><br>";
    } else {
        tail = u"<br><a action=\"bypass -h "
               u"menu_selected?ask=-778&reply=";
        AppendDecimal(tail, numberFlag);
        tail += u"\">";
        tail += LottoFString(1000179);
        tail += u"</a>";
    }
    html->Set(u"tail", tail.c_str());
    ShowFHTML(target, html);
}

void CNPC::Lotto_BuyTicket(CSharedCreatureData* target, int numberFlag, int price) {
    // Current L2NPC.exe 0x004a1528 relies on the native-call argument
    // contract and only checks the process-wide pause flag here.
    L2_GUARD_FUNCTION();
    if (l2npc::g_LottoGameManager.IsPaused()) {
        return;
    }

    const int state = l2npc::g_LottoGameManager.GetTopState();
    const int roundNumber = l2npc::g_LottoGameManager.GetRoundNumber();
    if (state != 1) {
        // Noise: Ticket sales have closed. An outdated buying page can still submit this request. The normal rejection
        // queues neither payment nor ticket. Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] Lotto_BuyTicket failed. "
        //     L"state[%d]!=LTS_SELLING",
        //     kNpcSourceFileW, 0x3953, l2npc::g_LottoGameManager.GetTopState()
        // )
        return;
    }

    int selectedCount = 0;
    const std::uint32_t mask = static_cast<std::uint32_t>(numberFlag);
    for (unsigned bit = 0; bit < 20; ++bit) {
        if ((mask & (1U << bit)) != 0) {
            ++selectedCount;
        }
    }
    if (selectedCount != 5) {
        const std::string targetName = Utf16ToUtf8(target->Name());
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] Lotto_BuyTicket failed. "
        //     L"invalid bit flag. hack? user[%s]",
        //     kNpcSourceFileW, 0x3959, targetName.c_str()
        // )
        // Log.Add(LOG_WARN,
        //     "[lottery] Purchase rejected: selection 0x%08x contains %d of the 20 numbers. Exactly 5 are required. No
        //     payment or ticket queued for '%s'.", static_cast<unsigned int>(mask), selectedCount,
        //     WideToUtf8(targetName).c_str())
        L2_LOG_WARN(
            Log,
            "[lottery] Purchase rejected: selection 0x%08x contains %d of the 20 numbers; exactly 5 are required. No "
            "payment or ticket queued for '%s'.",
            static_cast<unsigned int>(mask), selectedCount, targetName.c_str()
        );
        return;
    }
    CScriptEngine::AddAtomicItemProcess(target->index, 0x39, -static_cast<std::int64_t>(price), -1, 0);

    CScriptEngine::AddAtomicItemProcess(target->index, 0x115a, 1, numberFlag, roundNumber);
    const int targetSid = CCreatureFactory::Inst().GetIdByIndex(target->index);
    auto* const job = new AtomicBuyLottoTicket(targetSid, roundNumber, numberFlag);
    CScriptEngine::AddAtomicJob(target->index, job);
}

void CNPC::Lotto_ShowPrevRewardPage(CSharedCreatureData* target, int page) {
    // Current L2NPC.exe 0x004b5344.
    L2_GUARD_FUNCTION();
    if (l2npc::g_LottoGameManager.IsPaused()) {
        return;
    }

    std::u16string html = u"<html><body>";
    const int currentRoundNumber = l2npc::g_LottoGameManager.GetRoundNumber();
    int displayedCount = 0;
    {
        CInventory inventory;
        inventory.SetIndex(target->index, target->m_bIsUser);
        L2_READ_GUARD(inventory);

        const std::u16string roundLabel = LottoFString(1000172);
        const std::array<std::u16string, 5> rewardLabels{{
            {},
            LottoFString(1000173),
            LottoFString(1000174),
            LottoFString(1000175),
            LottoFString(1000176),
        }};

        for (CSharedItemData* item = inventory.GetFirst(); item; item = item->Next()) {
            const int roundNumber = item->m_bBlessed;
            if (item->m_nClassID != 0x115a || roundNumber >= currentRoundNumber ||
                item->m_nDBID == g_CurrentLottoTicketDatabaseId || l2npc::g_LottoGameManager.GetState(roundNumber) == 0) {
                continue;
            }

            int rewardRank = 0;
            l2npc::g_LottoGameManager.CalculateReward(roundNumber, item->GetEnchanted(), rewardRank);
            if (rewardRank == 0 || page > displayedCount) {
                // This counter order is the shipping 0x004b55f1 branch:
                // a positive cursor cannot advance past skipped entries.
                continue;
            }

            const std::u16string number = l2npc::g_LottoGameManager.CastLottoNumber(item->GetEnchanted());
            std::u16string entry = u"<a action=\"bypass -h "
                                   u"menu_selected?ask=-800&reply=";
            AppendDecimal(entry, item->m_nDBID);
            entry += u"\">";
            AppendDecimal(entry, roundNumber);
            entry += u" ";
            entry += roundLabel;
            entry += u" ";
            entry.append(runtime::StringView(number).data(), runtime::StringView(number).size());
            entry += u" - ";
            entry += rewardLabels[static_cast<std::size_t>(rewardRank)];
            entry += u"</a><br1>";

            if (html.size() + entry.size() > 0xdacU) {
                html += u"<a action=\"bypass -h "
                        u"menu_selected?ask=-302&reply=";
                AppendDecimal(html, displayedCount);
                html += u"\">continued</a><br1>";
                break;
            }
            html += entry;
            ++displayedCount;
        }

        if (displayedCount == 0) {
            html += LottoFString(1000177);
        }
        html += u"<br>";
        AppendLottoNavigation(html, l2npc::g_LottoGameManager.GetTopState());
        html += u"</body></html>";
    }

    g_ns.Send("cddS", 0x11, m_data->index, target->index, html.c_str());
}

