int CNPC::GetDualClassID(CSharedCreatureData* creature) {
    // Current L2NPC.exe 0x004951f4.
    L2_GUARD_FUNCTION();
    if (!creature) {
        return -1;
    }
    CCreature* const live = CCreature::GetObjectW(static_cast<std::uint32_t>(creature->m_nId));
    if (!live) {
        return -1;
    }
    CSharedCreatureData* const data = live->m_data;

    switch (data->DualClassID()) {
        case 1:
            return data->m_nSubJob1Class;
        case 2:
            return data->m_nSubJob2Class;
        case 3:
            return data->m_nSubJob3Class;
        default:
            return -1;
    }
}

