void CNPC::PartyDied(CNPC* died) {
    L2_GUARD_FUNCTION();
    CNPCEvent* const event = CNPCEventFactory::CreatePartyDiedEvent(this, died);
    if (!event) {
        // Log.Add(LOG_ERROR, L"[%s][%d] PartyDied failed", kNpcSourceFileW, 0x582)
        // Log.Add(LOG_ERROR,
        //     "[AI event] Cannot create the party-death event for NPC %u. Continuing child notifications and private-list
        //     cleanup.", static_cast<unsigned int>(Id()))
        L2_LOG_ERROR(
            Log,
            "[AI event] Cannot create the party-death event for NPC %u; continuing child notifications and private-list "
            "cleanup.",
            static_cast<unsigned int>(Id())
        );
    } else {
        HandleEvent(event);
        L2_RELEASE(event, ObjectRefType::CreateDelete);
    }

    std::set<int> children;
    {
        L2_GUARD(m_PrivatesSect);
        children = m_sPrivates;
    }
    for (const int childId : children) {
        if (CNPC* const child = CNPC::GetObjectW(childId)) {
            child->PartyDied(died);
        }
    }

    L2_GUARD(m_PrivatesSect);
    m_sPrivates.erase(static_cast<int>(died->Id()));
}

namespace {

double DistanceSquared(const FVector& left, const FVector& right) {
    const double dx = left.x - right.x;
    const double dy = left.y - right.y;
    const double dz = left.z - right.z;
    return dx * dx + dy * dy + dz * dz;
}

double DistanceXYSquared(const FVector& left, const FVector& right) {
    const double dx = left.x - right.x;
    const double dy = left.y - right.y;
    return dx * dx + dy * dy;
}

bool IsZero(const FVector& value) { return value.x == 0.0 && value.y == 0.0 && value.z == 0.0; }

} // namespace

int CNPC::dMoveFreeway(CDesire* desirePointer) {
    // Current L2NPC.exe 0x00498538. PDB owner NPC.cpp.
    L2_GUARD_FUNCTION();
    CDesire& desire = *desirePointer;
    CNPC& npc = *this;

    CFreeway* freeway = g_FreewayManager.Find(desire.id);
    if (!freeway) {
        // Log.Add(LOG_ERROR, L"%s : invalid freewayID[%d]", L"CNPC::dMoveFreeway", desire.id)
        // Log.Add(LOG_ERROR,
        //     "[NPC route] Freeway %d was not found. Stopping movement for NPC %u.",
        //     desire.id, static_cast<unsigned int>(Id()))
        L2_LOG_ERROR(
            Log, "[NPC route] Freeway %d was not found; stopping movement for NPC %u.", desire.id,
            static_cast<unsigned int>(Id())
        );
        return 0;
    }

    CDesire::MoveSuperPointContext& state = desire.m_MoveSuperPointContext;
    // The target computes this before first-call initialization. Keeping
    // that order keeps the one-tick isLast quirk of a fresh desire.
    const bool isLast = state.m_DestIndex + 1 == freeway->GetNodeCount();
    const int previousCallCount = state.m_Revision;
    state.m_Revision = static_cast<int>(static_cast<std::uint32_t>(state.m_Revision) + 1U);

    const auto emitMove = [&](const FVector& destination) { npc.SendMovePacket(destination); };
    const auto emitTeleport = [&](const FVector& destination) {
        npc.InstantTeleport(
            npc.m_data, static_cast<int>(destination.x), static_cast<int>(destination.y), static_cast<int>(destination.z)
        );
    };
    const auto persist = [&](std::uint32_t retryMilliseconds) {
        npc.m_nTimerDelay = static_cast<int>(retryMilliseconds);
        return 1;
    };

    if (previousCallCount == 0) {
        state.m_StartIndex = 0;
        state.m_DestIndex = 1;
        CFreewayNode* first = freeway->GetNode(0);
        if (!first) {
            // Log.Add(LOG_ERROR, L"%s : invalid freeway nodeID[%d, %d]", L"CNPC::dMoveFreeway", desire.id,
            // state.m_StartIndex), Log.Add(LOG_ERROR,
            //     "[NPC route] Cannot initialize freeway %d: node index %d is unavailable. Stopping NPC %u.",
            //     desire.id, state.m_StartIndex, static_cast<unsigned int>(Id()))
            L2_LOG_ERROR(
                Log, "[NPC route] Cannot initialize freeway %d: node index %d is unavailable; stopping NPC %u.", desire.id,
                state.m_StartIndex, static_cast<unsigned int>(Id())
            );
            return 0;
        }
        emitTeleport(first->position);
    }

    CFreewayNode* node = freeway->GetNode(state.m_DestIndex);
    if (!node) {
        // Log.Add(LOG_ERROR, L"%s : invalid freeway nodeID[%d, %d]", L"CNPC::dMoveFreeway", desire.id, state.m_DestIndex)
        // Log.Add(LOG_ERROR,
        //     "[NPC route] Cannot advance along freeway %d: node index %d is unavailable. Stopping NPC %u.",
        //     desire.id, state.m_DestIndex, static_cast<unsigned int>(Id()))
        L2_LOG_ERROR(
            Log, "[NPC route] Cannot advance along freeway %d: node index %d is unavailable; stopping NPC %u.", desire.id,
            state.m_DestIndex, static_cast<unsigned int>(Id())
        );
        return 0;
    }

    const FVector position = npc.m_data->GetPos();
    const double distance = std::sqrt(DistanceSquared(position, node->position));
    const bool arrived = node->delay < 1 ? distance <= npc.m_data->m_dParam[11] : distance <= 1.0;
    if (!arrived) {
        emitMove(node->position);
        return persist(1000);
    }

    if (state.m_WaitedTime == 0) {
        CNPCEvent* const event = CNPCEventFactory::CreateNodeArrivedEvent(
            &npc, node->nodeID, node->delay, node->social, node->state, isLast ? 1 : 0
        );
        if (!event) {
            // Log.Add(LOG_ERROR, L"[%s][%d] CreateNodeArrivedEvent failed", kNpcSourceFileW, 0xe67)
            // Log.Add(LOG_ERROR,
            //     "[NPC route] Cannot create the arrival event for NPC %u at freeway %d, node %d. Route timing and
            //     advancement continue.", static_cast<unsigned int>(Id()), desire.id, node->nodeID)
            L2_LOG_ERROR(
                Log,
                "[NPC route] Cannot create the arrival event for NPC %u at freeway %d, node %d; route timing and "
                "advancement continue.",
                static_cast<unsigned int>(Id()), desire.id, node->nodeID
            );
        } else {
            npc.HandleEvent(event);
            L2_RELEASE(event, ObjectRefType::CreateDelete);
        }
    }

    if (node->delay > state.m_WaitedTime) {
        ++state.m_WaitedTime;
        return persist(1000);
    }

    state.m_WaitedTime = 0;
    ++state.m_StartIndex;
    ++state.m_DestIndex;
    if (isLast) {
        if (desire.contextValue == 0) {
            return 0;
        }
        if (desire.contextValue == 1) {
            state.m_StartIndex = 0;
            state.m_DestIndex = 1;
        } else if (desire.contextValue == 2) {
            state.m_StartIndex = 0;
            state.m_DestIndex = 1;
            CFreewayNode* first = freeway->GetNode(0);
            if (!first) {
                // Log.Add(
                //     LOG_ERROR, L"%s : invalid freeway nodeID[%d, %d]", L"CNPC::dMoveFreeway", desire.id,
                //     state.m_StartIndex
                // )
                // Log.Add(LOG_ERROR,
                //     "[NPC route] Cannot restart freeway %d: node index %d is unavailable. Stopping NPC %u.",
                //     desire.id, state.m_StartIndex, static_cast<unsigned int>(Id()))
                L2_LOG_ERROR(
                    Log, "[NPC route] Cannot restart freeway %d: node index %d is unavailable; stopping NPC %u.", desire.id,
                    state.m_StartIndex, static_cast<unsigned int>(Id())
                );
                return 0;
            }
            emitTeleport(first->position);
        } else {
            // The executable logs this but keeps the now-out-of-range state.
            // The following pass then takes the ordinary invalid-node path.
            // Log.Add(
            //     LOG_ERROR, L"%s:%d  Invalid freeway method %I64d", kNpcSourceFileW, 0xe98,
            //     static_cast<long long>(desire.contextValue)
            // )
            // Log.Add(LOG_ERROR,
            //     "[NPC route] Unsupported end mode %lld for freeway %d (expected 0..2), NPC %u. Retaining updated indices
            //     %d -> %d and retrying in 50 ms.", static_cast<long long>(desire.contextValue), desire.id,
            //     static_cast<unsigned int>(Id()), state.m_StartIndex, state.m_DestIndex)
            L2_LOG_ERROR(
                Log,
                "[NPC route] Unsupported end mode %lld for freeway %d (expected 0..2), NPC %u; retaining updated indices %d "
                "-> %d and retrying in 50 ms.",
                static_cast<long long>(desire.contextValue), desire.id, static_cast<unsigned int>(Id()), state.m_StartIndex,
                state.m_DestIndex
            );
        }
    }
    return persist(50);
}

int CNPC::dMoveFormation(CDesire* desirePointer) {
    // Current L2NPC.exe 0x0049897c. PDB owner NPC.cpp.
    L2_GUARD_FUNCTION();
    CDesire& desire = *desirePointer;
    CNPC& npc = *this;
    CFormationManager& formations = g_FormationManager;

    const bool useFreeway = desire.flags != 0;
    const bool leader = desire.formationIndex == 0;
    CFreeway* freeway = nullptr;
    const l2geo::CSuperPoint* graph = nullptr;
    if (useFreeway) {
        freeway = g_FreewayManager.Find(desire.id);
        if (!freeway) {
            // Log.Add(LOG_ERROR, L"%s : invalid freewayID[%d]", L"CNPC::dMoveFormation", desire.id)
            // Log.Add(LOG_ERROR,
            //     "[formation] Freeway %d was not found. Stopping NPC %u in formation instance %d, template %d.",
            //     desire.id, static_cast<unsigned int>(Id()), desire.uniqueId, desire.formationId)
            L2_LOG_ERROR(
                Log, "[formation] Freeway %d was not found; stopping NPC %u in formation instance %d, template %d.",
                desire.id, static_cast<unsigned int>(Id()), desire.uniqueId, desire.formationId
            );
            return 0;
        }
    } else {
        const std::string graphName = Utf16ToUtf8(std::u16string_view(desire.name));
        graph = l2geo::g_SuperPointManager.Find(desire.name);
        if (!graph) {
            // Log.Add(LOG_ERROR, L"%s : invalid superpoint %s", L"CNPC::dMoveFormation", graphName.c_str())
            // Log.Add(LOG_ERROR,
            //     "[formation] SuperPoint graph '%s' was not found. Stopping NPC %u in formation instance %d, template %d.",
            //     WideToUtf8(graphName).c_str(), static_cast<unsigned int>(Id()), desire.uniqueId, desire.formationId)
            L2_LOG_ERROR(
                Log,
                "[formation] SuperPoint graph '%s' was not found; stopping NPC %u in formation instance %d, template %d.",
                graphName.c_str(), static_cast<unsigned int>(Id()), desire.uniqueId, desire.formationId
            );
            return 0;
        }
        if (graph->GetNodeCount() < 2) {
            const std::string npcName = Utf16ToUtf8(std::u16string_view(npc.GetName()));
            const std::string storedGraphName = Utf16ToUtf8(runtime::StringView(graph->m_Name));
            // Log.Add(
            //     LOG_ERROR,
            //     L"[%s] dMoveFormation [%s] [%s] : "
            //     L"super point node count [%d] < 2",
            //     npcName.c_str(), graphName.c_str(), storedGraphName.c_str(), graph->GetNodeCount()
            // )
            // Log.Add(LOG_ERROR,
            //     "[formation] SuperPoint graph '%s' has %d nodes. At least 2 are required. Stopping NPC '%s' in instance %d
            //     (requested graph '%s').", WideToUtf8(storedGraphName).c_str(), graph->GetNodeCount(),
            //     WideToUtf8(npcName).c_str(), desire.uniqueId, WideToUtf8(graphName).c_str())
            L2_LOG_ERROR(
                Log,
                "[formation] SuperPoint graph '%s' has %d nodes; at least 2 are required. Stopping NPC '%s' in instance %d "
                "(requested graph '%s').",
                storedGraphName.c_str(), graph->GetNodeCount(), npcName.c_str(), desire.uniqueId,
                graphName.c_str()
            );
            return 0;
        }
    }

    CDesire::MoveSuperPointContext& state = desire.m_MoveSuperPointContext;
    const bool atFreewayEnd = useFreeway && state.m_DestIndex + 1 == freeway->GetNodeCount();
    const int previousCallCount = state.m_Revision;
    state.m_Revision = static_cast<int>(static_cast<std::uint32_t>(state.m_Revision) + 1U);

    const auto emitMove = [&](const FVector& destination) { npc.SendMovePacket(destination); };
    const auto emitTeleport = [&](const FVector& destination) {
        npc.InstantTeleport(
            npc.m_data, static_cast<int>(destination.x), static_cast<int>(destination.y), static_cast<int>(destination.z)
        );
    };
    const auto persist = [&](std::uint32_t retryMilliseconds) {
        npc.m_nTimerDelay = static_cast<int>(retryMilliseconds);
        return 1;
    };
    const auto graphPosition = [&](int index) -> std::optional<FVector> {
        if (!graph) {
            return std::nullopt;
        }
        return graph->GetLoc(index);
    };
    const auto routePosition = [&](int index) -> std::optional<FVector> {
        if (useFreeway) {
            CFreewayNode* node = freeway->GetNode(index);
            return node ? std::optional<FVector>(node->position) : std::nullopt;
        }
        return graphPosition(index);
    };
    const auto selectRandomDestination = [&](int fromNode, int& destination) -> bool {
        const int nodeCount = graph->GetNodeCount();
        // SHIPPING BUG SP-HANG-001: CNPC::dMoveFormation at current
        // L2NPC.exe 0x0049897c repeats dMoveSuperPoint's unbounded
        // missing-route search. Preserve the shipping loop as disabled
        // source and reject only graphs for which it can never finish.
        /*
        for (..) {
            const int candidate =
                LegacyCrtRand() % nodeCount.
            if (candidate != fromNode &&
                graph->GetPath(fromNode, candidate)) {
                destination = candidate.
                return true.
            }
        }
        */

        bool hasPublishedDestination = false;
        for (int candidate = 0; candidate < nodeCount; ++candidate) {
            if (candidate == fromNode) {
                continue;
            }
            const int pathKey =
                static_cast<int>((static_cast<std::uint32_t>(fromNode) << 16U) | static_cast<std::uint32_t>(candidate));
            const auto found = graph->m_Paths.find(pathKey);
            if (found != graph->m_Paths.end() && found->second) {
                hasPublishedDestination = true;
                break;
            }
        }

        if (!hasPublishedDestination) {
            const std::string storedGraphName = Utf16ToUtf8(runtime::StringView(graph->m_Name));
            // Log.Add(
            //     LOG_ERROR,
            //     L"%s : no random route from node[%d] "
            //     L"in superpoint[%s]",
            //     L"CNPC::dMoveFormation", fromNode, storedGraphName.c_str()
            // )
            // Log.Add(LOG_ERROR,
            //     "[formation] No published destination is reachable from node %d in SuperPoint graph '%s'. Stopping NPC %u
            //     in formation instance %d.", fromNode, WideToUtf8(storedGraphName).c_str(), static_cast<unsigned
            //     int>(Id()), desire.uniqueId)
            L2_LOG_ERROR(
                Log,
                "[formation] No published destination is reachable from node %d in SuperPoint graph '%s'; stopping NPC %u "
                "in formation instance %d.",
                fromNode, storedGraphName.c_str(), static_cast<unsigned int>(Id()), desire.uniqueId
            );
            return false;
        }

        for (;;) {
            const int candidate = LegacyCrtRand() % nodeCount;
            if (candidate != fromNode && graph->GetPath(fromNode, candidate)) {
                destination = candidate;
                return true;
            }
        }
    };

    if (previousCallCount == 0) {
        CFormationInst* formation = npc.m_pFormationInst;
        if (!formation) {
            if (!formations.InsertNPCToFormation(&npc, desire.uniqueId, desire.formationId, desire.formationIndex, leader)) {
                return 0;
            }
            formation = formations.GetFormationInst(desire.uniqueId);
            if (!formation) {
                return 0;
            }
            npc.m_pFormationInst = formation;
        }

        if (useFreeway) {
            state.m_StartIndex = 0;
            state.m_DestIndex = 1;
            CFreewayNode* first = freeway->GetNode(0);
            if (!first) {
                // Log.Add(
                //     LOG_ERROR, L"%s : invalid freeway nodeID[%d, %d]", L"CNPC::dMoveFormation", desire.id,
                //     state.m_StartIndex
                // )
                // Log.Add(LOG_ERROR,
                //     "[formation] Cannot initialize freeway %d: node index %d is unavailable. Stopping NPC %u in instance
                //     %d.", desire.id, state.m_StartIndex, static_cast<unsigned int>(Id()), desire.uniqueId)
                L2_LOG_ERROR(
                    Log,
                    "[formation] Cannot initialize freeway %d: node index %d is unavailable; stopping NPC %u in instance "
                    "%d.",
                    desire.id, state.m_StartIndex, static_cast<unsigned int>(Id()), desire.uniqueId
                );
                return 0;
            }
            emitTeleport(first->position);
        } else if (desire.contextValue == 1) {
            const int nodeCount = graph->GetNodeCount();
            state.m_StartIndex = LegacyCrtRand() % nodeCount;
            if (!selectRandomDestination(state.m_StartIndex, state.m_DestIndex)) {
                return 0;
            }
            emitTeleport(*graphPosition(state.m_StartIndex));
            state.m_DestPointIndex = 0;
        } else {
            if (desire.contextValue < 0 || desire.contextValue > 3) {
                // Log.Add(
                //     LOG_ERROR, L"%s : invalid method[%I64d]", L"CNPC::dMoveFormation",
                //     static_cast<long long>(desire.contextValue)
                // )
                // Log.Add(LOG_ERROR,
                //     "[formation] SuperPoint mode %lld is outside 0..3. Stopping NPC %u in instance %d.",
                //     static_cast<long long>(desire.contextValue), static_cast<unsigned int>(Id()), desire.uniqueId)
                L2_LOG_ERROR(
                    Log, "[formation] SuperPoint mode %lld is outside 0..3; stopping NPC %u in instance %d.",
                    static_cast<long long>(desire.contextValue), static_cast<unsigned int>(Id()), desire.uniqueId
                );
                return 0;
            }
            const FVector position = npc.m_data->GetPos();
            const int closest = graph->GetClosestIndex(
                static_cast<int>(position.x), static_cast<int>(position.y), static_cast<int>(position.z)
            );
            const int nodeCount = graph->GetNodeCount();
            if (closest < 1) {
                state.m_StartIndex = 0;
                state.m_DestIndex = 1;
            } else {
                state.m_StartIndex = closest;
                state.m_DestIndex = closest + 1;
                if (state.m_DestIndex == nodeCount) {
                    if (desire.contextValue == 0) {
                        state.m_Direction = 1;
                        state.m_DestIndex = closest - 1;
                    } else {
                        state.m_StartIndex = 0;
                        state.m_DestIndex = 1;
                        if (desire.contextValue == 3) {
                            emitTeleport(*graphPosition(0));
                        }
                    }
                }
            }
            state.m_DestPointIndex = 0;
        }

        if (formation && leader && !formation->NextPosSet()) {
            const std::optional<FVector> start = routePosition(state.m_StartIndex);
            const std::optional<FVector> goal = routePosition(state.m_DestIndex);
            if (!start || !goal) {
                // Log.Add(
                //     LOG_ERROR, L"%s : invalid freeway nodeID[%d, %d]", L"CNPC::dMoveFormation", desire.id,
                //     state.m_StartIndex
                // )
                // Log.Add(LOG_ERROR,
                //     "[formation] Cannot initialize route positions %d -> %d (start %s, destination %s). Stopping NPC %u in
                //     instance %d.", state.m_StartIndex, state.m_DestIndex, start ? "present" : "missing", goal ? "present"
                //     : "missing", static_cast<unsigned int>(Id()), desire.uniqueId)
                L2_LOG_ERROR(
                    Log,
                    "[formation] Cannot initialize route positions %d -> %d (start %s, destination %s); stopping NPC %u in "
                    "instance %d.",
                    state.m_StartIndex, state.m_DestIndex, start ? "present" : "missing", goal ? "present" : "missing",
                    static_cast<unsigned int>(Id()), desire.uniqueId
                );
                return 0;
            }
            formation->ReserveNextPos(*start, *goal);
            formation->SetNextPos();
        }
        if (formation && formation->AllNPCLoaded()) {
            formation->GoAll(FPT_GOTO_GOAL);
            formation->SendNodeArrivedEventToAll();
        }
    }

    CFormationInst* formation = npc.m_pFormationInst;
    if (!formation || !formation->AllNPCLoaded()) {
        // Log.Add(LOG_ERROR, L"Who am I? [%d] Where is here? ", npc.m_data->m_nClassID)
        // Log.Add(LOG_WARN,
        //     "[formation] Stopping movement for NPC %u (class %d), instance %d, template %d, slot %d: %s.",
        //     static_cast<unsigned int>(Id()), npc.m_data->m_nClassID, desire.uniqueId, desire.formationId,
        //     desire.formationIndex, formation ? "not all members are loaded" : "formation instance is missing")
        L2_LOG_WARN(
            Log, "[formation] Stopping movement for NPC %u (class %d), instance %d, template %d, slot %d: %s.",
            static_cast<unsigned int>(Id()), npc.m_data->m_nClassID, desire.uniqueId, desire.formationId,
            desire.formationIndex, formation ? "not all members are loaded" : "formation instance is missing"
        );
        return 0;
    }

    const int process = formation->WhereAmI(&npc);
    FVector next{};
    if (process == FPT_GOTO_WAIT) {
        next = formation->GetNextWait(&npc);
    } else if (process == FPT_GOTO_GOAL) {
        next = formation->GetNextGoal(&npc);
    }
    const FVector destination = next;
    if (IsZero(destination)) {
        return persist(100);
    }

    const FVector current = npc.m_data->GetPos();
    if (DistanceXYSquared(current, destination) > 1.0) {
        emitMove(destination);
        return persist(500);
    }

    if (process == FPT_GOTO_WAIT) {
        formation->NotifyArrived(&npc, FPT_ARRIVED_WAIT);
        if (leader && !formation->NextPosReserved()) {
            state.m_WaitedTime = 0;
            if (useFreeway) {
                ++state.m_StartIndex;
                ++state.m_DestIndex;
                if (atFreewayEnd) {
                    if (desire.contextValue == 0) {
                        return 0;
                    }
                    if (desire.contextValue == 1) {
                        state.m_StartIndex = 0;
                        state.m_DestIndex = 1;
                    } else if (desire.contextValue == 2) {
                        state.m_StartIndex = 0;
                        state.m_DestIndex = 1;
                        CFreewayNode* first = freeway->GetNode(0);
                        if (!first) {
                            // Log.Add(
                            //     LOG_ERROR, L"%s : invalid freeway nodeID[%d, %d]", L"CNPC::dMoveFormation", desire.id,
                            //     state.m_StartIndex
                            // )
                            // Log.Add(LOG_ERROR,
                            //     "[formation] Cannot restart freeway %d: node index %d is unavailable. Stopping NPC %u in
                            //     instance %d.", desire.id, state.m_StartIndex, static_cast<unsigned int>(Id()),
                            //     desire.uniqueId)
                            L2_LOG_ERROR(
                                Log,
                                "[formation] Cannot restart freeway %d: node index %d is unavailable; stopping NPC %u in "
                                "instance %d.",
                                desire.id, state.m_StartIndex, static_cast<unsigned int>(Id()), desire.uniqueId
                            );
                            return 0;
                        }
                        emitTeleport(first->position);
                    } else {
                        // Log.Add(
                        //     LOG_ERROR, L"%s:%d  Invalid freeway method %I64d", kNpcSourceFileW, 0x1007,
                        //     static_cast<long long>(desire.contextValue)
                        // )
                        // Log.Add(LOG_ERROR,
                        //     "[formation] Unsupported end mode %lld for freeway %d (expected 0..2), instance %d, NPC %u.
                        //     continuing with updated route indices %d -> %d.", static_cast<long long>(desire.contextValue),
                        //     desire.id, desire.uniqueId, static_cast<unsigned int>(Id()), state.m_StartIndex,
                        //     state.m_DestIndex)
                        L2_LOG_ERROR(
                            Log,
                            "[formation] Unsupported end mode %lld for freeway %d (expected 0..2), instance %d, NPC %u; "
                            "continuing with updated route indices %d -> %d.",
                            static_cast<long long>(desire.contextValue), desire.id, desire.uniqueId,
                            static_cast<unsigned int>(Id()), state.m_StartIndex, state.m_DestIndex
                        );
                    }
                }
            } else {
                state.m_DestPointIndex = 0;
                const int nodeCount = graph->GetNodeCount();
                if (desire.contextValue == 0) {
                    if (state.m_Direction == 0) {
                        ++state.m_StartIndex;
                        ++state.m_DestIndex;
                        if (state.m_DestIndex == nodeCount) {
                            state.m_Direction = 1;
                            state.m_DestIndex = state.m_StartIndex - 1;
                        }
                    } else {
                        --state.m_StartIndex;
                        --state.m_DestIndex;
                        if (state.m_DestIndex == -1) {
                            state.m_Direction = 0;
                            state.m_DestIndex = 1;
                        }
                    }
                } else if (desire.contextValue == 1) {
                    state.m_StartIndex = state.m_DestIndex;
                    if (!selectRandomDestination(state.m_StartIndex, state.m_DestIndex)) {
                        return 0;
                    }
                } else if (desire.contextValue == 2 || desire.contextValue == 3) {
                    ++state.m_StartIndex;
                    ++state.m_DestIndex;
                    if (state.m_DestIndex == nodeCount) {
                        state.m_StartIndex = 0;
                        state.m_DestIndex = 1;
                        if (desire.contextValue == 3) {
                            emitTeleport(*graphPosition(0));
                        }
                    }
                } else {
                    // Log.Add(
                    //     LOG_ERROR, L"%s:%d  Invalid type %I64d", kNpcSourceFileW, 0xfdb,
                    //     static_cast<long long>(desire.contextValue)
                    // )
                    // Log.Add(LOG_ERROR,
                    //     "[formation] Unsupported SuperPoint mode %lld in instance %d, NPC %u. Continuing with route
                    //     indices %d -> %d.", static_cast<long long>(desire.contextValue), desire.uniqueId,
                    //     static_cast<unsigned int>(Id()), state.m_StartIndex, state.m_DestIndex)
                    L2_LOG_ERROR(
                        Log,
                        "[formation] Unsupported SuperPoint mode %lld in instance %d, NPC %u; continuing with route indices "
                        "%d -> %d.",
                        static_cast<long long>(desire.contextValue), desire.uniqueId, static_cast<unsigned int>(Id()),
                        state.m_StartIndex, state.m_DestIndex
                    );
                }
            }

            const std::optional<FVector> start = routePosition(state.m_StartIndex);
            const std::optional<FVector> goal = routePosition(state.m_DestIndex);
            if (!start || !goal) {
                // Log.Add(
                //     LOG_ERROR, L"%s : invalid freeway nodeID[%d, %d]", L"CNPC::dMoveFormation", desire.id,
                //     state.m_StartIndex
                // )
                // Log.Add(LOG_ERROR,
                //     "[formation] Cannot reserve route positions %d -> %d (start %s, destination %s). Stopping NPC %u in
                //     instance %d.", state.m_StartIndex, state.m_DestIndex, start ? "present" : "missing", goal ? "present"
                //     : "missing", static_cast<unsigned int>(Id()), desire.uniqueId)
                L2_LOG_ERROR(
                    Log,
                    "[formation] Cannot reserve route positions %d -> %d (start %s, destination %s); stopping NPC %u in "
                    "instance %d.",
                    state.m_StartIndex, state.m_DestIndex, start ? "present" : "missing", goal ? "present" : "missing",
                    static_cast<unsigned int>(Id()), desire.uniqueId
                );
                return 0;
            }
            formation->ReserveNextPos(*start, *goal);
        }
    } else if (process == FPT_GOTO_GOAL) {
        formation->NotifyArrived(&npc, FPT_ARRIVED_GOAL);
    }

    if (!formation->CheckAllArrived(FPT_ARRIVED_GOAL)) {
        if (formation->CheckAllArrived(FPT_ARRIVED_WAIT)) {
            formation->GoAll(FPT_GOTO_GOAL);
            formation->SetNextPos();
            formation->SendNodeArrivedEventToAll();
        }
    } else {
        formation->GoAll(FPT_GOTO_WAIT);
        formation->SendNodeArrivedEventToAll();
    }
    return persist(100);
}


std::atomic<std::int32_t> g_nNPCSpawnCount{0};
L2TimeInfo g_L2TimeInfo{13, 0, 0};

namespace {

char16_t* DuplicateAIParameterString(const char16_t* text) {
    // Current L2NPC.exe 0x00557f24 is _wcsdup: a null source is returned as
    // null, not normalized to an allocated empty string.
    if (!text) {
        return nullptr;
    }
    const std::size_t length = std::char_traits<char16_t>::length(text);
    auto* const copy = static_cast<char16_t*>(std::calloc(length + 1, sizeof(char16_t)));
    if (copy) {
        std::char_traits<char16_t>::copy(copy, text, length);
    }
    return copy;
}

std::uint64_t PackSkillNameId(int skillId, int skillLevel, int skillSubLevel) {
    const auto signedBits = [](int value) { return static_cast<std::uint64_t>(static_cast<std::int64_t>(value)); };
    return ((signedBits(skillId) << 16) | signedBits(skillLevel)) << 16 | signedBits(skillSubLevel);
}

std::size_t RefTypeIndex(ObjectRefType type) { return static_cast<std::size_t>(type); }

} // namespace

CNPC* CNPC::GetObjectW(int objectId) {
    L2_GUARD_FUNCTION();
    CCreature* object = CCreature::GetObjectW(static_cast<std::uint32_t>(objectId));
    return object && object->IsNPC() ? object->CastNPC() : nullptr;
}

