int CNPC::HandleEvent(CNPCEvent* event) {
    // Current L2NPC.exe 0x0046c3c4.
    L2_GUARD_FUNCTION();
    if (!m_pEventHandler) {
        return 0;
    }
    const int threadId = CThreadManager::GetThreadID();
    g_NPCClassID[threadId][0] = m_data->m_nClassID;
    g_NPCClassID[threadId][1] = event->m_nEventId;
    return m_pEventHandler->InterlockedHandleEvent(event, &m_AIParam);
}

