MemoryObject* CNPC::AddRef(const char* callerFile, int callerLine, ObjectRefType type) {
    runtime::raw_atomic::AddI32(&m_nRefCount, 1);

    RefHelperStruct& record = m_RefHelpers.m_RefData[RefTypeIndex(type)];
    record.m_nRefCount.fetch_add(1, std::memory_order_seq_cst);
    record.m_pAddCaller = callerFile;
    record.m_nAddLine = callerLine;
    return this;
}

std::int32_t CNPC::Release(const char* callerFile, int callerLine, ObjectRefType type, bool) {
    RefHelperStruct& record = m_RefHelpers.m_RefData[RefTypeIndex(type)];
    const std::int32_t subtypeRemaining = record.m_nRefCount.fetch_sub(1, std::memory_order_seq_cst) - 1;
    if (subtypeRemaining < 0) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%S][%d]  sub-type[%s] "
        //     L"sub-reference count[%d] is below zero!",
        //     callerFile, callerLine, ObjectRefTypeName(type), subtypeRemaining
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC lifetime] Release at %s:%d took reference type '%s' below zero (%d) for object %p.",
        //     callerFile ? callerFile : "<unknown>", callerLine, WideToUtf8(ObjectRefTypeName(type)).c_str(),
        //     static_cast<int>(subtypeRemaining), static_cast<void*>(this))
        L2_LOG_ERROR(
            Log, "[NPC lifetime] Release at %s:%d took reference type '%s' below zero (%d) for object %p.",
            callerFile ? callerFile : "<unknown>", callerLine, WideToUtf8(ObjectRefTypeName(type)).c_str(),
            static_cast<int>(subtypeRemaining), static_cast<void*>(this)
        );
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%d]-[%s]  last_add[%S][%d] "
        //     L"last_release[%S][%d]",
        //     record.m_nRefCount.load(std::memory_order_relaxed), ObjectRefTypeName(type), record.m_pAddCaller,
        //     record.m_nAddLine, record.m_pReleaseCaller, record.m_nReleaseLine
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC lifetime] Reference count %d for type '%s': last add %s:%d, last release %s:%d. Object %p.",
        //     record.m_nRefCount.load(std::memory_order_relaxed), WideToUtf8(ObjectRefTypeName(type)).c_str(),
        //     record.m_pAddCaller ? record.m_pAddCaller : "<unknown>", record.m_nAddLine, record.m_pReleaseCaller ?
        //     record.m_pReleaseCaller : "<unknown>", record.m_nReleaseLine, static_cast<void*>(this))
        L2_LOG_ERROR(
            Log, "[NPC lifetime] Reference count %d for type '%s': last add %s:%d, last release %s:%d; object %p.",
            record.m_nRefCount.load(std::memory_order_relaxed), WideToUtf8(ObjectRefTypeName(type)).c_str(),
            record.m_pAddCaller ? record.m_pAddCaller : "<unknown>", record.m_nAddLine,
            record.m_pReleaseCaller ? record.m_pReleaseCaller : "<unknown>", record.m_nReleaseLine, static_cast<void*>(this)
        );
        record.m_pReleaseCaller = callerFile;
        record.m_nReleaseLine = callerLine;
        ReportCallStack(LOG_ERROR, false);
        ReportOrt("NPC.cpp", 0x90);
    } else {
        record.m_pReleaseCaller = callerFile;
        record.m_nReleaseLine = callerLine;
    }

    const std::int32_t remaining = runtime::raw_atomic::AddI32(&m_nRefCount, -1);
    if (remaining == 0) {
        if (!IsInTimer()) {
            DestroyReleasedObject();
        } else {
            if (callerFile) {
                // Log.Add(
                //     LOG_ERROR,
                //     "deleting in-timer-object![CNPC] "
                //     "at file[%s], line[%d]",
                //     callerFile, callerLine
                // )
                // Log.Add(LOG_ERROR,
                //     "[NPC lifetime] Object %p reached zero references at %s:%d while still registered with a timer.
                //     destruction skipped.", static_cast<void*>(this), callerFile, callerLine)
                L2_LOG_ERROR(
                    Log,
                    "[NPC lifetime] Object %p reached zero references at %s:%d while still registered with a timer; "
                    "destruction skipped.",
                    static_cast<void*>(this), callerFile, callerLine
                );
            } else {
                // Log.Add(LOG_ERROR, "deleting in-timer-object![CNPC]")
                // Log.Add(LOG_ERROR,
                //     "[NPC lifetime] Object %p reached zero references while still registered with a timer. Destruction
                //     skipped, caller location unavailable.", static_cast<void*>(this))
                L2_LOG_ERROR(
                    Log,
                    "[NPC lifetime] Object %p reached zero references while still registered with a timer; destruction "
                    "skipped, caller location unavailable.",
                    static_cast<void*>(this)
                );
            }
            ReportOrt("NPC.cpp", 0x90);
        }
        ReleaseClassInstance(L2_MEMORY_CLASS_ID(CNPC));
    } else if (remaining < 0) {
        // Log.Add(LOG_ERROR, "Invalid Memory Ex(%d) on CNPC(%d)", remaining, MemoryObjectID())
        // Log.Add(LOG_ERROR,
        //     "[NPC lifetime] Invalid reference count %d for NPC memory object %d. Reporting reference history.",
        //     remaining, MemoryObjectID())
        L2_LOG_ERROR(
            Log, "[NPC lifetime] Invalid reference count %d for NPC memory object %d; reporting reference history.",
            remaining, MemoryObjectID()
        );
        if (callerFile) {
            // Log.Add(LOG_ERROR, "           Caller : file[%s], line[%d]", callerFile, callerLine)
            // Log.Add(LOG_ERROR,
            //     "[NPC lifetime] Invalid release of object %p originated at %s:%d.",
            //     static_cast<void*>(this), callerFile, callerLine)
            L2_LOG_ERROR(
                Log, "[NPC lifetime] Invalid release of object %p originated at %s:%d.", static_cast<void*>(this),
                callerFile, callerLine
            );
        }
        ReportOrt("NPC.cpp", 0x90);
        ReportCallStack(LOG_ERROR, true);
    }
    return remaining;
}

void CNPC::ReportOrt(const char* callerFile, int callerLine) {
    L2_GUARD_FUNCTION();
    thread_local std::uint32_t npcReportTick = 0;
    ++npcReportTick;
    const int threadId = CThreadManager::GetThreadID();
    int sequence = 1;

    if (callerFile) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[ORT Report][tid:%d][tick:%d][%d] begin "
        //     L"called from file[%S], line[%d] -------------",
        //     threadId, static_cast<int>(npcReportTick), sequence, callerFile, callerLine
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC references] Begin report %u for object %p (thread slot %d, row %d), requested at %s:%d.",
        //     static_cast<unsigned int>(npcReportTick), static_cast<void*>(this), threadId, sequence, callerFile,
        //     callerLine)
        L2_LOG_ERROR(
            Log, "[NPC references] Begin report %u for object %p (thread slot %d, row %d), requested at %s:%d.",
            static_cast<unsigned int>(npcReportTick), static_cast<void*>(this), threadId, sequence, callerFile, callerLine
        );
    } else {
        // Log.Add(
        //     LOG_ERROR,
        //     "[ORT Report][tid:%d][tick:%d][%d] "
        //     "begin ---------------------------",
        //     threadId, static_cast<int>(npcReportTick), sequence
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC references] Begin report %u for object %p (thread slot %d, row %d). Caller location unavailable.",
        //     static_cast<unsigned int>(npcReportTick), static_cast<void*>(this), threadId, sequence)
        L2_LOG_ERROR(
            Log, "[NPC references] Begin report %u for object %p (thread slot %d, row %d); caller location unavailable.",
            static_cast<unsigned int>(npcReportTick), static_cast<void*>(this), threadId, sequence
        );
    }

    for (std::size_t index = 0; index < RefHelpers::kCount; ++index) {
        const RefHelperStruct& record = m_RefHelpers.m_RefData[index];
        if (!record.m_pAddCaller || !record.m_pReleaseCaller || record.m_nRefCount.load(std::memory_order_relaxed) == 0) {
            continue;
        }
        ++sequence;
        // Log.Add(
        //     LOG_ERROR,
        //     L"[ORT Report][tid:%d][tick:%d][%d] "
        //     L"[RefCount:%d]-[%s]  last_add[%S][%d] "
        //     L"last_release[%S][%d]",
        //     threadId, static_cast<int>(npcReportTick), sequence, record.m_nRefCount.load(std::memory_order_relaxed),
        //     ObjectRefTypeName(static_cast<ObjectRefType>(index)), record.m_pAddCaller, record.m_nAddLine,
        //     record.m_pReleaseCaller, record.m_nReleaseLine
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC references] Report %u, thread slot %d, row %d: %d references of type '%s'. Last add %s:%d, last release
        //     %s:%d.", static_cast<unsigned int>(npcReportTick), threadId, sequence,
        //     record.m_nRefCount.load(std::memory_order_relaxed),
        //     WideToUtf8(ObjectRefTypeName(static_cast<ObjectRefType>(index))).c_str(), record.m_pAddCaller,
        //     record.m_nAddLine, record.m_pReleaseCaller, record.m_nReleaseLine)
        L2_LOG_ERROR(
            Log,
            "[NPC references] Report %u, thread slot %d, row %d: %d references of type '%s'; last add %s:%d, last release "
            "%s:%d.",
            static_cast<unsigned int>(npcReportTick), threadId, sequence, record.m_nRefCount.load(std::memory_order_relaxed),
            WideToUtf8(ObjectRefTypeName(static_cast<ObjectRefType>(index))).c_str(), record.m_pAddCaller, record.m_nAddLine,
            record.m_pReleaseCaller, record.m_nReleaseLine
        );
    }

    // Log.Add(
    //     LOG_ERROR,
    //     "[ORT Report][tid:%d][tick:%d][%d] "
    //     "end -----------------------------",
    //     threadId, static_cast<int>(npcReportTick), sequence + 1
    // )
    // Log.Add(LOG_ERROR,
    //     "[NPC references] End report %u for object %p (thread slot %d, row %d).",
    //     static_cast<unsigned int>(npcReportTick), static_cast<void*>(this), threadId, sequence + 1)
    L2_LOG_ERROR(
        Log, "[NPC references] End report %u for object %p (thread slot %d, row %d).",
        static_cast<unsigned int>(npcReportTick), static_cast<void*>(this), threadId, sequence + 1
    );
}

void CNPC::SeeCreatureData(CSharedCreatureData* creature) {
    // Current L2NPC.exe 0x0046bb28.
    L2_GUARD_FUNCTION();
    CNPCEvent* const event = CNPCEventFactory::CreateSeeCreatureEvent(this, creature);
    if (!event) {
        // Log.Add(LOG_ERROR, L"[%s][%d] Event failed", kNpcSourceFileW, 0x5c7)
        // Log.Add(LOG_ERROR,
        //     "[NPC AI] Cannot create the creature-sighting event for NPC %u, creature %u. AI callback skipped.",
        //     static_cast<unsigned int>(Id()), creature ? static_cast<unsigned int>(creature->m_nId) : 0U)
        L2_LOG_ERROR(
            Log, "[NPC AI] Cannot create the creature-sighting event for NPC %u, creature %u; AI callback skipped.",
            static_cast<unsigned int>(Id()), creature ? static_cast<unsigned int>(creature->m_nId) : 0U
        );
        return;
    }
    HandleEvent(event);
    L2_RELEASE(event, ObjectRefType::CreateDelete);
}

void CNPC::SeeCreature(CCreature* creature) {
    // Current L2NPC.exe 0x00489824.
    L2_GUARD_FUNCTION();
    if (m_data->m_SummonType != 1 && m_data->m_SummonType != 2) {
        if (!creature->IsNPC()) {
            return;
        }
        SeeCreatureData(creature->m_data);
        if (!creature->IsVisible() || creature->m_data->m_Race != 0x1d) {
            return;
        }
    } else {
        if (!creature->IsVisible()) {
            return;
        }
        if (creature->IsNPC()) {
            SeeCreatureData(creature->m_data);
        }
    }
    creature->CastNPC()->SeeCreatureData(m_data);
}

void CNPC::Spelled(CSharedCreatureData* speller, int skillId, int skillLevel, int skillSubLevel) {
    // Current L2NPC.exe 0x004b1258.
    L2_GUARD_FUNCTION();
    const std::uint64_t skillNameId = PackSkillNameId(skillId, skillLevel, skillSubLevel);
    const int effectPoint = Skill_GetEffectPoint(runtime::Int64FromBits(skillNameId));

    if (effectPoint < 0) {
        Attacked(speller, runtime::NegateInt32Wrapping(effectPoint), 0, runtime::Int64FromBits(skillNameId), true, 0);
        return;
    }

    CNPCEvent* const event = CNPCEventFactory::CreateSpelledEvent(this, speller, skillId, skillLevel, skillSubLevel);
    if (!event) {
        // Log.Add(LOG_ERROR, L"[%s][%d] Event Create failed", kNpcSourceFileW, 0x42b)
        // Log.Add(LOG_ERROR,
        //     "[NPC AI] Cannot create the spell-received event for NPC %u, caster %u, skill %d/%d/%d. AI callback and party
        //     notification skipped.", static_cast<unsigned int>(Id()), speller ? static_cast<unsigned int>(speller->m_nId) :
        //     0U, skillId, skillLevel, skillSubLevel)
        L2_LOG_ERROR(
            Log,
            "[NPC AI] Cannot create the spell-received event for NPC %u, caster %u, skill %d/%d/%d; AI callback and party "
            "notification skipped.",
            static_cast<unsigned int>(Id()), speller ? static_cast<unsigned int>(speller->m_nId) : 0U, skillId, skillLevel,
            skillSubLevel
        );
        return;
    }
    HandleEvent(event);
    L2_RELEASE(event, ObjectRefType::CreateDelete);

    CNPC* root = CNPC::GetObjectW(m_data->m_BossID);
    if (!root && m_bBoss) {
        root = this;
    }
    if (root) {
        root->PartySpelled(speller, m_data, skillId, skillLevel, skillSubLevel);
    }
}

void CNPC::Attacked(
    CSharedCreatureData* attacker, int damage, int argument, std::int64_t context, bool propagate, int tail
) {
    // Current L2NPC.exe 0x004b10c8.
    L2_GUARD_FUNCTION();
    if (m_nNpcDespawnCount >= 1) {
        return;
    }

    m_nOutOfTerritoryCounter = 0;
    CNPCEvent* const event =
        CNPCEventFactory::CreateAttackedEvent(this, attacker, static_cast<float>(damage), argument, context, tail);
    if (!event) {
        // Log.Add(LOG_ERROR, L"[%s][%d] CreateAttackedEvent failed", kNpcSourceFileW, 0x3e5)
        // Log.Add(LOG_ERROR,
        //     "[NPC AI] Cannot create the attack-received event for NPC %u, attacker %u, damage %d. AI callback and party
        //     notification skipped.", static_cast<unsigned int>(Id()), attacker ? static_cast<unsigned int>(attacker->m_nId)
        //     : 0U, damage)
        L2_LOG_ERROR(
            Log,
            "[NPC AI] Cannot create the attack-received event for NPC %u, attacker %u, damage %d; AI callback and party "
            "notification skipped.",
            static_cast<unsigned int>(Id()), attacker ? static_cast<unsigned int>(attacker->m_nId) : 0U, damage
        );
        return;
    }

    HandleEvent(event);
    L2_RELEASE(event, ObjectRefType::CreateDelete);
    if (!propagate) {
        return;
    }

    CNPC* root = CNPC::GetObjectW(m_data->m_BossID);
    if (!root && m_bBoss) {
        root = this;
    }
    if (root) {
        root->PartyAttacked(attacker, m_data, damage);
    }
}

void CNPC::MakeAttackEvent(CSharedCreatureData* attacker, float damage, int propagate) {
    // Current L2NPC.exe 0x004b15d8.
    L2_GUARD_FUNCTION();
    Attacked(attacker, runtime::Win64CvttDoubleToInt32(static_cast<double>(damage)), 0, 0, propagate != 0, 0);
}

void CNPC::PartyAttacked(CSharedCreatureData* attacker, CSharedCreatureData* privateNpc, int damage) {
    // Current L2NPC.exe 0x004ae708.
    L2_GUARD_FUNCTION();
    CNPCEvent* const event = CNPCEventFactory::CreatePartyAttackedEvent(this, attacker, privateNpc, damage);
    if (!event) {
        // Log.Add(LOG_ERROR, L"[%s][%d] CreateAttackedEvent failed", kNpcSourceFileW, 0x404)
        // Log.Add(LOG_ERROR,
        //     "[NPC AI] Cannot create the party-attack event for NPC %u, attacker %u, victim %u, damage %d. Notification of
        //     this NPC and its children skipped.", static_cast<unsigned int>(Id()), attacker ? static_cast<unsigned
        //     int>(attacker->m_nId) : 0U, privateNpc ? static_cast<unsigned int>(privateNpc->m_nId) : 0U, damage)
        L2_LOG_ERROR(
            Log,
            "[NPC AI] Cannot create the party-attack event for NPC %u, attacker %u, victim %u, damage %d; notification of "
            "this NPC and its children skipped.",
            static_cast<unsigned int>(Id()), attacker ? static_cast<unsigned int>(attacker->m_nId) : 0U,
            privateNpc ? static_cast<unsigned int>(privateNpc->m_nId) : 0U, damage
        );
        return;
    }

    HandleEvent(event);
    L2_RELEASE(event, ObjectRefType::CreateDelete);

    std::set<int> children;
    {
        L2_GUARD(m_PrivatesSect);
        children = m_sPrivates;
    }
    for (const int childId : children) {
        if (CNPC* const child = CNPC::GetObjectW(childId)) {
            child->PartyAttacked(attacker, privateNpc, damage);
        }
    }
}

void CNPC::PartySpelled(
    CSharedCreatureData* speller, CSharedCreatureData* privateNpc, int skillId, int skillLevel, int skillSubLevel
) {
    // Current L2NPC.exe 0x004abf84.
    L2_GUARD_FUNCTION();
    CNPCEvent* event =
        CNPCEventFactory::CreatePartySpelledEvent(this, speller, privateNpc, skillId, skillLevel, skillSubLevel);
    if (!event) {
        // Log.Add(LOG_ERROR, L"[%s][%d] CreateAttackedEvent failed", kNpcSourceFileW, 0x456)
        // Log.Add(LOG_ERROR,
        //     "[NPC AI] Cannot create the party-spell event for NPC %u, caster %u, victim %u, skill %d/%d/%d. Notification
        //     of this NPC and its children skipped.", static_cast<unsigned int>(Id()), speller ? static_cast<unsigned
        //     int>(speller->m_nId) : 0U, privateNpc ? static_cast<unsigned int>(privateNpc->m_nId) : 0U, skillId,
        //     skillLevel, skillSubLevel)
        L2_LOG_ERROR(
            Log,
            "[NPC AI] Cannot create the party-spell event for NPC %u, caster %u, victim %u, skill %d/%d/%d; notification of "
            "this NPC and its children skipped.",
            static_cast<unsigned int>(Id()), speller ? static_cast<unsigned int>(speller->m_nId) : 0U,
            privateNpc ? static_cast<unsigned int>(privateNpc->m_nId) : 0U, skillId, skillLevel, skillSubLevel
        );
        return;
    }

    HandleEvent(event);
    L2_RELEASE(event, ObjectRefType::CreateDelete);

    std::set<int> children;
    {
        L2_GUARD(m_PrivatesSect);
        children = m_sPrivates;
    }
    for (const int childId : children) {
        CNPC* const child = CNPC::GetObjectW(childId);
        if (!child) {
            continue;
        }

        event = CNPCEventFactory::CreatePartySpelledEvent(this, speller, privateNpc, skillId, skillLevel, skillSubLevel);
        if (!event) {
            // Log.Add(LOG_ERROR, L"[%s][%d] Event failed", kNpcSourceFileW, 0x46f)
            // Log.Add(LOG_ERROR,
            //     "[NPC AI] Cannot create the party-spell event from NPC %u for child %u, skill %d/%d/%d. Skipping this
            //     child and continuing notification.", static_cast<unsigned int>(Id()), static_cast<unsigned int>(childId),
            //     skillId, skillLevel, skillSubLevel)
            L2_LOG_ERROR(
                Log,
                "[NPC AI] Cannot create the party-spell event from NPC %u for child %u, skill %d/%d/%d; skipping this child "
                "and continuing notification.",
                static_cast<unsigned int>(Id()), static_cast<unsigned int>(childId), skillId, skillLevel, skillSubLevel
            );
            continue;
        }
        child->HandleEvent(event);
        L2_RELEASE(event, ObjectRefType::CreateDelete);
    }
}

