bool CNPC::CanAct() {
    // Current L2NPC.exe 0x00484a60.
    L2_GUARD_FUNCTION();
    if (m_data->m_cNoSleepMode == 0 && g_bSilentWhenNoUser && m_data->m_nInstantZoneID == 0) {
        const SharedLong nearbyUsers = SharedUserMapDensity::Inst().CountByPos(m_data->m_Pos);
        if (nearbyUsers == 0) {
            m_nCanActState = 0;
            return false;
        }
    }

    m_nCanActState = 1;
    return true;
}

bool CNPC::AddAttackDesireEx(int targetObjectId, int attackMoveType, int force, float value) {
    // Current L2NPC.exe 0x00499b44.
    L2_GUARD_FUNCTION();
    if (!m_data->m_bIsActive || !m_data->m_bIsAlive || m_data->GetHP() <= 0.0 || !CanAct()) {
        return false;
    }

    if (m_data->IsSummonOrPet()) {
        // The current target reads +0x3588 here. The donor PDB calls that
        // field m_BossID. For summon types 1/2 L2Server publishes the owning
        // User id in the same slot. CNPC::GetMaster uses the separate safe
        // pointer at +0x3568 in other call paths.
        const int masterObjectId = m_data->m_BossID;
        if (targetObjectId == masterObjectId) {
            return false;
        }
        // CNPC calls User::GetObjectW here, so a non-User creature with the
        // same object id is not an acceptable summon master.
        if (!User::GetObjectW(masterObjectId)) {
            return false;
        }
    }

    // const int targetKind = static_cast<int>(static_cast<std::uint32_t>(targetObjectId) >> 27)
    const int targetKind = static_cast<int>(static_cast<std::uint32_t>(targetObjectId) >> CLASS_SHIFT);
    CCreature* targetObject = nullptr;
    CSharedCreatureData* target = nullptr;
    int levelDifference = 0;
    int targetMasterObjectId = 0;
    int targetMasterLevelDifference = 0;

    // if (targetKind == 9) {
    if (targetKind == SCLS_CREATURE) {
        targetObject = CCreature::GetObjectW(static_cast<std::uint32_t>(targetObjectId));
        // The target keeps a desire for an unresolved kind-9
        // id. Validation happens only when CCreature::GetObject returns a
        // process-local object at the time this method runs.
        if (targetObject) {
            target = targetObject->m_data;
            if (targetObject == this || !target->m_bIsActive || !target->m_bIsAlive || target->GetHP() <= 0.0 ||
                !targetObject->IsTargetable()) {
                return false;
            }

            const int reverseHate = runtime::Win64CvttDoubleToInt32(std::fabs(static_cast<double>(value)));
            if (g_nMaxChaseCount < 1) {
                targetObject->AddReverseHate(static_cast<std::uint32_t>(Id()), reverseHate);
            } else {
                ReverseHateManager::inst().AddHate(
                    static_cast<std::uint32_t>(targetObject->Id()), static_cast<std::uint32_t>(Id())
                );
            }

            levelDifference = target->m_nLevel - m_data->m_nLevel;

            if (targetObject->IsNPC()) {
                CNPC* const typeNpc = targetObject->CastNPC();
                if (typeNpc->m_data->IsSummon()) {
                    CNPC* const masterNpc = targetObject->CastNPC();
                    CCreature* const targetMasterObject = masterNpc->GetMaster();
                    if (targetMasterObject) {
                        CSharedCreatureData* const targetMaster = targetMasterObject->m_data;
                        if (targetMaster->m_bIsActive && targetMaster->m_bIsAlive && targetMaster->GetHP() >= 0.0) {
                            targetMasterObjectId = static_cast<int>(targetMasterObject->Id());
                            targetMasterLevelDifference = targetMaster->m_nLevel - m_data->m_nLevel;
                        }
                    }
                }
            }
        }
    }

    const float boost = m_AIParam.GetDesireBoostValue(DESIRE_ATTACK);
    CDesire attackDesire = CDesireFactory::MakeAttack(
        targetObjectId, static_cast<NpcAttackMoveType>(attackMoveType), force != 0, value, boost, levelDifference
    );
    attackDesire.deadlineTick = std::numeric_limits<std::uint32_t>::max();
    if (targetMasterObjectId > 0) {
        CDesire masterAttackDesire = CDesireFactory::MakeAttack(
            targetMasterObjectId, static_cast<NpcAttackMoveType>(attackMoveType), force != 0,
            value >= 0.0f ? 5.0f : -5.0f, boost, targetMasterLevelDifference
        );
        // The donor repeats the same deadline assignment at 0x00499e63.
        masterAttackDesire.deadlineTick = std::numeric_limits<std::uint32_t>::max();
        m_DesirePQ.AddValue(masterAttackDesire);
    }

    int topChanged = 0;
    m_DesirePQ.AddValue(attackDesire, topChanged);
    GuardHelper attackDesireEventCallStack(L"add_attack_desire_event", CThreadManager::GetThreadID());
    if (topChanged == 0) {
        return true;
    }

    FVector targetPosition{};
    double targetRadius = 0.0;
    // if (targetKind == 9) {
    if (targetKind == SCLS_CREATURE) {
        targetObject = CCreature::GetObjectW(static_cast<std::uint32_t>(targetObjectId));
        if (!targetObject) {
            return true;
        }
        target = targetObject->m_data;
        targetPosition = target->GetPos();
        targetRadius = target->m_dCollisionRadius;
        // } else if (targetKind == 11) {
    } else if (targetKind == SCLS_STATIC_OBJECT) {
        const int staticObjectIndex = static_cast<int>(static_cast<std::uint32_t>(targetObjectId) & 0x000fffffU);
        const CSharedStaticObjectData* staticObject = CStaticObjectFactory::Inst().GetData(staticObjectIndex);
        if (!staticObject) {
            return true;
        }
        targetPosition = staticObject->GetPos();
        targetRadius = staticObject->m_dCollisionRadius;
    } else {
        return true;
    }

    if (!CanAttackEx(targetRadius, targetPosition, static_cast<NpcAttackMoveType>(attackMoveType))) {
        return true;
    }

    g_ns.Send("cdddd", 0x06, m_data->index, targetObjectId, attackMoveType, force);
    return true;
}

bool CNPC::AddAttackDesire(CSharedCreatureData* target, int attackMoveType, float value) {
    // Current L2NPC.exe 0x0049a050.
    L2_GUARD_FUNCTION();
    return target && AddAttackDesireEx(target->m_nId, attackMoveType, 1, value);
}

