void CNPC::OnCreate() {
    // Current L2NPC.exe 0x004a8de4.
    L2_GUARD_FUNCTION();
    ResetDesirePQ();
    m_nSpawnTick = runtime::GetTickCount();
    m_nSpawnTime = runtime::crt::Time32Now();

    if (CNPC* const parent = CNPC::GetObjectW(m_data->m_BossID); parent && m_data->m_SummonType == 0) {
        parent->PrivateCreated(static_cast<int>(Id()));
        boss = parent->m_data;
    }

    // Current L2NPC.exe 0x004a8de4 stores the virtual GetName result
    // directly in Serializer::m_pOwnerName at CNPC +0x1368.
    Serializer.SetOwnerName(GetName());
}

bool CNPC::Delete() {
    // Current L2NPC.exe 0x004960e0.
    L2_GUARD_FUNCTION();
    // Exact first phase: restore every still-live private's process-local
    // boss pointer to shared creature slot zero. L2Server remains
    // authoritative for shared boss_id.
    if (m_bBoss) {
        L2_GUARD(m_PrivatesSect);
        for (const int childId : m_sPrivates) {
            CNPC* const child = CNPC::GetObjectW(childId);
            if (child) {
                child->boss = CCreatureFactory::Inst().GetData(0);
            }
        }
    }

    if (!CCreature::Delete()) {
        return false;
    }
    SaveDie();
    m_pSpawnDefine->OnNpcDeleted(this);
    base_structure_detail::AtomicIncrement(&NpcSpawnInfo::Inst()->Npc_Delete);
    return true;
}

void CNPC::Died() {
    // Current L2NPC.exe 0x0046b5dc.
    L2_GUARD_FUNCTION();
    if (m_data->m_BossID != 0) {
        base_structure_detail::AtomicIncrement(&NpcSpawnInfo::Inst()->Npc_OnPrivateDie);
    }
}

