int CNPC::GetNPCLogByID(CSharedCreatureData* creature, int questId, int logType, int npcId) {
    L2_GUARD_FUNCTION();
    if (!creature) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(
        //     LOG_ERROR,
        //     L"Script:GetNPCLog : "
        //     L"pCreature == NULL!!!, npc[%s]",
        //     npcName.c_str()
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC quest] Cannot read counter for quest %d, type %d, NPC key %d: creature is missing in the script call
        //     from NPC '%s' (%u). Returning zero.", questId, logType, npcId, WideToUtf8(npcName).c_str(),
        //     static_cast<unsigned int>(Id()))
        L2_LOG_ERROR(
            Log,
            "[NPC quest] Cannot read counter for quest %d, type %d, NPC key %d: creature is missing in the script call from "
            "NPC '%s' (%u); returning zero.",
            questId, logType, npcId, npcName.c_str(), static_cast<unsigned int>(Id())
        );
        return 0;
    }
    return creature->GetUserNPCLog(questId, npcId, static_cast<UserNPCLogType>(logType));
}

void CNPC::IncreaseNPCLog(CSharedCreatureData* creature, int questId, int logType, int maximum) {
    L2_GUARD_FUNCTION();
    const int npcLogId = runtime::Int32FromBits(static_cast<std::uint32_t>(m_data->m_nClassID) - 1000000U);
    IncreaseNPCLogByID(creature, questId, logType, npcLogId, maximum);
}

void CNPC::IncreaseNPCLogByID(CSharedCreatureData* creature, int questId, int logType, int npcId, int maximum) {
    L2_GUARD_FUNCTION();
    if (!creature) {
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(
        //     LOG_ERROR,
        //     L"Script:IncreaseNPCLog : "
        //     L"pCreature == NULL!!!, npc[%s]",
        //     npcName.c_str()
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC quest] Cannot increase counter for quest %d, type %d, NPC key %d (limit %d): creature is missing in the
        //     script call from NPC '%s' (%u). Update skipped.", questId, logType, npcId, maximum,
        //     WideToUtf8(npcName).c_str(), static_cast<unsigned int>(Id()))
        L2_LOG_ERROR(
            Log,
            "[NPC quest] Cannot increase counter for quest %d, type %d, NPC key %d (limit %d): creature is missing in the "
            "script call from NPC '%s' (%u); update skipped.",
            questId, logType, npcId, maximum, npcName.c_str(), static_cast<unsigned int>(Id())
        );
        return;
    }

    const int current = creature->GetUserNPCLog(questId, npcId, static_cast<UserNPCLogType>(logType));
    if (current >= maximum) {
        return;
    }

    const int value = creature->IncreaseUserNPCLog(questId, npcId, static_cast<UserNPCLogType>(logType), maximum);
    g_ns.Send("cddcdd", 0xe0, static_cast<int>(creature->m_nId), questId, logType, npcId, value);

    CLogFormatter formatter;
    formatter.WriteLogNpc1(0x80, *this, creature, nullptr, nullptr, questId, npcId, value, 0, 0, 0, 0);
}

void CNPC::ReportAIClassHierarchy(int builderObjectId) {
    // Current L2NPC.exe 0x004ace30.
    L2_GUARD_FUNCTION();
    std::u16string report(u"ai class hierachy");
    CNPCEventHandler* generation = m_pEventHandler ? m_pEventHandler->m_pRealHandler : nullptr;
    while (generation) {
        report += u"\r\n[";
        report += std::u16string_view(generation->GetAIClassName());
        report += u"]";
        generation = GetSuperEventHandler(generation);
    }

    g_ns.Send("cdS", 0x54, builderObjectId, report.c_str());
}

bool CNPC::EnterWorld() {
    // Current L2NPC.exe 0x004b256c.
    L2_GUARD_FUNCTION();
    if (m_nNpcDespawnCount > 0) {
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] Enter world to despawned "
        //     L"NPC[RefCount:%d]",
        //     kNpcSourceFileW, 0x67b, RefCount()
        // )
        // Log.Add(LOG_ERROR,
        //     "[NPC lifecycle] World entry requested for despawned NPC %u (despawn count %d, references %d). Dumping
        //     reference history and continuing entry checks.", static_cast<unsigned int>(Id()), m_nNpcDespawnCount,
        //     RefCount())
        L2_LOG_ERROR(
            Log,
            "[NPC lifecycle] World entry requested for despawned NPC %u (despawn count %d, references %d); dumping "
            "reference history and continuing entry checks.",
            static_cast<unsigned int>(Id()), m_nNpcDespawnCount, RefCount()
        );
        ReportOrt("NPC.cpp", 0x67c);
    }

    // Exact NPC.cpp:0x686 branch: a live instant-zone maker that is already
    // deleting rejects entry at the CNPC layer, latches Despawn, and
    // prevents the spawn definition's OnNpcEnterWorld virtual call.
    l2npc::NpcMakerEx* const maker = GetMyMaker();
    if (maker && maker->GetInZoneDeleteCount() != 0 && maker->GetInZoneID() != 0) {
        Despawn();
        const std::string npcName = Utf16ToUtf8(GetName());
        // Log.Add(
        //     LOG_ERROR,
        //     L"[%s][%d] npc enter world while inzone is "
        //     L"being deleted[%s]",
        //     kNpcSourceFileW, 0x686, npcName.c_str()
        // )
        // Log.Add(LOG_WARN,
        //     "[NPC lifecycle] World entry rejected for NPC '%s' (%u): instance %u is being deleted. NPC marked for
        //     despawn.", WideToUtf8(npcName).c_str(), static_cast<unsigned int>(Id()), maker->GetInZoneID())
        L2_LOG_WARN(
            Log,
            "[NPC lifecycle] World entry rejected for NPC '%s' (%u): instance %u is being deleted; NPC marked for despawn.",
            npcName.c_str(), static_cast<unsigned int>(Id()), maker->GetInZoneID()
        );
        return false;
    }

    const std::uint32_t now = runtime::GetTickCount();
    m_DecayLastTick = now;
    m_nTimerDelay = static_cast<std::uint32_t>(gGlobalObj.Rand(2000) + 1000);
    m_nDecayingCounter = 0;
    m_nCorpseCounter = 0;

    CSharedCreatureData* const data = m_data;
    if (!data) {
        {
            // GetDBName returns by value in the target. Keep this scope so
            // its temporary is destroyed after CLog::Add and before the
            // virtual ReportOrt call.
            const std::u16string dbName = GetDBName();
            const std::string dbNameText = Utf16ToUtf8(runtime::StringView(dbName));
            // The shipping branch assumes GetMyMaker succeeded and directly
            // passes the maker's embedded name. Do not fabricate a null
            // maker substitution on this invariant-failure path.
            const std::string makerName = Utf16ToUtf8(std::u16string_view(maker->GetName()));
            const int referenceCount = RefCount();
            // Log.Add(
            //     LOG_ERROR,
            //     L"[%s][%d] npc[%s] enter world but "
            //     L"m_data is null. maker[%s] refcount[%d]",
            //     kNpcSourceFileW, 0x699, dbNameText.c_str(), makerName.c_str(), referenceCount
            // )
            // Log.Add(LOG_ERROR,
            //     "[NPC lifecycle] Cannot enter world for NPC %u, DB name '%s', maker '%s': shared data is missing
            //     (references %d), dumping reference history and raising a fatal assertion.", static_cast<unsigned
            //     int>(Id()), WideToUtf8(dbNameText).c_str(), WideToUtf8(makerName).c_str(), referenceCount)
            L2_LOG_ERROR(
                Log,
                "[NPC lifecycle] Cannot enter world for NPC %u, DB name '%s', maker '%s': shared data is missing "
                "(references %d); dumping reference history and raising a fatal assertion.",
                static_cast<unsigned int>(Id()), dbNameText.c_str(), makerName.c_str(),
                referenceCount
            );
        }
        ReportOrt("NPC.cpp", 0x69b);
        EASSERT();
    }

    const FVector position = data->GetPos();
    __x = runtime::Win64CvttDoubleToInt32(position.x);
    __y = runtime::Win64CvttDoubleToInt32(position.y);
    __z = runtime::Win64CvttDoubleToInt32(position.z);
    // The target first truncates CSharedCreatureData::x/y/z into the three
    // CNPC integer fields and only then converts those integers back to
    // double for prev_pos.
    prev_pos = {static_cast<double>(__x), static_cast<double>(__y), static_cast<double>(__z)};
    bInMyTerritory = true;

    // AddTimer(this, m_nTimerDelay) in the Windows CIO timer queue.
    AddTimer(m_nTimerDelay, 0);
    const int currentEnterWorldCount [[maybe_unused]] = runtime::raw_atomic::AddI32(&m_nEnterWorldCount, 1);
    base_structure_detail::AtomicIncrement(&NpcSpawnInfo::Inst()->Npc_EnterWorld);
    return true;
}

