void CNPC::ChangePetMoveMode(int mode, FVector position) {
    // Current L2NPC.exe 0x00496bc0.
    L2_GUARD_FUNCTION();
    CDesire key = CDesireFactory::MakePetDefault();
    L2_GUARD(m_DesirePQSect);
    CDesire* current = nullptr;
    if (m_DesirePQ._GetDesire(key, current) == 0) {
        _AddPetDefaultDesire_Follow(100.0F);
        if (m_DesirePQ._GetDesire(key, current) == 0) {
            // Log.Add(LOG_ERROR, L"[%s][%d] TogglePetMoveMode failed", L"NPC.cpp", 0x5ed)
            // Log.Add(LOG_ERROR,
            //     "[pet] Cannot set movement mode %d for NPC %u: the default action is still missing after queuing follow.
            //     mode change skipped.", mode, static_cast<unsigned int>(Id()))
            L2_LOG_ERROR(
                Log,
                "[pet] Cannot set movement mode %d for NPC %u: the default action is still missing after queuing follow; "
                "mode change skipped.",
                mode, static_cast<unsigned int>(Id())
            );
            return;
        }
    }

    if (mode != 0) {
        current->contextValue = 0;
        return;
    }

    CCreature* const masterObject = GetMaster();
    if (!masterObject) {
        return;
    }
    CSharedCreatureData* const master = masterObject->m_data;
    const FVector npcPosition = m_data->GetPos();
    const FVector masterPosition = master->GetPos();
    const double deltaX = masterPosition.x - npcPosition.x;
    const double deltaY = masterPosition.y - npcPosition.y;
    const double deltaZ = masterPosition.z - npcPosition.z;
    const int distance = runtime::Win64CvttDoubleToInt32(std::sqrt(deltaX * deltaX + deltaY * deltaY + deltaZ * deltaZ));
    const int maximumDistance = GetOption(0);
    if (maximumDistance > 0 && maximumDistance < distance) {
        return;
    }
    current->contextValue = 1;
    current->position = position;
}

void CNPC::TogglePetMoveMode() {
    // Current L2NPC.exe 0x00496e2c.
    L2_GUARD_FUNCTION();
    CDesire key = CDesireFactory::MakePetDefault();
    L2_GUARD(m_DesirePQSect);
    CDesire* current = nullptr;
    if (m_DesirePQ._GetDesire(key, current) == 0) {
        AddPetDefaultDesire_Follow(100.0F);
        if (m_DesirePQ._GetDesire(key, current) == 0) {
            // Log.Add(LOG_ERROR, L"[%s][%d] TogglePetMoveMode failed", L"NPC.cpp", 0x61d)
            // Log.Add(LOG_ERROR,
            //     "[pet] Cannot toggle movement mode for NPC %u: the default action is still missing after queuing follow.
            //     mode change skipped.", static_cast<unsigned int>(Id()))
            L2_LOG_ERROR(
                Log,
                "[pet] Cannot toggle movement mode for NPC %u: the default action is still missing after queuing follow; "
                "mode change skipped.",
                static_cast<unsigned int>(Id())
            );
            return;
        }
    }

    if (current->contextValue != 0) {
        current->contextValue = 0;
        return;
    }

    CCreature* const masterObject = GetMaster();
    if (!masterObject) {
        return;
    }
    CSharedCreatureData* const master = masterObject->m_data;
    const FVector npcPosition = m_data->GetPos();
    const FVector masterPosition = master->GetPos();
    const double deltaX = masterPosition.x - npcPosition.x;
    const double deltaY = masterPosition.y - npcPosition.y;
    const double deltaZ = masterPosition.z - npcPosition.z;
    const int distance = runtime::Win64CvttDoubleToInt32(std::sqrt(deltaX * deltaX + deltaY * deltaY + deltaZ * deltaZ));
    const int maximumDistance = GetOption(0);
    if (maximumDistance > 0 && maximumDistance < distance) {
        return;
    }

    current->contextValue = 1;
    current->position = m_data->GetPos();
}

bool CNPC::SetSkillFired(std::int64_t skillNameId, int targetObjectId, int successNotification) {
    // Current L2NPC.exe 0x004ae56c.
    L2_GUARD_FUNCTION();
    {
        L2_GUARD(m_SkillSect);
        m_mapSkillFiredTick[skillNameId] = runtime::GetTickCount();
    }

    if (successNotification > 0) {
        CCreature* const targetObject = CCreature::GetObjectW(static_cast<std::uint32_t>(targetObjectId));
        if (targetObject) {
            SpellSuccessed(targetObject->m_data, skillNameId);
        }
    }

    L2_GUARD(m_DesirePQSect);
    if (m_DesirePQ._IsDQEmpty()) {
        return false;
    }
    CDesire& top = m_DesirePQ._GetTopDesire();
    if (top.type != DESIRE_USE_SKILL || top.contextValue != skillNameId) {
        return false;
    }
    top.firedByServer = true;
    return true;
}

