void CNPC::RemoveAllHateInfoIF(int condition, int value) {
    // Current L2NPC.exe 0x004b04bc.
    L2_GUARD_FUNCTION();
    HateInfoList* const list = GetCurrentHateInfoList();

    switch (condition) {
        case 0:
            list->RemoveAllHateInfo();
            break;
        case 1:
            list->RemoveAllIF([](const auto& entry) {
                CSharedCreatureData* const creature = entry.second.GetCreature();
                return !creature || !creature->m_bIsAlive || !creature->m_bIsActive || creature->GetHP() <= 0.0;
            });
            break;
        case 2:
            list->RemoveAllIF([value](const auto& entry) {
                return entry.second.HateValue() < static_cast<std::int64_t>(value);
            });
            break;
        case 3: {
            const FVector origin = m_data->GetPos();
            const std::uint32_t valueBits = static_cast<std::uint32_t>(value);
            const int squaredRange = runtime::Int32FromBits(valueBits * valueBits);
            list->RemoveAllIF([origin, squaredRange](const auto& entry) {
                CSharedCreatureData* const creature = entry.second.GetCreature();
                if (!creature) {
                    return true;
                }
                const double gateDz = creature->m_Pos.z - origin.z;
                const int integerDz = runtime::Win64CvttDoubleToInt32(gateDz);
                const int absoluteDz = integerDz < 0 ? runtime::NegateInt32Wrapping(integerDz) : integerDz;
                if (absoluteDz > 500) {
                    return true;
                }
                const double dx = creature->m_Pos.x - origin.x;
                const double dy = creature->m_Pos.y - origin.y;
                const double dz = creature->m_Pos.z - origin.z;
                const double distance = dx * dx + dy * dy + dz * dz;
                return distance > static_cast<double>(squaredRange);
            });
        } break;
        default:
            // Log.Add(
            //     LOG_ERROR,
            //     L"[%s][%d] RemoveAllHateInfoIF. "
            //     L"Invalid condition[%d]",
            //     L"NPC.cpp", 0x383c, condition
            // )
            // Log.Add(LOG_ERROR,
            //     "[NPC AI] NPC %u cannot filter hate entries with condition %d (value %d): condition is outside 0..3. Hate
            //     entries unchanged.", static_cast<unsigned int>(Id()), condition, value)
            L2_LOG_ERROR(
                Log,
                "[NPC AI] NPC %u cannot filter hate entries with condition %d (value %d): condition is outside 0..3; hate "
                "entries unchanged.",
                static_cast<unsigned int>(Id()), condition, value
            );
            break;
    }
}

